t.guides["forever/alliance/02-westfall"] = (function() return {
		["Back north past {area:918} to the mine: Kobold Diggers work inside."] = "Обратно на север мимо фермы ({area:918}) к руднику: внутри работают кобольды-землекопы.",
		["Back to {zone:1453}"] = "Обратно: {zone:1453}",
		["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}. {object:1166} stands in the farmhouse at the {area:219}, among them: {npc:1646}' compass is inside.\nCareful: The {area:113} cave holds many Defias packed together, so it is easy to pull several at once there."] = "Погромщики и мошенники из Братства Справедливости занимают фермы к западу (ориентир: {area:108}), между прибрежной дорогой и поселением {area:20}. Среди них, в доме на ферме ({area:219}), стоит {object:1166}: внутри компас, который ищет {npc:1646}.\nОсторожно: в пещере ({area:113}) много членов Братства стоят плотно, там легко выманить сразу нескольких.",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Волшебники-плуты из Братства Справедливости стоят лагерем на берегах ({area:86}); с них падают и красные льняные банданы. {object:56} лежит в деревне мурлоков на северо-восточном берегу.",
		["Defias Trappers and Smugglers"] = "Ловчие и контрабандисты из Братства Справедливости",
		["East along the road past {area:18}: {npc:248242} and {npc:248248} stand at the foot of the tower."] = "На восток по дороге мимо {area:18}: {npc:248242} и {npc:248248} стоят у подножия башни.",
		["East along the road, then into the river south of the bridge: the {item:247813}, Axe and Toolbox lie in it. Prowlers and Young Forest Bears roam its banks."] = "На восток по дороге, затем в реку к югу от моста: в ней лежат {item:247813}, топор и ящик с инструментами. По ее берегам бродят бродяги и молодые лесные медведи.",
		["Every Defias on this loop can drop a {item:829}: the Trappers and Smugglers, and the guards at {object:290}."] = "С любого члена Братства Справедливости на этом круге может выпасть {item:829}: с ловчих и контрабандистов, а также со стражей у {object:290}.",
		["Fill the vial at the farm's well"] = "Наполните склянку у колодца фермы",
		["Fill the vial at the well"] = "Наполните склянку у колодца",
		["Finish the Goretusk Livers"] = "Доберите печень жутевепря",
		["Finish the {item:729}"] = "Доберите: {item:729}",
		["Finish the {quest:153}"] = "Завершите: {quest:153}",
		["Fleshrippers circle the fields along this loop: kill the ones you pass for the stew's meat."] = "Над полями вдоль этого круга кружат шкуродеры: убивайте встречных ради мяса для рагу.",
		["Follow the hills south to the tower."] = "Идите по холмам на юг к башне.",
		["Follow the road from Elwynn into {zone:1436}: the Furlbrows sit by their burned farm, the first one on the road. Pick up oats from any {object:2724} you pass on the loop: the rest are gathered in the fields here on the way back."] = "Следуйте по дороге из Элвиннского леса в Зону {zone:1436}: супруги Хмуробров сидят у своей сгоревшей фермы — первой по дороге. Собирайте овес из каждого предмета {object:2724} по пути: остальное соберете на полях здесь на обратном пути.",
		["Follow the road west to {area:87}, on the way to {zone:1436}: {npc:240} stands outside the inn."] = "Идите по дороге на запад до {area:87}, по пути в {zone:1436}: {npc:240} стоит у таверны.",
		["For {npc:266} in {area:69}, Redridge"] = "Для NPC {npc:266} ({area:69}, Красногорье)",
		["Gnoll Paws"] = "Лапы гнолла",
		["Goretusk Livers as you go"] = "Печень жутевепря по пути",
		["Goretusk Snouts"] = "Рыла жутевепря",
		["Goretusks and Young Goretusks root along every leg of this loop: kill the ones you pass for the pie's livers."] = "Жутевепри и молодые жутевепри роются на каждом отрезке этого круга: убивайте встречных ради печени для пирога.",
		["Harvest Watchers"] = "Дозорные полей",
		["Harvest Watchers and Golems work the fields around {area:918}; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone."] = "Дозорные полей и големы работают на полях вокруг {area:918}; с них падают изопружины, гиростабилизаторы, {item:732} и иногда {item:255155}. Здесь ходит {npc:573}, редкий противник 20 уровня: не трогайте его.",
		["Head to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "Отправляйтесь в {zone:1453}. Там нет учителя шаманов: от {object:28027} сядьте на {area:2257} до {zone:1455}, обучитесь у {npc:258098}, затем вернитесь на трамвае к кораблю.",
		["In through the main gate (already done if you are in the city)"] = "Войдите через главные ворота (уже сделано, если вы в городе)",
		["It lies by the river north-west of the logging camp."] = "Оно лежит у реки к северо-западу от лесозаготовок.",
		["Kobold Diggers"] = "Кобольды-землекопы",
		["Level 12, 14 and 16 spells"] = "Заклинания 12, 14 и 16-го уровней",
		["Longshore Murloc Gills"] = "Жабры мурлока с Бескрайнего берега",
		["Murloc Coastrunners and Raiders line the north coast from above the mine east toward the {area:916}: work along the beach eastward. They flee at low health: pull one at a time."] = "Мурлоки-береговики и мурлоки-налетчики занимают северное побережье от места над рудником на восток до {area:916}: двигайтесь по пляжу на восток. При низком здоровье они убегают: выманивайте по одному.",
		["North to the hills above {area:111}: Riverpaw Gnolls and Scouts (level 11-13) roam there, east toward the {area:916}. The gnolls further south and west are 13-19: stay in the north hills.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer."] = "На север, к холмам над {area:111}: там бродят гноллы и разведчики Речной Лапы (11-13 уровень), на восток до {area:916}. Гноллы дальше к югу и западу — 13-19 уровня: держитесь северных холмов.\nОсторожно: гноллы, стоящие рядом, обычно вступают в бой группой. Безопаснее выманивать по одному.",
		["North-west from {area:108} toward {area:918}: Defias Trappers and Smugglers camp in the fields between them."] = "На северо-запад от {area:108} к {area:918}: ловчие и контрабандисты из Братства Справедливости стоят лагерем в полях между ними.",
		["On the road from {zone:1453} to {zone:1436}, {area:87} is the first stop: {npc:241} stands outside the inn, {npc:240} beside him. {npc:241}'s {quest:40} goes straight to Dughan, who then gives {quest:35}; his {quest:109} goes with you to {zone:1436}."] = "По дороге из {zone:1453} в {zone:1436} первая остановка – {area:87}: {npc:241} стоит у таверны, {npc:240} рядом с ним. Задание {npc:241} {quest:40} сдается прямо Дугану, который затем дает {quest:35}; его задание {quest:109} вы возьмете с собой в {zone:1436}.",
		["Only if you looted a {item:1972} in Elwynn: right-click it"] = "Только если вы добыли в Элвиннском лесу предмет {item:1972}: щелкните по нему правой кнопкой",
		["Red Linen Bandanas"] = "Красные льняные банданы",
		["Ride the tram back: it comes out in {zone:1453}'s {object:28027}, where the errands below start."] = "Вернитесь на поезде: он прибывает в город {zone:1453}, сюда: {object:28027}. Отсюда начинаются поручения ниже.",
		["Right-click the {item:6775} he gives you"] = "Щелкните правой кнопкой по предмету {item:6775}, который он даст",
		["Riverpaw Miners"] = "Шахтеры из стаи Речной Лапы",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Гноллы из стаи Речной Лапы стоят лагерем на холмах к западу (ориентир: {area:86}); {quest:91725} лежат в их лагерях.",
		["Sacks of Oats in the fields around the farm"] = "Мешки овса на полях вокруг фермы",
		["Shaman training"] = "Обучение шамана",
		["South along the road, past the fork. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west. Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way."] = "На юг вдоль дороги, мимо развилки. {npc:233} стоит снаружи, {npc:235} — в доме, {npc:253395} — в амбаре к западу. Молодые жутевепри и шкуродёры бродят по полям вокруг фермы: по пути начните собирать печень и мясо для похлёбки.",
		["South-west to the coast, west of {area:918}. Riverpaw Miners work the quarry."] = "На юго-запад к побережью, к западу от фермы ({area:918}). В карьере работают шахтеры из стаи Речной Лапы.",
		["Still short of eight? Young Goretusks root in the fields just west of {area:107}."] = "Не хватает до восьми? Молодые жутевепри роются в полях сразу к западу от {area:107}.",
		["Still short of fifteen? Defias Trappers camp in the fields just west of {area:108}."] = "Не хватает до пятнадцати? Ловчие из Братства Справедливости стоят лагерем в полях сразу к западу от {area:108}.",
		["Still short of three? Young Fleshrippers circle the fields north-west of {area:107}."] = "Не хватает до трех? Молодые шкуродеры кружат над полями к северо-западу от {area:107}.",
		["The bridge"] = "Мост",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "Лагерь – к северо-востоку от моста. Вязанки дров лежат вокруг лагеря и в лесу к северу от него.",
		["The gnoll camps"] = "Лагеря гноллов",
		["The gnoll hills"] = "Холмы гноллов",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: {npc:471} (7-10), the Mine Spiders (7-9) and {npc:248474} (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend."] = "Рудник – к юго-западу от лагерей гноллов. {item:247816} лежат у входа; туннели занимают кобольды-геоманты.\nОсторожно: {npc:471} (7-10), рудниковые пауки (7-9) и {npc:248474} (7) – элитные противники в глубине рудника: выманивайте кобольдов по одному у входа и отступайте, если подходит элитный; с другом проще.",
		["The {area:113}"] = "{area:113}",
		["The {area:2} murlocs"] = "Мурлоки ({area:2})",
		["The {area:54}'s entrance"] = "Вход в {area:54}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["Tram to {zone:1455}"] = "Поезд до {zone:1455}",
		["Walk to {area:1519}, or fly if you know its flight path. Trainers: {object:2100} (Warriors, Rogues), the Cathedral (Paladins, Priests), the {object:2101} (Mages, Warlocks), the {object:28027} (Hunters), the Park (Druids)."] = "Идите в {area:1519} или летите, если знаете этот маршрут полета. Учителя: {object:2100} (воины, разбойники), собор (паладины, жрецы), {object:2101} (маги, чернокнижники), {object:28027} (охотники), парк (друиды).",
		["Walk to {zone:1453}. {npc:376} is in the Cathedral of Light."] = "Идите в город {zone:1453}. {npc:376} – в Соборе Света.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Раз уж вы здесь: изучите владение посохами у NPC {npc:11867} ({object:2096}, 10 серебра); у оружия ближнего боя охотника важнее всего характеристики, а у двуручного их больше всего.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Раз уж вы здесь: изучите владение посохами у NPC {npc:11867} ({object:2096}, 10 серебра); при прокачке посох дает больше характеристик для заклинаний, чем одноручное оружие.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Раз уж вы здесь: изучите владение мечами у NPC {npc:11867} ({object:2096}, 10 серебра); с мечом в правой руке разбойник стабильно качается.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "Раз уж вы здесь: изучите навык {spell:202} у NPC {npc:11867} ({object:2096}, 10 серебра); с двуручным оружием паладин качается быстрее всего.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Раз уж вы здесь: изучите {spell:202} у NPC {npc:11867} ({object:2096}, 10 серебра); с двуручным оружием воин качается быстрее всего.",
		["Young Goretusks root in the fields along the road south from Saldean's to {area:108}: take their snouts on the way."] = "Молодые жутевепри роются в полях вдоль дороги на юг от фермы Сальденов до {area:108}: по пути собирайте их рыла.",
		["{area:108}'s tower and {npc:523}"] = "Башня на {area:108} и {npc:523}",
		["{area:20}: kill these as you meet them"] = "{area:20}: убивайте этих по пути",
		["{area:54}: kill these as you meet them"] = "{area:54}: убивайте их по пути",
		["{area:918}'s Harvest Watchers"] = "Дозорные полей ({area:918})",
		["{area:918}'s well"] = "Колодец ({area:918})",
		["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "{item:2449} для задания «Сбор лекарственных ингредиентов» (6123), {zone:1439}: {npc:1313}, товары для алхимиков; травники вместо этого собирают его там сами",
		["{item:2998}, from {object:1166}"] = "{item:2998} – из объекта {object:1166}",
		["{item:6529}, from {npc:5494}"] = "{item:6529}: продает {npc:5494}",
		["{item:729} as you go"] = "{item:729} по пути",
		["{item:729}: Fleshrippers"] = "{item:729}: шкуродеры",
		["{item:814}: keep five for {npc:392} at the {area:115}, later on the route"] = "{item:814}: оставьте пять для NPC {npc:392} ({area:115}), позже по маршруту",
		["{npc:1323}, {object:2156} in {object:2100}"] = "{npc:1323}, лавка «Ограниченный иммунитет» в {object:2100}",
		["{npc:1416}: his package for {npc:1343} in {zone:1432}, later on the route"] = "{npc:1416}: его посылка для {npc:1343} (зона {zone:1432}), позже по маршруту",
		["{npc:1646}, {object:2098}: his compass is in his old house in {zone:1436}"] = "{npc:1646}, {object:2098}: его компас – в его старом доме в {zone:1436}",
		["{npc:234} and {npc:821} stand at the top of the stone tower, {npc:491} inside it, {npc:523} the gryphon master on the south side of the hill with {npc:878} beside him. {npc:523} gives you Lewis' note for {npc:1323} with a free flight to {zone:1453}: take it now. In {zone:1453}, {npc:279}'s shop is in the {object:2096} by the gryphons, {npc:1323}'s shop, {object:2156}, in {object:2100}; {npc:1646} stands in {object:2098} on the way back to {npc:352}, the gryphon master."] = "{npc:234} и {npc:821} стоят на вершине каменной башни, {npc:491} – внутри нее, {npc:523}, распорядитель грифонов, – на южной стороне холма, рядом с ним {npc:878}. {npc:523} отдает вам записку Льюиса для {npc:1323} и бесплатный полет в {zone:1453}: летите сейчас. В {zone:1453} лавка {npc:279} находится в {object:2096} у грифонов, лавка {npc:1323}, лавка «Ограниченный иммунитет», – в {object:2100}; {npc:1646} стоит на {object:2098}, по пути обратно к {npc:352}, распорядителю грифонов.",
		["{npc:234} and {npc:821} stand at the top of the stone tower. {npc:491} is in the tower, {npc:878} on the south side of the hill, next to the inn and {npc:523} the gryphon master."] = "{npc:234} и {npc:821} стоят на вершине каменной башни. {npc:491} – в башне; {npc:878} – на южном склоне холма, рядом с таверной и укротителем грифонов (это {npc:523}).",
		["{npc:235}, inside"] = "{npc:235} – внутри",
		["{npc:237}: Humans may have it already from {npc:963} in Elwynn"] = "{npc:237}: у людей это задание может уже быть – от {npc:963} в Элвинне",
		["{npc:240}: for {npc:234} at {area:108}"] = "{npc:240}: для {npc:234} на {area:108}",
		["{npc:253092}, beside {npc:878}"] = "{npc:253092} – рядом с NPC {npc:878}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it. His tools and Thomas's Prowlers and bears are south of the bridge, on the way back."] = "{npc:261} охраняет мост на дороге на восток; {npc:248265} стоит сразу за ним. Его инструменты, а также бродяги и медведи для Томаса – к югу от моста, по пути обратно.",
		["{npc:278}, inside"] = "{npc:278}, внутри",
		["{npc:279}, {object:2096}, by the gryphons"] = "{npc:279}, {object:2096}, у грифонов",
		["{npc:352}, the gryphon master"] = "{npc:352}, распорядитель грифонов",
		["{npc:476} walks around {area:54}: look inside the circle on the map"] = "{npc:476} ходит здесь: {area:54}: ищите внутри круга на карте",
		["{npc:491}, inside"] = "{npc:491} – внутри",
		["{npc:491}, inside: back from {zone:1453}"] = "{npc:491}, внутри: по возвращении из {zone:1453}",
		["{npc:523}: the free flight he offers goes to {zone:1453}"] = "{npc:523}: бесплатный полет, который он предлагает, ведет в {zone:1453}",
		["{npc:5480} trains warriors in {object:2100}, near {npc:1323}'s shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480} обучает воинов здесь: {object:2100}, рядом с лавкой NPC {npc:1323}; трамвай из города {zone:1455} прибывает сюда: {object:28027}, к северу от него. {npc:6089} и {npc:6090} стоят там вместе рядом с заведением {object:2152}. {npc:6090} дерется с вами за свою кружку. Если {npc:5480} не предлагает задание {quest:1638}, идите прямо к NPC {npc:6089}: он дает {quest:1639} и без него.",
		["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494} продает рыболовные принадлежности у канала, чуть западнее (ориентир: {object:2096}); {npc:267118} рыбачит в гавани, по пути к кораблю.",
		["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}, Святилище волшебника: {quest:1861}",
		["{npc:6171} and {npc:6173} are in the Cathedral of Light; {npc:6174} stands in the {object:2096} and asks for ten {item:2589} (humanoids drop it; the Auction House sells it)."] = "{npc:6171} и {npc:6173} – в Соборе Света; {npc:6174} стоит здесь: {object:2096}; она просит десять шт. {item:2589} (падает с гуманоидов; продается на аукционе).",
		["{npc:6172}, by {area:86} in Elwynn, on the road to Redridge"] = "{npc:6172} – у {area:86} в Элвиннском лесу, на дороге в Красногорье",
		["{npc:7232}, {object:28027}: for his brother in {area:442}"] = "{npc:7232}, {object:28027}: для его брата в {area:442}",
		["{npc:878}, beside {npc:523}"] = "{npc:878}, рядом с {npc:523}",
		["{object:290} stands in the ruined house east of the mine, on the way to the {area:916}.\nCareful: Two Defias stand guard inside, one of them the level 15 named {npc:502}. They are linked, so attacking either one brings both."] = "{object:290} стоит в разрушенном доме к востоку от рудника, по пути к {area:916}.\nОсторожно: внутри на страже двое членов Братства, один из них — именной противник 15 уровня {npc:502}. Они связаны: нападение на одного привлекает обоих.",
		["{object:290}; inside"] = "{object:290}; внутри",
		["{quest:153} as you go"] = "{quest:153} по пути",
		["{zone:1453}'s {object:28027}"] = "{zone:1453}: {object:28027}",
} end)()
t.guides["forever/alliance/03-darkshore"] = (function() return {
		["At the {area:2362}"] = "Здесь: {area:2362}",
		["Back north-east into the mountains to the crystal."] = "Назад на северо-восток, в горы, к кристаллу.",
		["Bears and the Blackwood camp"] = "Медведи и лагерь Чернолесья",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "Землепроходцы и заклинатели ветра из племени Чернолесья занимают лагерь к юго-востоку (ориентир: {area:442}).",
		["Blackwood furbolgs"] = "Фурболги Чернолесья",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Поднимитесь в горы к востоку (ориентир: {area:447}); {object:175524} лежит на уступе.",
		["Crawler Legs"] = "Ножки краба",
		["East of Buzzbox 323, {npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}.\nCareful: Dark Strand Voidcallers (28-29) with their voidwalkers and {npc:3660} (31) stand in the tower itself: take the parchments from the Fanatics south of it and keep away from the tower."] = "К востоку от Жужжалки 323 {npc:3661} прячется у подножия башни среди фанатиков из клана Темной Нити. Сохраните его письмо для Делгрена Очистителя ({zone:1440}).\nОсторожно: призыватели Бездны из клана Темной Нити (28-29) со своими демонами Бездны и {npc:3660} (31) стоят в самой башне: добудьте пергаменты у фанатиков к югу от нее и держитесь подальше от башни.",
		["Fill the tube at the moonwell in the village"] = "Наполните пробирку у лунного колодца в деревне",
		["Fly from {area:442} to {area:702} and take the portal up to {npc:4217} in the {area:1658}."] = "Летите: {area:442} → {area:702}, и поднимитесь через портал; там {npc:4217} ({area:1658}).",
		["Follow the hills north to the {area:456} and up to the falls. Two more beached remains lie on the north shore: near the {area:443} and north of {quest:954}."] = "Идите вдоль холмов на север к реке ({area:456}) и вверх к водопаду. Еще два выброшенных на берег останка лежат на северном побережье: у руин ({area:443}) и к северу от руин ({quest:954}).",
		["Grell Earrings"] = "Серьги грелля",
		["Highborne Relics"] = "Реликвии высокорожденных",
		["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "Убивайте бешеных колючешерстных медведей на холмах к востоку (ориентир: {area:442}), затем поднимитесь к лагерю фурболгов к юго-востоку от них: убивать там пока никого не нужно.",
		["Moonstalker Fangs"] = "Клыки лунопарда",
		["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower."] = "Лунопарды рыщут по холмам между руинами ({quest:954}) и башней. {quest:1002} стоит на холме к западу от башни.",
		["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {quest:1001} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "На север вдоль холмов. {npc:3650} ждет в руинах ({quest:954}); там полно диких греллей и коварных греллей, на восточном краю – сатиры из племени Дет'рилл. {quest:1001} стоит у дороги к западу от руин; по пути к нему на берегу лежит существо ({quest:4723}).",
		["Plagued bears"] = "Больные медведи",
		["Rabid Thistle Bears roam the hills just east of {area:442}. Use {quest:2139} on one and lead it back to him."] = "Бешеные колючешерстные медведи бродят по холмам чуть восточнее (ориентир: {area:442}). Примените на одном предмет из задания «{quest:2139}» и приведите медведя к нему.",
		["Read the {object:17188}"] = "Прочитайте: {object:17188}",
		["Read the {object:17189}"] = "Прочитайте: {object:17189}",
		["The WANTED poster outside the inn"] = "Плакат «РАЗЫСКИВАЕТСЯ» у таверны",
		["The bay wrecks"] = "Затонувшие корабли в заливе",
		["The beach"] = "Пляж",
		["The cave and the {npc:6788}"] = "Пещера и {npc:6788}",
		["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls."] = "Пещера – к югу от водопада: ножки струпника растут по всей пещере, {item:5270} – в самой глубине. {npc:6788} живет в холмах к югу от водопада.",
		["The flame burns in the south of {area:447}."] = "Пламя горит в южной части руин ({area:447}).",
		["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "Половинки подвески находятся здесь: {zone:1439} и {zone:1436} – дальше по маршруту",
		["The red crystal"] = "Красный кристалл",
		["The skeletal turtle"] = "Скелет черепахи",
		["The {object:16393}"] = "{object:16393}",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Прибрежные крабы снуют по берегу под деревней; {quest:983} стоит на пляже чуть южнее пристани. На мелководье плавают крепкозубы Темного берега. {object:175207} лежит на берегу чуть южнее деревни.",
		["{item:12237} from {npc:2233} and {npc:2235}, by this stop"] = "{item:12237}: с существ {npc:2233} и {npc:2235} рядом с этой точкой",
		["{item:12238}: fish from the pier"] = "{item:12238}: ловите с пристани",
		["{item:12349}, at the waterfall"] = "{item:12349} – у водопада",
		["{item:12355}, in {object:177624}"] = "{item:12355}: {object:177624}",
		["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845}: у входа в пещеру у водопада",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}: из объекта {object:177785} в озере",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: сатиры из племени Дет'рилл",
		["{item:5348}: Dark Strand Fanatics"] = "{item:5348}: фанатики из клана Темной Нити",
		["{npc:10216}, on the pier"] = "{npc:10216} – на пристани",
		["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} in the north-west, use it there and speak to {npc:11799}. {quest:29} runs on a timer: no teleport or Hearthstone until {npc:11799} has it. Then fly back to {area:442} from {area:2361}."] = "{npc:11802} стоит на верхнем этаже своего здания ({area:2361}): поднимитесь внутри, стрелка не различает этажи. Безделушки из святилища лежат в контейнерах на дне озера ({area:656}) ниже деревни ({area:2361}): отнесите одну на северо-запад ({area:2362}), используйте ее там и поговорите: {npc:11799}. У задания {quest:29} есть таймер: никаких телепортов и Камня возвращения, пока его не примет {npc:11799}. Затем летите обратно ({area:2361} → {area:442}).",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639} стоит у северного края руин. Там обитают проклятые, терзаемые высокорожденные и {npc:2178}; среди них бродит призрак – {npc:3667}, к востоку кружит сова {npc:270196}. Обе скрижали лежат в руинах; {quest:4722} – на берегу к западу от них.",
		["{npc:3644}, on the pier"] = "{npc:3644} – на пристани",
		["{npc:3649}, north end of the village"] = "{npc:3649} – в северной части деревни",
		["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}: для персонажа {npc:1646} ({zone:1453})",
		["{npc:3666}, upstairs in the inn"] = "{npc:3666} – на втором этаже таверны",
		["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122}: наполните пробоотборник здесь: {area:445}",
} end)()
t.guides["forever/alliance/03-darkshore-return"] = (function() return {
		["Back south"] = "Назад на юг",
		["Back to {npc:11802}"] = "Назад к {npc:11802}",
		["Back to {npc:11802} in {area:2361}, then {npc:11800} there flies Druids straight to {area:702}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Назад: {npc:11802} ({area:2361}), затем {npc:11800} там же отправит друидов прямо сюда: {area:702}. {npc:11802} стоит на верхнем этаже своего здания: поднимитесь внутри, стрелка не различает этажи.",
		["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "Выведите ее из глефы; задание сдается Тересиль ({zone:1440})",
		["Fine Moonstalker Pelts"] = "Прекрасные шкуры лунопарда",
		["Follow the coast north-east to the {area:443}. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore."] = "Идите вдоль побережья на северо-восток ({area:443}). {quest:951} лежат среди руин; их охраняют мирмидоны, колдуньи и воины из клана Гремучей Чешуи, а по берегу ходят повелительницы зверей из клана Гремучей Чешуи.",
		["Follow the road north."] = "Идите по дороге на север.",
		["Grizzled Scalps"] = "Седые скальпы",
		["Grizzled Thistle Bears roam the hills around the Grove; {quest:1003} stands west of it among them."] = "Седые колючешерстные медведи бродят по холмам вокруг Рощи; {quest:1003} стоит к западу от нее, среди них.",
		["Moonstalker Sires prowl the woods around the glaive. The {object:12666} sits at the bottom of the crater; {npc:3584} stands on its north side. For {quest:948}'s quest, use the {item:5251} at the bottom of the crater: it makes the {object:10076}, and you hand the quest in to the bowl."] = "Взрослые лунопарды рыщут в лесу вокруг глефы. {object:12666} – на дне кратера; {npc:3584} стоит на его северной стороне. Для задания {quest:948} примените {item:5251} на дне кратера: так появится {object:10076}, и задание сдается чаше.",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "Ночные эльфы летят ({area:442} → {area:702}); небеснорожденные плывут на корабле от пристани ({area:442}) и там узнают маршрут полета Деревни Рут'теран. Поднимитесь через портал; там {npc:4217} ({area:1658}).",
		["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "Только если с послушника или лиходея упал предмет {item:5352}: щелкните по нему правой кнопкой",
		["She gives you the {item:15826}"] = "Она дает вам предмет {item:15826}",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "Лунный Плеснецвет растет в пещерах лунных совухов на холмах чуть восточнее (ориентир: {area:442}); совухи там раздражительны. Для предмета {item:2449} нужен навык {skill:182}: травники собирают его по всей зоне {zone:1439}, остальные привозят его из города {zone:1453} ({npc:1313}) или с аукциона.",
		["The WANTED poster"] = "Плакат «РАЗЫСКИВАЕТСЯ»",
		["The naga"] = "Наги",
		["The relics of the Barrow Dens"] = "Реликвии Келий Малфуриона",
		["The {area:443}"] = "{area:443}",
		["The {object:10076}"] = "{object:10076}",
		["The {object:12666}"] = "{object:12666}",
		["{item:15851} and {item:2449}"] = "{item:15851} и {item:2449}",
		["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883}: {object:177792} под водой у северного побережья, к западу от руин",
		["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279}: послушники и лиходеи из культа Сумеречного Молота",
		["{npc:10323}'s beach"] = "Пляж: {npc:10323}",
		["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "{npc:11802} стоит на верхнем этаже своего здания ({area:2361}): поднимитесь внутри, стрелка не различает этажи.",
		["{npc:11802}: the welcome from Sheldras"] = "{npc:11802}: приветствие от Шельдраса Лунное Древо",
		["{npc:12298}: use the {item:15826} on them; they roam all of {zone:1439}"] = "{npc:12298}: примените на них {item:15826}; они бродят по всей зоне {zone:1439}",
		["{npc:3616}, at the Grove"] = "{npc:3616} – в Роще",
		["{npc:6667} hides on the little island off the ruins. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom)."] = "{npc:6667} прячется на островке у руин. Части ключа падают с гигантских лесных долгоногов (верх), мурлоков из племени Серой Мглы (середина) и гневных рифовых крабов (низ).",
		["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "{quest:87760}: {npc:10219} дает это задание, когда сданы все девять выброшенных на берег останков",
		["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394} (ночные эльфы) и {npc:272054} (небеснорожденные) ждут на юге ({area:493}). Три реликвии лежат к востоку от них ({area:2363}). По отчетам первых недель, реликвия не дает добычи, пока ее обыскивает другой игрок: подождите немного и попробуйте снова.",
} end)()
t.guides["forever/alliance/03-loch-modan"] = (function() return {
		["Boat to {area:150}"] = "Корабль: {area:150}",
		["Cathedral of Light"] = "Собор Света",
		["Defias Pathstalkers and Knuckledusters walk {area:20}; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. {area:1581} entrance in the smithy is a group dungeon.\nCareful: The camps in the hills hold mixed groups of Defias, so it is easy to pull more than one at a time if you are low level."] = "По поселению {area:20} ходят налетчики и кастетники из Братства Справедливости; проходимцы (17-й уровень) патрулируют парами холмы к югу и востоку от него: выманивайте их поодиночке. Вход в {area:1581} в кузнице ведет в групповое подземелье.\nОсторожно: в лагерях на холмах стоят смешанные группы Братства, при низком уровне легко выманить нескольких сразу.",
		["Fly to {area:1537}"] = "Лететь в {area:1537}",
		["Fly to {zone:1453}"] = "Лететь в {zone:1453}",
		["Sell and repair in {area:442} first: the next stretch is a long one."] = "Сначала продайте добычу и почините снаряжение ({area:442}): дальше долгий путь.",
		["Through the South Gate tunnel and west along the road to {zone:1455}. Know the {zone:1455} flight path already? Fly from {area:144} instead: these two waypoints drop once you are in the city."] = "Через туннель Южных врат и на запад по дороге в {zone:1455}. Точка полета {zone:1455} уже открыта? Тогда летите из места {area:144}: эти две путевые точки исчезнут, как только вы окажетесь в городе.",
		["Use the {item:6866} on {npc:6172}"] = "Используйте {item:6866}. Цель: {npc:6172}",
		["You have the {area:1537} flight path from {zone:1426}: back north to {area:144}'s gryphons, quicker than walking through the tunnel and across {zone:1426}."] = "Точка полета {area:1537} у вас уже есть ({zone:1426}): вернитесь на север к грифонам ({area:144}) – так быстрее, чем идти через туннель и по землям {zone:1426}.",
		["{area:144} flight master"] = "Распорядитель полетов: {area:144}",
		["{area:20} and the Defias hills"] = "{area:20} и холмы Братства Справедливости",
		["{item:254676}, from the crates around {area:20}"] = "{item:254676}: из ящиков вокруг поселения {area:20}",
		["{item:280911}: Redridge Thrashers"] = "{item:280911}: твердозубы из стаи Красногорья",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}: волшебники-плуты из Братства Справедливости",
		["{npc:1343}: {npc:1416}'s package"] = "{npc:1343}: посылка от {npc:1416}",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}, {object:32372}",
