t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "Назад на юг мимо Эрнестуэя: пантеры и ящеры Тернистой долины бегают по полянам к западу от лагеря в сторону побережья; старые тигры занимают холмы на юго-западе.",
		["Both roam the grass around the camp and along the road north."] = "И те и другие бродят по траве вокруг лагеря и вдоль дороги на север.",
		["Down to {area:35}"] = "Вниз: {area:35}",
		["Druid training"] = "Обучение друида",
		["Fly to {zone:1453}"] = "Лететь в {zone:1453}",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "Идите по главной дороге на юг через все джунгли, мимо поворота на {object:3202}, до южного мыса: {area:35}.",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "Из зоны {zone:1431} идите по дороге на юг в Тернистую долину; палатки охотников стоят сразу к западу от дороги, за поворотом к лагерю ({area:99}).",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Барабуль, редкий мурлок на побережье к западу от лагеря, роняет предмет {item:4614}: заберите его, если встретите",
		["Panthers, raptors and elder tigers"] = "Пантеры, ящеры и старые тигры",
		["River Crocolisks swim the river by the {area:99}."] = "Речные кроколиски плавают в реке у места {area:99}.",
		["River crocolisks"] = "Речные кроколиски",
		["Stranglethorn Tigers"] = "Тигры Тернистой долины",
		["Take the road north; the camp sits in the hills to the west.\n{npc:738} offers {quest:215} only while he is out of the camp: about every half hour he walks down the path to the road, where two Kurzen's Agents ambush him. Help him kill them and take the quest at once, before he walks back up. He isn't there? Leave it: the guide passes {quest:200}, which follows from it, as well."] = "Идите по дороге на север; лагерь – в холмах к западу.\n{npc:738} предлагает задание {quest:215}, только пока находится вне лагеря: примерно раз в полчаса он спускается по тропе к дороге, где на него из засады нападают двое посланников Курцена. Помогите ему убить их и сразу возьмите задание, пока он не ушел обратно наверх. Его там нет? Оставьте задание: гайд пропустит и {quest:200}, которое из него следует.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Взрослые тигры рыщут по холмам сразу к югу и западу от лагеря.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Старые тигры – позже, на обратном пути от лагеря ({area:99})",
		["The haunted island"] = "Остров духов",
		["Young tigers and panthers"] = "Молодые тигры и пантеры",
		["{item:190309}, north of {area:413}"] = "{item:190309}, к северу (ориентир: {area:413})",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}: из ящика ({object:263})",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496} – наверху в таверне",
		["{npc:469}, in the hut"] = "{npc:469} – в хижине",
		["{npc:715}, from {zone:1441}"] = "{npc:715}: из зоны {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} собирает страницы ({item:2755}): они падают почти со всех гуманоидов в джунглях. По ходу дела собирайте из страниц главы.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} и ящеры-кнутохвосты",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "{npc:729}, огромный тигр, живет на вершине холма к юго-западу от лагеря; ящеры-кнутохвосты бегают к югу от него, по пути в {area:35}.",
		["{npc:737}, in the tavern"] = "{npc:737} – в таверне",
		["{npc:738}, at the foot of the path"] = "{npc:738} – у подножия тропы",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: просто осмотритесь в лагере охотников",
} end)()
t.guides["forever/alliance/30-40/04b-stranglethorn-vale"] = (function() return {
		["East to the {area:99}, on the way back to Nesingwary's camp."] = "На восток в {area:99}, по пути обратно в лагерь Эрнестуэя.",
		["East to {area:101}: Herod's records lie in a hut on its west side."] = "На восток к лагерю ({area:101}): записи Херода лежат в хижине на его западной стороне.",
		["For Archmage Ansirem in {zone:1416}"] = "Для верховного мага Ансарема (зона {zone:1416})",
		["For characters of 35 to 36, but several quests here are level 37-41: on purpose, for their experience. {quest:205}'s Skullsplitter trolls are 39-42, so pull them one at a time."] = "Для персонажей 35-36 уровня, но несколько заданий здесь 37-41 уровня: намеренно, ради опыта. Тролли из племени Дробителей Черепов в задании {quest:205} – 39-42 уровня, так что выманивайте их по одному.",
		["North along the coast to the ruins on the hill: the last two tablets lie there. Pick up Green Hills pages as they drop."] = "На север вдоль побережья к руинам на холме: там лежат две последние таблички. Подбирайте выпадающие страницы «Зеленых холмов».",
		["Skullsplitter trolls"] = "Тролли из племени Дробителей Черепов",
		["Snapjaw Crocolisks"] = "Кроколиски-хрустогрызы",
		["South from the compound to {area:37}: the Venture Co. Geologists in the camps on its shore carry the Tumbled Crystals, and the Shadowmaw Panthers prowl stealthed in the jungle south and east of it."] = "От лагеря на юг к озеру ({area:37}): упавшие кристаллы носят геологи Торговой компании из лагерей на его берегу, а тенебрюхие пантеры в незаметности рыщут в джунглях к югу и востоку от него.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Тролли из племени Дробителей Черепов занимают руины к востоку от дороги между лагерем Эрнестуэя и местом {object:3202}.",
		["The haunted island lies just off the shore west of the second tablet: the Lesser Water Elementals rise from the water around it."] = "Остров с призраками лежит у самого берега к западу от второй таблички: из воды вокруг него поднимаются малые элементали воды.",
		["The jungle ruins"] = "Руины в джунглях",
		["The {area:102}"] = "{area:102}",
		["West across the jungle to the troll ruins: each holds one stone tablet of the troll legends, the first two in the ruins south-west of Nesingwary's camp, the last two on the hill in the north-west."] = "На запад через джунгли к руинам троллей: в каждых лежит одна каменная табличка с легендами троллей, первые две – в руинах к юго-западу от лагеря Эрнестуэя, последние две – на холме на северо-западе.",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496} – наверху в таверне",
		["{npc:718}: the Shadowmaw Panthers prowl around {area:37}, after {area:101}"] = "{npc:718}: тенебрюхие пантеры рыщут вокруг озера ({area:37}), после лагеря ({area:101})",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}: для NPC {npc:773} ({area:35})",
		["{npc:773}, upstairs: this optional quest needs four {item:4278}. Mine Lesser Bloodstone Deposits in {zone:1417} with {skill:186} 75, or buy the ore at the Auction House or ask a miner friend. The kobolds do not drop it; skip this quest if you cannot get the ore."] = "{npc:773} – наверху: для этого необязательного задания нужно четыре шт. {item:4278}. Добывайте руду из малых месторождений кровавого камня в зоне {zone:1417} с навыком {skill:186} 75, купите ее на аукционе или попросите друга-шахтера. Кобольды ее не роняют; пропустите задание, если не можете достать руду.",
		["{zone:1453} flight master"] = "Распорядитель полетов: {zone:1453}",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks stealthed on the edge of {area:271}, and few players find him. If you spot him, kill him and read the contract he carries: {npc:2276} takes it. Don't wait for him: the rest of this step doesn't need him."] = "{npc:2434} скрывается в незаметности на окраине места {area:271}, и мало кто его находит. Если заметите его, убейте и прочитайте контракт, который он несет: его примет {npc:2276}. Не ждите его: остальной части шага он не нужен.",
		["Back west through {zone:1430} to {area:42}."] = "Обратно на запад через {zone:1430} сюда: {area:42}.",
		["Below ground"] = "Под землей",
		["Crushridge ogres"] = "Огры из клана Раздробленного Хребта",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals. {quest:1392} walks a long path through the ruins: if you meet him, kill him, his cudgel starts a quest for {npc:1776}. Don't wait for him."] = "На восток по дороге сюда: {area:76}. Кристаллы падают с противников {npc:256028}. {quest:1392} ходит по руинам длинным маршрутом: если встретите его, убейте – его дубина начинает задание для NPC {npc:1776}. Не ждите его специально.",
		["East from {quest:681} across the north of the Highlands; the shards glitter on the hill by the {area:333}, north of {area:314}."] = "На восток от места {quest:681} через север нагорья; осколки сверкают на холме у места {area:333}, к северу от места {area:314}.",
		["Fly to {area:271}"] = "Летите сюда: {area:271}",
		["Fly to {area:42}"] = "Летите сюда: {area:42}",
		["Fly to {zone:1453}"] = "Летите сюда: {zone:1453}",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "Идите по дороге на восток из места {area:287} через {area:1057} сюда: {area:320}.",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings. {npc:2306} (40) turns up in one spot at a time: the cellar of {area:280}'s inn, or one of the Syndicate tent camps in the uplands north and north-west of the village."] = "Идите по дороге на север из места {area:271} в горы. По склонам бродят горные львы; члены Синдиката в месте {area:280} носят перстни-печатки. {npc:2306} (40) появляется в одном месте за раз: в подвале таверны ({area:280}) или в одном из палаточных лагерей Синдиката на возвышенностях к северу и северо-западу от деревни.",
		["Follow the road north to the draenei of the {area:657}."] = "Идите по дороге на север к дренеям {area:657}.",
		["For {npc:1440} in {zone:1453}: keep it"] = "Для NPC {npc:1440} ({zone:1453}): сохраните",
		["For {npc:2487} in {area:35}: keep it"] = "Для NPC {npc:2487} ({area:35}): сохраните",
		["For {npc:2542} in {area:35}: keep it"] = "Для NPC {npc:2542} ({area:35}): сохраните",
		["For {npc:2711} in {area:271}"] = "Для NPC {npc:2711} ({area:271})",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "Из города {zone:1455} идите через туннель на восток через зону {zone:1426} в зону {zone:1432} и по дороге сюда: {area:144}.",
		["Inside"] = "Внутри",
		["North-west out of the Witherbark valley; {npc:2712} and {npc:2713} camp in the hills just north of {area:314}."] = "На северо-запад из долины Сухокожих; {npc:2712} и {npc:2713} стоят лагерем на холмах сразу к северу от места {area:314}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Только если Барабуль дал вам подвеску в Тернистой долине",
		["Phizzlethorpe"] = "Физзлторп",
		["South from the {object:2691}, past {area:314}, to {area:317} in the hills: the Witch Doctors stand among the huts and the Shadow Hunters guard the far end of the valley. Every troll can drop a tusk."] = "На юг от объекта {object:2691}, мимо места {area:314}, сюда: {area:317} на холмах. Знахари стоят среди хижин, а темные охотники охраняют дальний конец долины. Клык может выпасть с любого тролля.",
		["South-east along the loch to the dig site."] = "На юго-восток вдоль озера к раскопкам.",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "На юго-запад к лагерю Кирин-Тора на берегу озера к западу от места {area:279}, сразу за границей зоны {zone:1421}: там стоит {npc:269127}. Верховный маг Ансарем стоит к юго-востоку от него, у купола.",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop the Motes of Myzrael, not Krazek's ore. Lesser Bloodstone Deposits need {skill:186} 75: mine four ore, buy them at the Auction House, or ask a miner friend. The ore goal is optional; continue with Myzrael if you cannot get it. Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Кобольды из племени Сухоусов копают в ущелье к востоку от места {area:321} (Орда); обойдите поселение с севера. С них падает «Мощь Мизраэли», а не руда для Кразека. Для малых месторождений кровавого камня нужен навык {skill:186} 75: добудьте четыре куска руды, купите их на аукционе или попросите друга-шахтера. Цель с рудой необязательна; если не можете ее достать, продолжайте с Мизраэлем. Осторожно: все виды кобольдов убегают за подмогой при низком здоровье (кобольды – при 30%, геодезисты и землекопы – при 15%), и так можно привлечь еще больше.",
		["The courier walks the road from {area:314} west across the Highlands, as far as about 24,45, and back, with two guards: the arrow follows the road west until you meet him. Pull them off the road."] = "Курьер с двумя стражами ходит по дороге от места {area:314} на запад через нагорье примерно до 24,45 и обратно: стрелка ведет по дороге на запад, пока вы его не встретите. Выманите их с дороги.",
		["The shards lie at the far end of {area:318}."] = "Радужные осколки лежат в дальнем конце места {area:318}.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Два затонувших корабля лежат в заливе к западу от бухты. Карты и журналы внутри них; самоцветы лежат на морском дне вокруг. Наги из клана Пронзающего Гребня плавают по всему заливу.",
		["The western swamp"] = "Западная часть болота",
		["The wrecked caravan's chest lies at the north end of the {area:76}, beside {npc:5391}'s cage.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "Сундук разбитого каравана стоит в северной части места {area:76}, рядом с клеткой NPC {npc:5391}.\nОсторожно: лагерь полон Заблудших около 38-го уровня. Они стоят связанными группами по 2-3, многие из них заклинатели, и возрождаются они быстро.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:2417} walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path."] = "Это элитные противники: лучше собраться в группу, поищите, с кем пойти. {npc:2417} – элитный противник 40-го уровня: большинство классов справляются с ним в одиночку на 42-м уровне, но вам может понадобиться помощь. Если вы один, пропустите его: маршрут позволит набрать этот опыт другим способом.\n{npc:2417} ходит от стрелки на северо-восток через руины примерно до 40,47 и обратно: если его нет у стрелки, идите по его пути.",
		["Tram to {zone:1455}"] = "Поезд до {zone:1455}",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Молодые кроколиски, ткачи скорби и болотные ягуары бродят по болоту вокруг дороги.",
		["from {quest:1392}: he walks a path through the ruins"] = "с противника {quest:1392}: он ходит по руинам",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: огры из клана Раздробленного Хребта",
		["{item:4435} from {npc:2572}, {npc:2573} and {npc:2574}, by this stop"] = "{item:4435}: с противников {npc:2572}, {npc:2573} и {npc:2574}, рядом с этой точкой",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, дорога к месту {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, Собор Света",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, королевская библиотека в крепости",
		["{npc:185335}, at the same circle"] = "{npc:185335}, у того же круга",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: три зверька, которых нужно поймать в Нагорье Арати, Пустошах ({zone:1443}) и Тернистой долине",
		["{npc:2434}, if you spot him"] = "{npc:2434}, если заметите",
		["{npc:2705}, below ground"] = "{npc:2705}, под землей",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} и {npc:2713}",
		["{npc:2713}'s errand"] = "Поручение: {npc:2713}",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391} заперт в клетке в северной части святилища. Освободите его и не дайте ему погибнуть по пути наружу; затем его сундук будет ждать у дороги.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} привязывает инкуба к вам",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} ждет в подвале здания {object:2164} ({object:2101}). Используйте {item:6913} у круга призыва и победите призванного суккуба. Если вы взяли задание {quest:65602}, отдайте ему еще и {item:190309}, поставьте ее у того же круга и победите инкуба.",
		["{quest:65602}, if you took it"] = "{quest:65602}, если вы его взяли",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["A {npc:217590} crawls about the {area:596}: catch one with the tool from {npc:217412}'s Entomology Starter Kit."] = "Здесь ({area:596}) ползает {npc:217590}: поймайте одного инструментом из набора начинающего энтомолога от {npc:217412}.",
		["Fly to Theramore"] = "Лететь на остров Терамор",
		["Follow the road north to {area:608}: {npc:5396} stands at its south end, {npc:5638} in the middle, {npc:1182} to the north."] = "Идите по дороге на север. Цель: {area:608}. {npc:5396} стоит в южной части, {npc:5638} – в центре, {npc:1182} – на севере.",
		["Follow the road south to {area:2407}."] = "Идите по дороге на юг. Цель: {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Идите по дороге на запад через север зоны {zone:1443} к руинам ({area:2405}). Там на холме, по пути к обломкам корабля, стоит башня {npc:11863}.",
		["Lesser Rock Elementals"] = "Младшие каменные элементали",
		["Maraudine centaurs"] = "Кентавры из племени Мародин",
		["Rackmore's chest lies just south-east of the {object:177673}."] = "Сундук Ракмора лежит чуть юго-восточнее объекта {object:177673}.",
		["Rock Elementals"] = "Каменные элементали",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "Следующее поручение Ржанца ведет сюда: {area:1517}. Пропустите его.",
		["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "Огры из клана Гнилобрюхов стоят лагерем чуть южнее долины; лом падает с любого из них. Над равниной к востоку кружат канюки.\nРазбитый скелет лежит на краю лагеря троггов из племени Каменного Свода; убийца Агмонда ({quest:739}) ходит среди костегрызов.\nОсторожно: повелители из клана Гнилобрюхов – 44-45-го уровня. Они применяют {spell:5242} и {spell:1160}, а при здоровье ниже 50% зовут на помощь союзников в радиусе 15 м. Семеро из них стоят примерно в 750 м к югу (ориентир: {area:340}).",
		["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}; every rock elemental can drop {npc:1470}'s Rock Elemental Shards."] = "Младшие каменные элементали бродят здесь: {area:1878}, к западу от {npc:2921}; осколки каменных элементалей для NPC {npc:1470} могут выпасть из любого каменного элементаля.",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Кентавры из племени Мародин занимают {area:607} к западу от кладбища; тотемы падают со всех.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Каменные элементали бродят к юго-востоку от {npc:2921}; на равнине к западу от них – гигантские канюки и старые скальные койоты.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Дворфы Тенегорна стоят лагерем чуть севернее раскопок; смятая карта лежит среди их палаток. Кирка Ржанца – у проходчиков и темнопрядов. По склонам вокруг бродят скальные койоты.",
		["The Slitherblade naga hold the north-west coast north of {npc:11863}'s tower; Karnitol's satchel lies on the sea floor off it, and any naga can drop Rackmore's golden key. Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}."] = "Наги Скользящего Клинка занимают северо-западное побережье к северу от башни {npc:11863}; сумка Карнитола лежит на морском дне напротив, а золотой ключ Ракмора может выпасть из любой наги. Плывите к месту {area:2406} у дальней северной оконечности и используйте {item:15766} на объекте {object:177673}: появится {npc:12369} (38); убейте его ради предмета {quest:6027}.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "Разбитый скелет лежит чуть восточнее огров, на краю лагеря троггов из племени Каменного Свода; хлопья падают с костегрызов и шаманов вокруг. Тельдарин сидит у разрушенного лагеря дальше к югу.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Моллюски – на северо-западном побережье Тернистой долины, в следующем гайде: сохраните задание",
		["The excavation crate"] = "Ящик с раскопок",
		["The next guide starts in Theramore."] = "Следующий гайд начинается на острове Терамор.",
		["The wrecked ship's chest lies just south-west of {npc:11863}'s tower."] = "Сундук с разбитого корабля лежит чуть юго-западнее башни {npc:11863}.",
		["The {area:2657}"] = "{area:2657}",
		["The {object:126260}"] = "{object:126260}",
		["To {area:2101}"] = "В таверну: {area:2101}",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Опустошители-отрекшиеся бродят по костяным полям к югу от деревни племени Маграм, к востоку от Ковена; на дальнем юго-востоке используйте {item:15848}, чтобы приманить призраков из племени Маграм.",
		["escort {npc:12277} back toward the graveyard"] = "сопроводите {npc:12277} обратно к кладбищу",
		["for {npc:2786} in {zone:1455}: keep it"] = "для NPC {npc:2786} ({zone:1455}): сохраните задание",
		["for {npc:3980} in {area:271}: keep it"] = "для NPC {npc:3980} ({area:271}): сохраните задание",
		["for {npc:5637} in {zone:1455}: keep it"] = "для NPC {npc:5637} ({zone:1455}): сохраните задание",
		["{item:15766}, on the {object:177673}"] = "{item:15766} – на объекте {object:177673}",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881} – с наг Скользящего Клинка",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, рядом с {npc:2921}",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618} и {npc:2817} стоят лагерем вместе ({area:1877}), в центре зоны {zone:1418}.",
		["{npc:5638}, if 30-40/02 didn't take it: the wreck lies below {npc:11863}'s tower"] = "{npc:5638}, если вы не взяли это задание в гайде 30-40/02: обломки корабля лежат под башней {npc:11863}",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons."] = "{npc:6019} стоит на краю места {area:596}, к юго-западу (ориентир: {area:2407}); {object:176751} лежат среди скелетов.",
		["{object:177787} lies beside {object:35251}. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next."] = "{object:177787} лежит рядом с объектом {object:35251}. Его серебряный ключ падает с крабов Сухого Щелчка вокруг обломков корабля; золотой – с наг Скользящего Клинка на северо-западном побережье, далее по гайду.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "«Вонючка» Игнац",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "На 40-м уровне, имея 100 золотых, можно научиться верховой езде, и при обучении вы получите транспорт. {npc:4732} обучает людей ({area:88}, восток зоны {zone:1429}) рядом с лошадьми, которых продает {npc:384}. Возможно, в Forever любая раса может учиться у любого учителя верховой езды (не подтверждено). Все цвета – в разделе «Коллекции», «Транспорт · 40-й уровень».",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "На 40-м уровне, имея 100 золотых, можно научиться верховой езде, и при обучении вы получите транспорт. {npc:4753} обучает ночных эльфов (город {zone:1457}) рядом с саблезубами, которых продает {npc:4730}: корабль ({area:17203} – {area:442}), затем полет в {area:702}. Возможно, в Forever любая раса может учиться у любого учителя верховой езды (не подтверждено), например у NPC {npc:4732} ({area:88}, зона {zone:1429}). Все цвета – в разделе «Коллекции», «Транспорт · 40-й уровень».",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "На 40-м уровне, имея 100 золотых, можно научиться верховой езде, и при обучении вы получите транспорт. {npc:4772} обучает дворфов ({area:803}, к востоку от поселка {area:131} по дороге в зону {zone:1432}) рядом с баранами, которых продает {npc:1261}. Возможно, в Forever любая раса может учиться у любого учителя верховой езды (не подтверждено). Все цвета – в разделе «Коллекции», «Транспорт · 40-й уровень».",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "На 40-м уровне, имея 100 золотых, можно научиться верховой езде, и при обучении вы получите транспорт. {npc:7954} обучает гномов ({area:189}, сразу к востоку от поселка {area:131}) рядом с механодолгоногами, которых продает {npc:7955}. Возможно, в Forever любая раса может учиться у любого учителя верховой езды (не подтверждено). Все цвета – в разделе «Коллекции», «Транспорт · 40-й уровень».",
		["Bloodsail camp"] = "Лагерь шайки Кровавого Паруса",
		["Boat to {area:150}"] = "Корабль: {area:150}",
		["Boat to {area:35}"] = "Корабль: {area:35}",
		["Cortello's scroll"] = "Свиток Кортелло",
		["Defeat the challengers and {npc:6238}"] = "Победите соперников и NPC {npc:6238}",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "С каждого пирата из шайки Кровавого Паруса падает понюшка, а у одного из них – глаз {npc:2493}; висельники бродят по берегу сразу к северу от города. Карты и приказы лежат в лагере пиратов ({area:43}), к югу от бухты ({area:35}).",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Смесь может выпасть с любого последователя Занзила; {npc:2537} ходит в южной части лагеря.",
		["Fly to {area:35}"] = "Летите: {area:35}",
		["Fly to {zone:1453}"] = "Лететь в {zone:1453}",
		["Follow the road east back to Theramore. The officers are in {area:514}."] = "Идите по дороге на восток назад в Терамор. Офицеры – в здании {area:514}.",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it.\n{npc:4967} waits at the foot of the tower: once you have looked around, hand the quest in to him there, not in Theramore."] = "Идите по дороге на северо-запад из Терамора к сторожевой башне ({area:503}). По болоту вокруг нее бродят глинистые землеглоты.\n{npc:4967} ждет у подножия башни: осмотревшись, сдайте задание ему прямо там, а не в Тераморе.",
		["Gorilla hills"] = "Холмы горилл",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "Сдайте клыки и оставайтесь на месте: придут три волны горилл, последним – {npc:1514}. Бейтесь с полным здоровьем.",
		["Inside"] = "Внутри",
		["Jungle Stalkers"] = "Тропические ловцы",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "Выйдите из города через туннель и идите вдоль побережья на север; письмо лежит в лагере шайки Кровавого Паруса на пляже, где ходит «Красавчик» Дункан.",
		["MacKinley's next task sends you after elite ogres: skip it."] = "Следующее задание Маккинли отправляет вас к элитным ограм: пропустите его.",
		["Mirefin murlocs"] = "Мурлоки из племени Болотного Плавника",
		["Naga Explorers"] = "Наги-исследователи",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "По пути на север в {area:392}: {area:720} лежит у берега ({area:391}) к югу от города, перейдите вброд по отмели. {npc:6236} по одному выпускает против вас четырех соперников, а затем – {npc:6238} (33-й уровень).",
		["Optional: Cortello's scroll lies inside one of the three Bloodsail ships anchored off the coast just south of {area:35}, on a middle or lower deck, and is not always on the same ship. Their crews are 42-45 pirates: clear your way from the edge, one at a time, and leave the captains (45-48), whom the route comes back for at 48."] = "Необязательно: свиток Кортелло лежит на одном из трех кораблей Кровавого Паруса, стоящих на якоре у берега чуть к югу от места {area:35}, на средней или нижней палубе, и не всегда на одном и том же корабле. Команды – пираты 42-45 уровня: расчищайте путь с края по одному и не трогайте капитанов (45-48) – за ними маршрут вернется на 48-м уровне.",
		["Paladin: {quest:1661}"] = "Паладин: {quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "Езжайте назад вниз в город; Трусишка стоит у входа в туннель.",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Езжайте на восток; перевитые ужасы по пути тоже роняют рассуждения. Обыщите край озера ({area:74}), где из воды поднимаются руины храма.",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "Езжайте вглубь суши к холмам горилл Мглистой долины. Потроха падают со старых горилл из Мглистой долины; среди них сидит {npc:1449}.",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "Езжайте на север к холмам к западу от дороги. {npc:2535} и {npc:2536} стоят вместе сразу к северу от деревни Занзила.",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Езжайте от шахты на северо-запад к заливу на северо-западном побережье. На его дне лежат гигантские моллюски с жемчугом; среди них плавает {npc:2624}, с него падает {item:4034}.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Езжайте на юг из зоны {zone:1432} через перевал в зону {zone:1418}; {npc:2860} стоит лагерем у раскопок.",
		["Ride south to the giant's hut in the middle of the marsh."] = "Езжайте на юг к хижине великана в середине болота.",
		["Riding at 40"] = "Верховая езда на 40-м уровне",
		["Seahorn's next errand goes back to Arathi: skip it."] = "Следующее поручение Морского Рога ведет обратно в Нагорье Арати: пропустите его.",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Вонючка ждет к западу от усадьбы, на болоте под башней ({area:504}). Отведите его к листьям болотного боба и не подпускайте к нему болотных тварей.",
		["Stormwind City"] = "Штормград",
		["The Mirefin murlocs crowd the north coast past {area:497}."] = "Мурлоки из племени Болотного Плавника толпятся на северном побережье за усадьбой ({area:497}).",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes."] = "Сгоревшая таверна стоит у дороги на запад, в сторону зоны {zone:1413}; значок стражника лежит в пепле.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Дезертиры стоят лагерем к югу от дороги, к западу от хижины {npc:4503}.",
		["The driftwood washes up along the eastern shore."] = "Плавник выносит на восточный берег.",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "Наги прочесывают пляжи к северу от лагеря шайки Кровавого Паруса; с них падает тростник.",
		["The north-west coast"] = "Северо-западное побережье",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "Свиток лежит на болоте к северу от Биггса. С тинобродов к северу от него могут выпасть рассуждения Кадгара.",
		["The sunken temple"] = "Затонувший храм",
		["Theramore"] = "Терамор",
		["Tram to {zone:1455}"] = "Поезд до {zone:1455}",
		["Unbagwa's ritual"] = "Ритуал Унбагвы",
		["Upstairs"] = "Наверху",
		["Warlock: {quest:3631}"] = "Чернокнижник: {quest:3631}",
		["Zanzil's village"] = "Деревня Занзила",
		["for the flight back to {npc:6251} at 43"] = "для полета назад к NPC {npc:6251} на 43-м уровне",
		["for the {zone:1435} later"] = "для зоны {zone:1435}, позже",
		["for {area:1438}: keep it"] = "для места {area:1438}: сохраните",
		["for {npc:2616} in Theramore: keep it"] = "для NPC {npc:2616} (Терамор): сохраните",
		["for {npc:5635} at {area:348}: keep it"] = "для NPC {npc:5635} ({area:348}): сохраните",
		["for {npc:770} at the {area:99}, on the northern loop"] = "для NPC {npc:770} ({area:99}), на северном круге",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "только если у вас есть {item:3853} (изготавливает кузнец)",
		["with the spices from Theramore"] = "со специями из Терамора",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}: для Ярла «Болотного Глаза»",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} готовит в здании {object:2169}; {npc:5384} – {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: другие цвета, 20 з.",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440} – Королевская библиотека ({object:2117})",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}: {quest:93176}, из гайда по Нагорью Арати (30-40)",
		["{npc:2487}, top floor"] = "{npc:2487} – верхний этаж",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "Следующее поручение {npc:2498} про Занзила начинается в зоне {zone:1441}: пропустите его.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} и {npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} плавает у северо-западного побережья, на северном круге",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} стоит лагерем в одиночестве ({area:1898}), к юго-востоку от раскопок.",
		["{npc:384}: other colours, 20g"] = "{npc:384}: другие цвета, 20 з.",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461} – {object:2164}: задание примет {npc:6251} ({area:392}) в конце следующего гайда",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: другие цвета, 20 з.",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders.\n{npc:4967} and {npc:4968} wait beside the tower: once he yields, hand in to both on the spot."] = "{npc:4966} удерживает башню с несколькими дезертирами. Он нападет на вас: бейте его, пока он не сдастся.\nОсторожно: у Хендела два стражника, которые вступают в бой, когда он становится враждебным. Когда он сдается, стражники убегают.\n{npc:4967} и {npc:4968} ждут рядом с башней: когда он сдастся, сдайте задания обоим на месте.",
		["{npc:4967}, at the tower"] = "{npc:4967}, у башни",
		["{npc:5464}, by the flight master"] = "{npc:5464}, у распорядителя полетов",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171} – в Соборе Света",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "Затем {npc:6236} предлагает задание «Ветростраж» (1791): цепочка оружия Вихря с элитным противником в конце описана в классовом гайде воина «Оружие Смерча».",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: для задания «{quest:2864}» (зона {zone:1446}), сохраните",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: другие цвета, 20 з.",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "Задание «{quest:1260}» – у таверны; {npc:4897}, поставщица в нескольких шагах к югу, продает специи, которые нужны Ярлу.",
		["{zone:1453} flight master"] = "Распорядитель полетов: {zone:1453}",
		["{zone:1453} has no shaman trainer"] = "В городе {zone:1453} нет учителя шаманов",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Fly to {area:271}"] = "Летите сюда: {area:271}",
		["From Theramore, ride north into the {zone:1413} to {area:392}, or fly if you know its flight path. {npc:6251} teaches in the house by the bank."] = "С острова Терамор езжайте на север в зону {zone:1413}. Цель: {area:392}; если знаете этот маршрут полета, летите. {npc:6251} обучает в доме у банка.",
		["Raleigh's next errand is in the {area:796}: skip it."] = "Следующее поручение Ролея – здесь: {area:796}. Пропустите его.",
		["Ride back east to {area:1898}."] = "Езжайте обратно на восток. Цель: {area:1898}.",
		["Ride back north to Ironband's camp."] = "Езжайте обратно на север к Раскопкам Сталекрута.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Из места {area:271} езжайте по дороге на северо-восток во {zone:1425}; {area:348} – сразу за границей. {npc:5635} принимает наверху, у птичника – {quest:1450}, у таверны стоит {npc:7884}.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "Следующее задание Разящего Когтя подождет до более позднего гайда по {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Обжигающие дракончики гнездятся в ущелье к востоку (ориентир: {npc:2888}); опаленных стражей (элита) не трогайте. {item:4612} падает редко: возьмите, если выпадет, пока вы фармите.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "Первые две клетки стоят рядом в деревне племени Сухокожих к югу от {npc:5634}; третья – в следующей деревне к востоку. Ожерелье может упасть с любого тролля из племени Сухокожих.",
		["The {area:1517} dig"] = "Раскопки: {area:1517}",
		["Theramore"] = "Остров Терамор",
		["Warlock: {quest:3631}"] = "Чернокнижник: {quest:3631}",
		["Witherbark villages"] = "Деревни племени Сухокожих",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} стоит на причале, куда прибывает корабль.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "{npc:2817}: следующее задание не дает опыта, пропустите его.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "{npc:2888}: следующее задание – охота на элиту, пропустите его.",
		["{npc:2944} does not stay at {area:342}: he walks a long loop around the {zone:1418} with his guards, from the camp in the west along the south of the zone to about 61,69, north to about 49,49 and back west to the camp. The arrow follows his loop west from here until you meet him."] = "{npc:2944} не стоит на месте ({area:342}): он со своими стражами обходит зону {zone:1418} по длинному кругу – от лагеря на западе вдоль юга зоны примерно до 61,69, затем на север примерно до 49,49 и обратно на запад к лагерю. Стрелка ведет по его маршруту на запад отсюда, пока вы его не встретите.",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} стоит лагерем на дороге к востоку (ориентир: {area:348}).",
		["{npc:7744}; below ground"] = "{npc:7744}; под землей",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Вернитесь сюда: {area:1117}. С любой наги из клана Гребня Ненависти там может выпасть чешуя.",
		["Gordunni ogres"] = "Огры из клана Гордунни",
		["Grimtotem camp"] = "Лагерь Зловещего Тотема",
		["Grimtotem tauren"] = "Таурены из племени Зловещего Тотема",
		["Grind to 45"] = "Гринд до 45",
		["Hatecrest naga"] = "Наги из клана Гребня Ненависти",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "Езжайте обратно сюда: {area:1108}; гоблин стоит у причала.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Езжайте на восток к Поселению Гордунни на холмах к юго-востоку от долины йети: в лагере чернокнижники и шаманы, громилы бродят по склонам вокруг и севернее.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Езжайте на север в долину йети. С любого йети со Свирепого Утеса может выпасть толстая шкура; {npc:5346} (уровень 48) рыщет в центре.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Езжайте на северо-восток к заставе ночных эльфов на границе зоны {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Езжайте на юго-восток к гноллам из стаи Древолапов; рюкзаки курьера лежат в их южном лагере, а посылка в них начинает доставку в {area:489}. Улей Зуккаш чуть южнее: пробейтесь к коконам, где держат Раскала, освободите его и сохраните ему жизнь на пути наружу.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Береговые странники, странники глубин и странники волн (элитные великаны) бродят по мелководью к северу от причала: ударьте одного предметом {item:18904} и убейте уменьшенного великана. Морские элементали и морские валы плавают в том же прибое.",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Плывите на корабле сюда: {area:1108}, и идите вдоль берега на юг к разбитой шлюпке на пляже.",
		["The courier's boat"] = "Лодка курьера",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Идите на юг по острову к руинам наг; беседка стоит среди них.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "для Тиранды ({zone:1457}): маршрут приведет вас туда на 47-м уровне",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "гринд: {npc:5292}, {area:1105}, {zone:1444}",
		["{item:11463}, from the backpacks"] = "{item:11463}, из рюкзаков",
		["{npc:14637}'s refills are level 55: skip them."] = "Пополнения {npc:14637} — 55-го уровня: пропустите их.",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "Затем {npc:3936} просит отнести вести в {zone:1457}: пропустите, {area:976} сам отправит вас туда.",
		["{npc:3936}, beside him"] = "{npc:3936}, рядом с ним",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: его ответ ждет в месте {area:702}, позже",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, на вершине крепости",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} ждет до конца круга по материку.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Boat to {area:150}"] = "Корабль: {area:150}",
		["Fly to Theramore"] = "Лететь на остров Терамор",
		["Gives the {item:8585}"] = "Дает: {item:8585}",
		["Pool by {area:979}"] = "Пруд у места {area:979}",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Езжайте на восток через дюны к гоблинской гавани на северо-восточном побережье.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "Езжайте на северо-запад к лагерю троллей из племени Песчаной Бури: {area:979}. Используйте {item:8584} у края пруда; тролли стоят близко, так что выманивайте ближайших первыми.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Езжайте на юг к лагерю раскопок: {area:1938}. {npc:7771} дает вам шлем-детектор: наденьте его, чтобы видеть холмики ({quest:3161}); их много в песке вокруг лагеря и к юго-западу, в сторону огров.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "Езжайте на юго-восток из места {area:439} в {zone:1446}. {area:976} — сразу за границей.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Езжайте на юго-запад к поселению огров. Там полно громил и головорезов (46-48); {npc:12046} (49) стоит в центре в окружении стражи: сначала разберитесь с ней.",
		["The Wanted poster beside him"] = "Плакат «Розыск!» рядом с ним",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "Маленький черепах {npc:5955} прячется в северной части долины. Отведите его домой к жене ({npc:6015}), у воды чуть восточнее места {area:977}: он идет медленно, и звери пустыни нападают на него, так что берегите его.",
		["The pool by {area:979}"] = "Пруд у места {area:979}",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "То же объявление: {npc:7847} будет гораздо позже, после места {area:976}",
		["The {area:1938}"] = "Место: {area:1938}",
		["The {area:2240} lies on the {area:439} in south-east {zone:1441}: {npc:4454} is in the gnomes' camp beside the track, Zamek by the goblin camp."] = "{area:2240} находится здесь: {area:439}, на юго-востоке зоны {zone:1441}. {npc:4454} – в лагере гномов у трассы, Замек – у лагеря гоблинов.",
		["for {zone:1457}: the route takes you there at 47"] = "Для зоны {zone:1457}: маршрут приведет вас туда на 47-м уровне",
		["{npc:5955}'s escort"] = "Сопровождение: {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, у водонапорной башни",
		["{npc:7408}, next to him"] = "{npc:7408}, рядом с ним",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: его ящик едет в {area:702}, позже",
		["{quest:2864}, north side of town"] = "{quest:2864}, северная часть городка",
} end)()
