} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Аркессон стоит рядом с королем Магни ({object:171709}).",
		["Archesonus stands beside King Magni in the {object:171709}: the relics you read in the Steppes are his."] = "Аркессон стоит рядом с королем Магни ({object:171709}): реликвии, которые вы прочли в Пылающих степях, – для него.",
		["Ardalan is inside {area:1438}."] = "Ардалан находится внутри крепости ({area:1438}).",
		["Below ground"] = "Под землей",
		["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "Поднимитесь на вершину скалы ({area:249}) и посадите голову в кучу мягкой земли.",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "Завершается заданием «{quest:4808}» ({area:2255}, {zone:1452}): сохраните",
		["Fly to {area:1537}"] = "Лететь в {area:1537}",
		["Fly to {area:271}"] = "Летите сюда: {area:271}",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "Идите по дороге на запад, затем поднимитесь на север к лагерю гоблинов: {area:251}.",
		["For {zone:1453}: keep it"] = "Для города {zone:1453}: сохраните задание",
		["Listen to his tale, then ride back south to Kum'isha."] = "Выслушайте его рассказ, затем езжайте назад на юг к Кум'ише.",
		["Mosshoof Coursers"] = "Мохоногие олени",
		["Open the {item:10569} from {zone:1427} for its {item:10575}, then tell {npc:9459} you bring proof of your deeds: no drake to fight."] = "Откройте {item:10569} из зоны {zone:1427}, чтобы достать {item:10575}, затем скажите NPC {npc:9459}, что принесли доказательство своих подвигов: сражаться с драконом не придется.",
		["Portal to {zone:1438}"] = "Портал: {zone:1438}",
		["Ride back east along the road to the Vigil."] = "Езжайте по дороге назад на восток к Дозору.",
		["Ride back south to the camp."] = "Езжайте назад на юг к лагерю.",
		["Ride north out of the {zone:1419} into the {zone:1435}: the {npc:10996} stands by the road from the {zone:1419}. Keep clear of {area:75}, the Horde town to the north-east."] = "Езжайте на север из зоны {zone:1419} в зону {zone:1435}: {npc:10996} стоит у дороги, ведущей из зоны {zone:1419}. Держитесь подальше от места {area:75} – это город Орды на северо-востоке.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "Езжайте от святилища на северо-восток: {npc:8405} стоит лагерем здесь – {area:1224}, в холмах над дорогой.",
		["Swim to the small island off the southern tip of {zone:1447}. If {npc:8392} isn't there, fire your {item:10444} to signal him, and wait for him to land."] = "Доплывите до островка у южной оконечности зоны {zone:1447}. Если NPC {npc:8392} там нет, подайте ему сигнал из предмета {item:10444} и дождитесь, пока он приземлится.",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "Огры из клана Огненного Чрева занимают большую скалу к северу от Дозора, громилы – на ее восточной стороне.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "Призраки высокорожденных бродят по руинам вокруг святилища; сатиры из племени Халдарр занимают лагерь сразу к северу от него.",
		["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "Наги из клана Бича Злобы ({area:1221}) носят предмет {item:13815}. Четыре руны, которые нужны NPC {npc:8507}, стоят среди руин: используйте на каждой его {item:10445}.",
		["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "Ближайшие мохоногие олени пасутся в холмах к северо-востоку от места {area:1224}, в сторону места {area:1219}; стадо побольше бродит по открытой местности на юге.",
		["The portal in {area:702} leads up to {zone:1457}: {npc:9047} waits in the {area:1658}, in the north of the city."] = "Портал в деревне {area:702} ведет наверх, в город {zone:1457}: {npc:9047} ждет в анклаве ({area:1658}) на севере города.",
		["The relics are in the {zone:1428}: keep it"] = "Реликвии – в зоне {zone:1428}: сохраните",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "Святилище лежит в юго-западном углу зоны {zone:1447}, к югу от заставы ({area:3137}).",
		["The wildkin are in {zone:1452}: keep it"] = "Дикие совухи – в зоне {zone:1452}: сохраните",
		["The {area:1221}"] = "{area:1221}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} (level 48 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the {zone:1425} shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "Это элитные противники: лучше собрать группу, поищите, с кем пойти. {npc:7977} (элитный, 48-й уровень) требует группы из 2 человек. Если вы один, пропустите это: маршрут возместит опыт за счет охоты на монстров.\n{npc:7977} ходит по берегу зоны {zone:1425} под утесами ({area:307}), от стрелки на юг примерно до 75,66 и на север примерно до 82,52: если ее нет у стрелки, идите вдоль берега.",
		["To {area:2101}"] = "В таверну: {area:2101}",
		["Upstairs"] = "Наверху",
		["Wildkin feathers"] = "Перья диких совухов",
		["{area:199} cauldron"] = "Котел: {area:199}",
		["{item:10575}, from the hoard"] = "{item:10575}, из клада",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}: {npc:7864}, около 10%",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "Призрак {npc:10778} бродит у дома ({area:199}) к западу от места {area:200}; ее посылка лежит внутри.",
		["{npc:11075} guards the cauldron in {area:199}, west of Andorhal."] = "{npc:11075} охраняет котел ({area:199}) к западу от Андорала.",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907} стоит наверху, над NPC {npc:7916}: поднимитесь внутри здания, стрелка не различает этажи.",
		["{npc:8395} wants two Undamaged Hippogryph Feathers from the Thunderhead hippogryphs around his camp, the ones you top up on here: about one in three carries one."] = "{npc:8395} хочет два неповрежденных пера гиппогрифа с громоглавых гиппогрифов вокруг его лагеря – тех, на которых вы здесь добираете опыт: перо есть примерно у каждого третьего.",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420} стоит лагерем на севере ({area:1219}); его снаряжение разбросано по всему месту {area:1220} сразу к юго-востоку от него.",
		["{npc:9047}, in the {area:1658}"] = "{npc:9047}, в анклаве ({area:1658})",
		["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177}: медальоны падают с орков из клана Черной Горы, держите задание открытым всё время в Пылающих степях",
		["{zone:1455} has no druid trainer"] = "В городе {zone:1455} нет учителя друидов",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Below ground"] = "Под землей",
		["Ends in the {zone:1413}: keep it"] = "Завершается здесь: {zone:1413} – сохраните задание",
		["First crater"] = "Первый кратер",
		["Follow the road north to the cave mouth of {area:1769}; {npc:15395} guards it."] = "Идите по дороге на север ко входу в пещеру ({area:1769}); его охраняет {npc:15395}.",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "Идите по дороге на север в долину с кратерами и обойдите каждый кратер, убивая по пути энтропических зверей и энтропических ужасов.",
		["Ride south-east from {area:1763} to the {area:2479}, the druids' camp by the road in southern {zone:1448}."] = "Езжайте на юго-восток ({area:1763} → {area:2479}) к лагерю друидов у дороги на юге зоны {zone:1448}.",
		["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "Сальфа стоит у выхода из туннеля в зону {zone:1452}: сохраните задание",
		["Second crater"] = "Второй кратер",
		["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "Фурболги из племени Мертвого Леса живут в деревне чуть юго-западнее (ориентир: {npc:11554}); сохраняйте перья из головного убора Мертвого Леса, которые с них падают.",
		["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back.\nCareful: Jadefire Shadowstalkers (level 51-52) use Sneak and {spell:7992} and are stealthed, so they often join fights uninvited.\nCursed Oozes slide about the glen's streams: kill them and use Laris's Empty Ooze Jar on their remains."] = "Сатиры из племени Нефритового Пламени занимают долину к западу от дороги; {npc:9454} – в ее глубине.\nОсторожно: ночные охотники из племени Нефритового Пламени (51–52-й уровень) используют Крадущийся шаг и {spell:7992} и находятся в незаметности, поэтому часто вмешиваются в бой.\nПроклятые слизнюки ползают по ручьям долины: убивайте их и используйте на останках пустой флакон, полученный у Лариса.",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "{item:11503} носят древни-криводревы ({area:1767}, к востоку от места {area:2618}).",
		["The {area:2479}"] = "{area:2479}",
		["Third crater"] = "Третий кратер",
		["{area:1763} again"] = "Снова: {area:1763}",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "{area:2618} – долина сатиров на северо-западе; {npc:10648} – в ее дальнем конце. С него падает {quest:939}; с любого сатира из племени Нефритового Пламени может упасть {item:11674}.",
		["{item:11949}: Tainted Oozes slide about {area:1763}'s fel pools"] = "{item:11949}: нечистые слизнюки ползают по озерам скверны ({area:1763})",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395} ждет в северной части зоны {zone:1448}",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528} – в руинах чуть восточнее (ориентир: {npc:11554})",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Boat to {area:150}"] = "Корабль: {area:150}",
		["Fly to Theramore"] = "Лететь на остров Терамор",
		["Fly to {area:3197}"] = "Летите сюда: {area:3197}",
		["Follow the road east across the zone to the chapel."] = "Идите по дороге на восток через всю зону к часовне.",
		["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "Идите по дороге на запад к лагерю {npc:9298} у горячих источников.",
		["Follow the southern road east into the {zone:1423}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "Идите по южной дороге на восток в зону {zone:1423}; руины ({area:2262}) лежат к югу от нее. Призрак {npc:10926} играет у разрушенного дома в южной части.",
		["For Kernda in {area:1769}: keep it"] = "Для Кернды ({area:1769}): сохраните",
		["Free Darrowshire Spirits: talk to them"] = "Освободите духов Дарроушира: поговорите с ними",
		["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}."] = "Йети с Холмов ледополоха живут на холмах к югу от места {area:2244}, хладноветрые химеры — в долине по пути к месту {area:2255}.",
		["Inside"] = "Внутри",
		["Keep it: Gregan in {zone:1444} brews the elixir later"] = "Сохраните: Греган ({zone:1444}) позже сварит эликсир",
		["On {npc:10978}, by the inn"] = "Взяв задание у NPC {npc:10978}, у таверны",
		["Pristine Yeti Horns"] = "Нетронутые рога йети",
		["Pureheart, Dumah, Valorfist and MacDonnell stand around the middle of the camp, by the flight master."] = "Чистое Сердце, Дума, Доблестный Кулак и Макдоннел стоят в центре лагеря, у распорядителя полетов.",
		["Scare {npc:10978} with {item:12928}"] = "Напугайте {npc:10978} с помощью предмета {item:12928}",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "Котел Мертвого Леса ({zone:1448}): сохраните",
		["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "Деревня фурболгов из племени Зимней Спячки лежит к востоку от места {area:2255}: шаманы (56-57), дозорные (55-56) и ведмеди (57-58), все выше вас. Сначала убивайте шаманов, они лечат, и выманивайте с краю. {npc:10738} в пещере в глубине — элитный: не заходите туда.",
		["The next guide starts here and flies to {area:3197}."] = "Следующий гайд начинается здесь и ведет полетом сюда: {area:3197}.",
		["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "Руины окружают замерзшее озеро к югу от места {area:2253}. Подберите четыре фрагмента реликвий, лежащих в руинах, и светолунные перья на земле там, где бродят дикие совухи.",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "Три части куклы лежат в разрушенных домах ({area:2262}); если подобрать одну, могут появиться призраки. Соедините их в куклу.",
		["To {area:2101}"] = "В таверну: {area:2101}",
		["Your Hearthstone is not set at {area:144} (the {zone:1425} guide binds there at 47, and this guide leaves {zone:1452} through it): bind at {area:2255} instead, for the trips back to town."] = "Ваш камень возвращения не привязан к месту {area:144} (гайд по зоне {zone:1425} привязывает вас там на 47-м уровне, и этот гайд покидает зону {zone:1452} через него): вместо этого привяжитесь здесь ({area:2255}), чтобы возвращаться в город.",
		["Your Hearthstone is still set at {area:144}: from there the gryphon to {area:3197} is about ten minutes quicker than {area:2255}'s flight to Theramore and the boat."] = "Ваш камень возвращения все еще привязан к месту {area:144}: оттуда полет на грифоне сюда ({area:3197}) примерно на десять минут быстрее, чем перелет отсюда ({area:2255}) на Терамор и корабль.",
		["Zaeldarr is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "Зельдарр — элитный: лучше собрать группу. Он ждет на самом дне ({area:2261}) — склепа на юго-западе зоны.",
		["{area:144} flight master"] = "Распорядитель полетов ({area:144})",
		["{area:2255}'s inn"] = "Таверна ({area:2255})",
		["{item:12383}, 110 yd north"] = "{item:12383}, 110 м к северу",
		["{npc:10926}'s doll"] = "Кукла {npc:10926}",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}: {npc:7583} и {npc:10977} будут позже",
		["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556} стоит прямо у выхода туннеля ({area:1769}) в край {zone:1452}, там, где вы выходите.",
		["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616}: термиты будут позже, здесь: {area:2627}",
		["{quest:5152}, in the {zone:1422}: keep it"] = "{quest:5152}, {zone:1422}: сохраните",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["Andorhal"] = "Андорал",
		["Back to {npc:7775}'s camp, just south-east of {npc:7765}: the {item:11242} buys three Videre Elixirs. Keep them: {npc:9298} takes one, and {npc:9299} in {area:976} shows himself only to someone who has drunk one."] = "Назад в лагерь {npc:7775}, чуть к юго-востоку от {npc:7765}: за {item:11242} вы получите три эликсира Видере. Сохраните их: {npc:9298} берет один, а {npc:9299} ({area:976}) показывается только тому, кто выпил эликсир.",
		["Below ground"] = "Под землей",
		["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "Перейдите реку на восток к {area:2261} – склепу на юго-западе зоны. {object:177667} лежит внутри: ключ от него у персонажа {npc:12248} на дальнем северо-востоке, это будет в следующем гайде.",
		["Cross the river west to {npc:1855}'s hut."] = "Перейдите реку на запад к хижине {npc:1855}.",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Пересеките юг кратера и вернитесь к {npc:9619} у спуска.",
		["Diseased Grizzlies"] = "Болезненные гризли",
		["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "Дальше на западе роются земляные сокрушители; в тех же песках охотятся камнехвостые клешневики, камнехвостые живодеры и скальные пауки-скакуны.",
		["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "Землечерпы роются в дюнах к северо-западу от крепости; повсюду бродят камнехвостые скорпиды и песчаные пауки-быстроноги.",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Завершается у NPC {npc:9298} (зона {zone:1452}): сохраните",
		["Escort {npc:9999}"] = "Сопроводите NPC {npc:9999}",
		["Fly from {area:976} to {area:541}. {npc:8737} stands at the back of the refuge; {npc:9117} is in the cave behind him.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "Летите из места {area:976} сюда: {area:541}. {npc:8737} стоит в глубине убежища; {npc:9117} – в пещере за ним.\nДруг {npc:9997}, {npc:9999}, пропал.",
		["Fly to Theramore"] = "Лететь на остров Терамор",
		["Fly to {area:2268}"] = "Летите сюда: {area:2268}",
		["Fly to {area:271}"] = "Летите сюда: {area:271}",
		["Fly to {area:976}"] = "Летите сюда: {area:976}",
		["For the druids of {zone:1457}: keep it"] = "Для друидов ({zone:1457}): сохраните задание",
		["For {area:3197}: keep it"] = "Для места {area:3197}: сохраните задание",
		["For {zone:1448}: keep it"] = "Для зоны {zone:1448}: сохраните задание",
		["For {zone:1451}: keep it"] = "Для зоны {zone:1451}: сохраните задание",
		["From Theramore, ride west into the {zone:1413} and north up the coast to {area:392}."] = "Из Терамора езжайте на запад ({zone:1413}) и на север вдоль побережья сюда: {area:392}.",
		["From {area:702}, fly to {area:1116}."] = "Летите: {area:702} → {area:1116}.",
		["Horgus' skull lies at {area:2624} and Marduk's sword in the {area:2623}, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "Череп Хоргуса лежит здесь: {area:2624}, а меч Мардука – здесь: {area:2623}; оба там, где сражаются призраки. На равнинах между ними охотятся взрослые чумные псы.",
		["Inside"] = "Внутри",
		["Into {zone:1451}"] = "В зону {zone:1451}",
		["Listen to his story"] = "Выслушайте его историю",
		["Mark {npc:10902} with the {item:12815}"] = "Отметьте предметом {item:12815}: {npc:10902}",
		["Mark {npc:10903} with the {item:12815}"] = "Отметьте предметом {item:12815}: {npc:10903}",
		["Mark {npc:10904} with the {item:12815}"] = "Отметьте предметом {item:12815}: {npc:10904}",
		["Mark {npc:10905} with the {item:12815}"] = "Отметьте предметом {item:12815}: {npc:10905}",
		["More watches"] = "Еще часы",
		["Northern Pylon"] = "Северный пилон",
		["On {npc:7583}"] = "У персонажа {npc:7583}",
		["Portal to {zone:1438}"] = "Портал: {zone:1438}",
		["Radley and Durgen"] = "Рэдли и Дурген",
		["Ranshalla in {zone:1452}: keep it"] = "Раншалла ({zone:1452}): сохраните задание",
		["Ride back south to the camp."] = "Езжайте назад на юг к лагерю.",
		["Ride back south-west to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "Езжайте обратно на юго-запад к башне ({area:2742}, {area:2738}); поднимитесь на нее и убейте засаду, которая появляется ради покрытого коркой предмета.",
		["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "Езжайте на восток к пограничной реке: {npc:1855} живет в маленькой хижине на берегу.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "Езжайте на восток к вулкану ({area:537}), поднимитесь на него и используйте {npc:10541} у лавовых отдушин у вершины.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Езжайте на север по восточной стороне к плато горилл. {npc:9622}, горилла 55-го уровня, сидит в самой глубокой пещере: сначала перебейте горилл у входа.",
		["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby."] = "Скачите на север сюда: {area:2627}. {npc:12384} живет в разрушенной хижине, а его книга расписок лежит в разрушенной таверне поблизости.",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "Езжайте по дороге на север к Лесопилке Северного Кряжа; {npc:11610} прячется на краю лагеря.",
		["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "Езжайте на северо-запад к ферме Далсона. Дневник лежит в амбаре; ключ от нужника носит бродячий скелет, а {npc:10836} ждет в нужнике с ключом от шкафчика.",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "Езжайте на северо-запад: {area:2276}, на краю зоны {area:2277}.",
		["Ride south to {area:201}, where {npc:11078} guards the cauldron."] = "Езжайте на юг: {area:201}; там котел охраняет {npc:11078}.",
		["Ride south-west to the camp."] = "Езжайте на юго-запад к лагерю.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Езжайте на юго-запад к лагерю ({npc:7771}): {area:1938}.",
		["Ride west along the road to the hot springs."] = "Езжайте по дороге на запад к горячим источникам.",
		["Ride west into the Ravenwind Ruins: {npc:7774} hides in the small round building at the back. Open the chest beside her for {item:9189}: it lasts 15 minutes, like the quest."] = "Езжайте на запад в Руины Воронова Ветра: {npc:7774} прячется в маленьком круглом здании в глубине. Откройте сундук рядом с ней ради предмета {item:9189}: он действует 15 минут, как и задание.",
		["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "Езжайте на запад: {area:2627}. По лесам бродят карликовые чумные псы, чумные нетопыри и личинки-падальщики; наполните предмет {item:15042} у больших термитников и убейте бесноватых чумных псов дальше к северу.",
		["Scare {npc:7583} with {item:12928}"] = "Напугайте {npc:7583} с помощью предмета {item:12928}",
		["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "Плывите на корабле на материк и езжайте на северо-восток к лагерю {npc:14637} (ориентир: {area:1119}).",
		["Ten {item:11040} from the {item:11020}"] = "Десять шт. {item:11040} из предмета {item:11020}",
		["The Andorhal watchtowers"] = "Сторожевые башни Андорала",
		["The Scarlet Crusade"] = "Алый орден",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "Медики, охотники, рыцари и маги из Алого ордена патрулируют лесопилку и дорогу к месту {area:190}.",
		["The Tar Beasts and Tar Lords wallow in the {area:538}, south of the refuge on the way down into the crater."] = "Смоляные чудища и смоляные повелители барахтаются здесь: {area:538} – к югу от убежища, по пути вниз в кратер.",
		["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "Котел стоит у фермы {npc:10739}: {area:202}.",
		["The cauldron sits at {area:200}, north-east of Felstone; its Cauldron Lord stands beside it."] = "Котел стоит к северо-востоку от поля Фелстоуна ({area:200}); рядом – его повелитель котла.",
		["The crater"] = "Кратер",
		["The gorillas live on {area:1943}, just east of the pylon: take the pelts for {npc:9619} now, while you are up here. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Гориллы живут здесь: {area:1943}, чуть к востоку от пилона. Соберите шкуры для {npc:9619} сейчас, пока вы наверху. Не заходите в самую глубокую пещеру: {npc:9622} – 55-го уровня.\nОсторожно: гориллы Ун'Горо (50–51-го уровня), потеряв 75% здоровья, зовут на помощь союзников в радиусе 20 ярдов. В этой местности есть пещера, полная обезьян, и бой там привлечет много противников.",
		["The shrunken giants roam the {area:1119}; the sea elementals wade along the coast to the west."] = "Уменьшенные великаны бродят здесь: {area:1119}; морские элементали – вдоль побережья к западу.",
		["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "Истерзанные друиды и часовые бродят по разрушенной деревне к юго-западу от {npc:13220}.",
		["The wooden sign beside {npc:9997}"] = "Деревянная табличка рядом с NPC {npc:9997}",
		["The {area:2742} tower"] = "Башня: {area:2742}",
		["The {item:11242} grows inside a ruined building north of {npc:7765}: climb in through the break in its wall from the ledge beside it."] = "{item:11242} растет внутри разрушенного здания к северу от {npc:7765}: заберитесь внутрь через пролом в стене с уступа рядом.",
		["Umber in {zone:1450}: keep it"] = "Умбер ({zone:1450}): сохраните задание",
		["Upstairs"] = "Наверху",
		["Use the {item:12627} by the grain silos to draw out Temporal Parasites. {quest:5154} is one of the musty tomes in the town hall. Every skeleton in town drops {quest:5537}."] = "Используйте {item:12627} у зернохранилищ, чтобы выманить временных паразитов. {quest:5154} – один из пыльных томов в ратуше. С каждого скелета в городе падает {quest:5537}.",
		["Use the {item:12815} at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp."] = "Используйте {item:12815} у подножия каждой из четырех сторожевых башен по краям Андорала, к северу от лагеря.",
		["Walk into {area:1769} and take the {zone:1450} branch of the tunnel to {area:2361}."] = "Войдите сюда: {area:1769} – и идите по ответвлению туннеля в зону {zone:1450}, до места {area:2361}.",
		["{area:190} overlook"] = "Обзорная точка: {area:190}",
		["{area:1943}: kill these as you meet them"] = "{area:1943}: убивайте их по пути",
		["{area:200} cauldron"] = "Котел: {area:200}",
		["{area:201} cauldron"] = "Котел: {area:201}",
		["{area:202} cauldron"] = "Котел: {area:202}",
		["{item:12894}, at the monument"] = "{item:12894} – у памятника",
		["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "{item:12954} лежит в ратуше ({area:190}) к западу от {npc:1855}: стражи Алого ордена стоят плотно.",
		["{item:12955} lies east of the barn at {area:201}."] = "{item:12955} лежит к востоку от амбара ({area:201}).",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal."] = "{npc:10667} ждет в разрушенной таверне в западной части Андорала.",
		["{npc:10878} and {npc:7740} stand by the Temple of the Moon; fill {item:11682} at the moonwell inside."] = "{npc:10878} и {npc:7740} стоят у Храма Луны; наполните {item:11682} у лунного колодца внутри.",
		["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "Дом {npc:10927} стоит на холме к востоку от лагеря; памятник ({npc:10936}) – чуть севернее.",
		["{npc:11886} is elite: grouping up is advised"] = "{npc:11886} – элитный противник: лучше собрать группу",
		["{npc:17082}, at the Alliance tents"] = "{npc:17082} – у палаток Альянса",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} – элитный противник 61-го уровня",
		["{npc:5411} in {area:976}: keep it"] = "{npc:5411} ({area:976}): сохраните задание",
		["{npc:5901}, on the coast north of town"] = "{npc:5901} – на побережье к северу от города",
		["{npc:7740}: keep it for {area:976}"] = "{npc:7740}: сохраните задание для места {area:976}",
		["{npc:7775}'s camp lies north of the {area:1119}. He brews the {item:11243} from an {item:11242}: take his errand for one."] = "Лагерь {npc:7775} – к северу (ориентир: {area:1119}). Он варит {item:11243} из предмета {item:11242}: возьмите его поручение ради него.",
		["{npc:7900}: keep it for {zone:1446}"] = "{npc:7900}: сохраните задание для зоны {zone:1446}",
		["{npc:8598}, 170 yd north-east"] = "{npc:8598} – 170 ярдов к северо-востоку",
		["{npc:9299} in {area:976}: keep it"] = "{npc:9299} ({area:976}): сохраните задание",
		["{npc:9299} is a ghost at the graveyard just east of town: drink a {item:11243} there, which kills you, release your spirit and talk to him as a ghost. Then run back to your body to come back to life: the gravestone stands nearby."] = "{npc:9299} – призрак на кладбище чуть к востоку от городка: выпейте там {item:11243} (он вас убьет), освободите дух и поговорите с ним в облике призрака. Затем бегите обратно к телу, чтобы ожить: надгробие стоит неподалеку.",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "Логово зверя {npc:9684} – в джунглях к северу от {npc:9619}, под восточными утесами: используйте там {item:11568}. {npc:9684} – 56-го уровня: начинайте бой с полным здоровьем.",
		["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999} сидит на юго-восточном склоне вулкана ({area:537}) в середине кратера.",
		["{quest:3444} is in {area:392}"] = "{quest:3444} – здесь: {area:392}",
		["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210} ({area:2268}): сохраните задание",
		["{quest:6762} in {zone:1450}: keep it"] = "{quest:6762} ({zone:1450}): сохраните задание",
		["{zone:1455}, where the next guide trains, has no druid trainer"] = "{zone:1455}, где следующий гайд посещает учителей, не имеет учителя друидов",
} end)()
t.guides["forever/alliance/50-60/05-silithus"] = (function() return {
		["Boat to {area:35}"] = "Корабль: {area:35}",
		["Chromie in Andorhal: keep it"] = "Хроми в Андорале: сохраните задание",
		["Fly from {area:541} to {area:392}."] = "Летите: {area:541} → {area:392}.",
		["Fly to {area:2268}"] = "Летите сюда: {area:2268}",
		["Fly to {zone:1453}"] = "Лететь в {zone:1453}",
		["For {npc:10778}: keep it"] = "Для персонажа {npc:10778}: сохраните задание",
		["Its jars are filled on the next Un'Goro visit"] = "Его флаконы наполняются при следующем посещении Кратера Ун'Горо",
		["Scourge Champions"] = "Воители Плети",
		["Scourge Champions (59) roam the {area:2270}, north of {area:2268}. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time."] = "Воители Плети (59) бродят здесь: {area:2270}, к северу от места {area:2268}. Проводите предметом {item:13156} {npc:11063} над каждым убитым: нужны ему черепа, которые резонируют. Выманивайте по одному.",
		["Take the boat from {area:392} to {area:35} and fly to {zone:1453}."] = "Плывите на корабле: {area:392} → {area:35}, затем летите в {zone:1453}.",
		["Tram to {zone:1455}"] = "Поезд до {zone:1455}",
		["{item:13155}, from the Scourge Champions"] = "{item:13155}: с воителей Плети",
		["{item:14613}, from {npc:11886}"] = "{item:14613}: с персонажа {npc:11886}",
		["{npc:332}, in SI:7"] = "{npc:332} – в здании ШРУ",
		["{npc:3520}, who walks the canals"] = "{npc:3520} – ходит вдоль каналов",
		["{quest:6184} at {area:3197}: keep it"] = "{quest:6184} ({area:3197}): сохраните задание",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Andorhal"] = "Андорал",
		["Angerclaw bears and Felpaw wolves"] = "Медведи злобных когтей и волки-сквернолапы",
		["Araj is elite: grouping up is advised."] = "Араж – элитный противник: лучше собрать группу.",
		["Below ground"] = "Под землей",
		["Boat to {area:150}"] = "Корабль: {area:150}",
		["Bronzebeard's Encampment"] = "Лагерь Бронзоборода",
		["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "Поднимитесь в центре кратера: {area:537} – и используйте {item:14644} у лавового озера наверху, имея в сумках два ториевых слитка. Наполните чистые флаконы для образцов от {npc:9616} на первобытных слизнюках в водоемах вокруг гряды.",
		["Fly to {area:271}"] = "Летите сюда: {area:271}",
		["Fly to {area:3137}"] = "Летите сюда: {area:3137}",
		["Fly to {area:3137} in {zone:1447} and ride west along the road to {area:2358}, just over the {zone:1440} border."] = "Летите сюда: {area:3137} ({zone:1447}) – и езжайте по дороге на запад: {area:2358}, сразу за границей зоны {zone:1440}.",
		["Fly to {area:976}"] = "Летите сюда: {area:976}",
		["Fly to {area:976}."] = "Летите сюда: {area:976}.",
		["Fly to {area:976}. Buy two Thorium Bars at the Auction House here for {quest:5801}."] = "Летите сюда: {area:976}. Купите здесь на аукционе два ториевых слитка для задания «{quest:5801}».",
		["Fly to {zone:1453}"] = "Лететь в {zone:1453}",
		["Follow the road north to {area:1767}. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north."] = "Идите по дороге на север: {area:1767}. Сердце носят топотуны Железнолесья; когти доберите с гризли злобных когтей и опустошителей-сквернолапов на севере.",
		["Follow {npc:9298}'s directions to the mouth of {area:2256}, past the Frostmaul giants: pass them one at a time."] = "Следуйте указаниям {npc:9298} ко входу сюда: {area:2256}, мимо великанов ледяного молота: проходите мимо них по одному.",
		["Hand him the ten texts you kept"] = "Отдайте ему десять сохраненных текстов",
		["Havunth's camp sits just west of {area:3425}."] = "Лагерь Хавунта – чуть западнее (ориентир: {area:3425}).",
		["Inside"] = "Внутри",
		["Irontree Stompers"] = "Топотуны Железнолесья",
		["Keep the {item:11169}, the claws and the heart he hands back"] = "Сохраните {item:11169}, когти и сердце, которые он вернет",
		["Learn the flight path in {area:2361}."] = "Откройте маршрут полета: {area:2361}.",
		["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "Подберите припасы вокруг повозки и заберите амулет {npc:10301} у совухов поблизости.",
		["Portal to {zone:1438}"] = "Портал: {zone:1438}",
		["Ride back south along the road to the Sanctuary."] = "Езжайте по дороге назад на юг к Святилищу.",
		["Ride back south-east to the hermit."] = "Езжайте назад на юго-восток к отшельнику.",
		["Ride back south-west to {area:3197}."] = "Езжайте назад на юго-запад: {area:3197}.",
		["Ride east into the hills. Use the {item:11169} to summon {quest:4005}, then defeat him for the totem."] = "Езжайте на восток в холмы. Используйте {item:11169}, чтобы призвать: {quest:4005}, затем победите его ради тотема.",
		["Ride east to the ruins of {area:2738}. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "Езжайте на восток к руинам ({area:2738}). {object:179565} лежит среди разрушенных зданий под охраной истерзанных часовых.",
		["Ride north along the west side to Mayna's small camp."] = "Езжайте на север вдоль западной стороны к маленькому лагерю Майны.",
		["Ride north to the Deadwood furbolgs' village by the {area:1769} cave mouth."] = "Езжайте на север к деревне фурболгов из племени Мертвого Леса у входа в пещеру ({area:1769}).",
		["Ride north to {area:541}. Use {npc:10980} beside {npc:10977}."] = "Езжайте на север: {area:541}. Используйте {npc:10980} рядом с персонажем {npc:10977}.",
		["Ride north up the road to the lumber mill and set the termite barrel down in the middle of it."] = "Езжайте по дороге на север к лесопилке и поставьте бочку с термитами в ее центре.",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand just south-east of the camp."] = "Езжайте на юго-запад к лагерю дворфов у южных гор и расспросите: {npc:15171} и {npc:15170}. Сумка {npc:15190} лежит в песке чуть юго-восточнее лагеря.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Езжайте на юго-запад к лагерю ({npc:7771}): {area:1938}.",
		["Running {area:2057} ({area:2298}, south-east {zone:1422}) or {area:2279} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "В группе быстрее пройти подземелье {area:2057} ({area:2298}, юго-восток зоны {zone:1422}) или {area:2279}, чем убивать мобов. Пропустите этот шаг, чтобы качаться в одиночку.",
		["Running {area:2577} in {zone:1444} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "В группе быстрее пройти подземелье {area:2577} ({zone:1444}), чем убивать мобов. Пропустите этот шаг, чтобы качаться в одиночку.",
		["Take the portal up to {zone:1457}."] = "Поднимитесь через портал: {zone:1457}.",
		["Take the road west down into the crater and ride to the {area:540}, the silithid cave in the south. The {npc:10041} waits in its deepest chamber."] = "Спуститесь по дороге на запад в кратер и езжайте к месту {area:540} – пещере силитидов на юге. {npc:10041} ждет в самом дальнем зале.",
		["Take the {area:1769} tunnel from its {zone:1452} mouth, west of {npc:9298}, and follow the {area:493} branch to {area:2361}. {npc:11939} studies by the lake shore."] = "Войдите в туннель ({area:1769}) со стороны зоны {zone:1452}, к западу от {npc:9298}, и идите по ответвлению ({area:493}) до места {area:2361}. {npc:11939} занимается исследованиями на берегу озера.",
		["Ten more for {quest:8323}"] = "Еще десять для задания «{quest:8323}»",
		["The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an {item:20404}: keep twenty, ten for {npc:15306} and ten for {npc:15194} later."] = "Раскопки культа Сумеречного Молота занимают северо-западный угол: фрагменты табличек лежат на земле, их также носят пылевихри и пустынные грохотуны. С любого культиста может упасть {item:20404}: сохраните двадцать – десять для персонажа {npc:15306} и десять позже для персонажа {npc:15194}.",
		["The flight lands in {area:702}. {npc:7916} stands a short walk north-west of the flight master."] = "Полет заканчивается здесь: {area:702}. {npc:7916} стоит недалеко к северо-западу от распорядителя полетов.",
		["The hermit hides among the rocks south-east of {area:2738}."] = "Отшельник прячется среди скал к юго-востоку (ориентир: {area:2738}).",
		["The {area:2479}"] = "{area:2479}",
		["The {area:3098}"] = "{area:3098}",
		["Tram to {zone:1455}"] = "Поезд до {zone:1455}",
		["Twilight Tablet Fragments"] = "Фрагменты Сумеречной таблички",
		["Twilight's Hammer cultists"] = "Культисты Сумеречного Молота",
		["Upstairs"] = "Наверху",
		["Use the jars on slain oozes"] = "Используйте флаконы на убитых слизнюках",
		["Wait a moment for {npc:9116}"] = "Подождите немного {npc:9116}",
		["grind on {npc:14564} at {area:2627}, {zone:1423}"] = "убивайте мобов ({npc:14564}): {area:2627}, {zone:1423}",
		["{area:1770} braziers"] = "Жаровни: {area:1770}",
		["{area:2057} (optional)"] = "{area:2057} (по желанию)",
		["{area:2057} fits levels 58 to 60; {quest:5505} is handed in at {area:3197} below."] = "{area:2057} подходит для 58–60 уровней; задание «{quest:5505}» сдается ниже ({area:3197}).",
		["{area:2577} (optional)"] = "{area:2577} (по желанию)",
		["{area:541} flight master"] = "Распорядитель полетов ({area:541})",
		["{npc:10301}'s camp"] = "Лагерь {npc:10301}",
		["{npc:10301}'s supplies"] = "Припасы {npc:10301}",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. {npc:1852} guards his phylactery in the middle of the town."] = "{npc:10667} ждет в разрушенной таверне в западной части Андорала – разрушенного города к северу от лагеря. {npc:1852} охраняет свою филактерию в центре города.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves."] = "Призрак {npc:10778} бродит у дома ({area:199}) к западу от Андорала. Вторую половину амулета носят болтливые вурдалаки на поле: соедините обе половины.",
		["{npc:11801}'s house stands in {area:2361}, east of {npc:11939}."] = "Дом ({npc:11801}) стоит здесь: {area:2361}, к востоку (ориентир: {npc:11939}).",
		["{npc:11803} holds the cultists' camp in the far south-west."] = "{npc:11803} удерживает лагерь культистов на дальнем юго-западе.",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722} – здесь: {object:2096}",
		["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} стоит наверху в своем здании: поднимитесь внутри, стрелка не различает этажи.",
		["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190} стоит наверху в своем здании: поднимитесь внутри, стрелка не различает этажи.",
		["{npc:15190}, upstairs beside {npc:15189}"] = "{npc:15190} – наверху, рядом с {npc:15189}",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} – элитный противник 61-го уровня",
		["{npc:1855} (optional)"] = "{npc:1855} (по желанию)",
		["{npc:1855} lives in a small hut on the border river, north-east of the lumber camp. Hand in {quest:5781} if you finished it."] = "{npc:1855} живет в маленькой хижине у пограничной реки, к северо-востоку от лесопилки. Сдайте задание «{quest:5781}», если выполнили его.",
		["{npc:3516}, atop the {area:1658}"] = "{npc:3516} – наверху ({area:1658})",
		["{npc:4155}, in the bank"] = "{npc:4155} – в банке",
		["{npc:7740} in {zone:1457}: keep it"] = "{npc:7740} ({zone:1457}): сохраните задание",
		["{npc:7740}, in the Temple of the Moon"] = "{npc:7740} – в Храме Луны",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737} – в глубине лагеря",
		["{quest:5085}: {npc:9298} in {zone:1452}, keep it"] = "{quest:5085}: {npc:9298} ({zone:1452}), сохраните задание",
		["{zone:1451}, {zone:1448}, {zone:1452} & the Plaguelands"] = "{zone:1451}, {zone:1448}, {zone:1452} и Чумные земли",
		["{zone:1453} has no shaman trainer"] = "В городе {zone:1453} нет учителя шаманов",
} end)()
t.guides["forever/alliance/dwarf/01-dun-morogh"] = (function() return {
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "Обратно через туннель к пещере {npc:257597} над фермой.",
		["Back to {area:77}"] = "Обратно: {area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "Вернитесь к NPC {npc:257446} ({area:77}). Он даст вам {item:6635}: идите по отмеченной камнями тропе, которая поднимается на запад с юга долины к камню духов на гребне, выпейте сапту рядом с ним и поговорите: {npc:5891}, затем принесите Тео {item:6656}.",
		["Back to {npc:257597}"] = "Вернитесь: {npc:257597}",
		["Below ground"] = "Под землей",
		["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "Скальные вепри и молодые черные медведи бродят по полям от лагеря Громобоя на северо-восток до места {area:131} и депо: убивайте их на обратном пути.",
		["Druid trainer"] = "Учитель друидов",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "Каждое задание Грифа Дикое Сердце дает вам {item:15908}: используйте его на названном звере, затем верните жезл ему в кузницу ({area:131}). Большие скальные вепри, снежные леопарды и медведи-ледолапы бродят по полям чуть южнее и восточнее места {area:131}.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Фарсен стоит лагерем на гребне, откуда с запада видно {area:134}. Поговорите с ним, чтобы получить его дальнее зрение.",
		["Feather Charms, from the Frostmane Novices"] = "Обереги из перьев, с новобранцев племени Мерзлогривов",
		["Firewood"] = "Дрова",
		["Flintfire's shipments lie on the cave floor, and {npc:278166} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "Грузы Кремнеграна лежат на полу пещеры, а {npc:278166} пропал где-то внутри.\nОсторожно: вендиго стоят в пещере плотно, поэтому в бою легко притянуть сразу нескольких; выманивайте их по одному дальними атаками снаружи.",
		["Follow the road east past the depot to {area:138}."] = "Идите по дороге на восток мимо депо сюда: {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Идите по дороге на северо-восток из места {area:131} к депо под дорогой в город {zone:1455}.",
		["From the {quest:2997} she gives you"] = "Из предмета {quest:2997}, который она вам дает",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Тролли-подростки из племени Мерзлогривов заполняют склоны к югу и востоку от лагеря {npc:786}.",
		["Heal and fortify {npc:12427}"] = "Исцелите и укрепите NPC {npc:12427}",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Подвески медведя-ледокогтя, с троллей-подростков из племени Мерзлогривов на склонах над лагерем",
		["Inside {area:77}"] = "Внутри: {area:77}",
		["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Выйдите из города {zone:1453} через главные ворота, идите на юг сюда: {area:87} и на восток по дороге сюда: {area:62}. {npc:881} (уровень 9) стоит у фермерского дома.",
		["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "Лепрогномы вокруг поселка Пивоваров и дороги к месту {area:133} носят шестеренки и зубчатки. Медведи-ледолапы, старые скальные вепри и снежные леопарды бродят по холмам вокруг озера.",
		["Level 4 spells, before Gozwin's camp"] = "Заклинания 4-го уровня, до лагеря Гозвина",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Косматые молодые волки бродят по снегу чуть южнее места {area:77}.",
		["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Dark Iron Spies sneak around the lake shore east of the quarry; one of them drops the {item:274268}."] = "Душители из племени Каменной Челюсти у места {area:212}, к северу от карьера, и хребтоломы Каменной Челюсти дальше на восток оставляют {quest:95214}. Шпионы Черного Железа крадутся по берегу озера к востоку от карьера; один из них оставляет {item:274268}.",
		["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "Головоломы, костоломы и душители из племени Каменной Челюсти населяют карьер и склоны к северу от него; душители оставляют {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Троггы и сильные троггы из племени Каменной Челюсти копают по всему дну долины к югу от места {area:77}.",
		["Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with {npc:1241} and {skill:129} with {npc:2326} in {area:131}, mining and engineering at {area:189}."] = "Сядьте у костра Эрика (введите /sit) и дождитесь эффекта. Если вы изучили профессию, Эрик также предложит задание «Основы походной жизни» для нее, которое сдается учителю этой профессии: кузнечное дело — NPC {npc:1241}, {skill:129} — NPC {npc:2326} ({area:131}), горное дело и инженерное дело — здесь: {area:189}.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Малые скальные вепри пасутся вокруг лагеря {npc:714} и вдоль западной стороны долины.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Снежные леопарды и вепри бродят по снегу между ранчо и карьером. Кузнецы: медные слитки получают выплавкой ({item:2770}) или покупают у торговцев.",
		["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "Идите на юг по дороге сюда: {area:144}, по пути добирая уши, мясо и паучью сукровицу. {npc:1340} ходит по дороге через город.",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "Ясновидцы из племени Камнедробов (уровень 13) стоят среди троггов на юге места {area:923}, к югу от {npc:257808}; геоманты-туннельщики (уровень 12) работают здесь: {area:149}, в северной части озера. Троггы ходят группами, некоторые атакуют издалека: выманивайте по одному.",
		["Subdue the voidwalker"] = "Подчините демона Бездны",
		["The Fire Spirit Stone"] = "Камень духа огня",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "Жгучая бражка действует пять минут: идите прямо на север к NPC {npc:836} внутри места {area:77}.",
		["The boars"] = "Вепри",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "Дрова лежат в снегу вокруг замерзшего озера у приюта.",
		["The pilots stand at the depot; {npc:1269} is on the road back west, north of {area:131}."] = "Пилоты стоят у депо; {npc:1269} — на дороге обратно на запад, к северу от места {area:131}.",
		["The quarry troggs"] = "Троггы карьера",
		["The troggs"] = "Троггы",
		["The troll cave"] = "Пещера троллей",
		["The tunnel"] = "Туннель",
		["The {area:2257}"] = "{area:2257}",
		["The {object:269} in the basement"] = "{object:269} в подвале",
		["Upstairs"] = "Наверху",
		["Use the {item:6866} on {npc:6177}"] = "Используйте {item:6866} на NPC {npc:6177}",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Раз уж вы здесь: изучите владение посохами у NPC {npc:11867} ({object:2096}, 10 серебра); у оружия ближнего боя охотника важнее всего характеристики, а у двуручного их больше всего.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Раз уж вы здесь: изучите владение посохами у NPC {npc:11867} ({object:2096}, 10 серебра); при прокачке посох дает больше характеристик для заклинаний, чем одноручное оружие.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Раз уж вы здесь: изучите владение мечами у NPC {npc:11867} ({object:2096}, 10 серебра); с мечом в правой руке разбойник стабильно качается.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "Раз уж вы здесь: изучите навык {spell:202} у NPC {npc:11867} ({object:2096}, 10 серебра); с двуручным оружием паладин качается быстрее всего.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Раз уж вы здесь: изучите {spell:202} у NPC {npc:11867} ({object:2096}, 10 серебра); с двуручным оружием воин качается быстрее всего.",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Вы начинаете перед местом {area:77} — каменным залом в северной части долины. {npc:658} ждет у двери.",
		["Young wolves"] = "Молодые волки",
		["talk to the trainer"] = "поговорите с учителем",
		["{area:131} and the depot"] = "{area:131} и депо",
		["{area:77} is on the way north from {npc:786}'s camp to the tunnel: {npc:837}, the priest trainer inside, sends priests of level 5 to {npc:1226} in {area:131}."] = "{area:77} находится по пути на север от лагеря {npc:786} к туннелю: {npc:837}, учитель жрецов внутри, отправляет жрецов 5-го уровня к NPC {npc:1226} ({area:131}).",
		["{item:13850}: the {object:176785}"] = "{item:13850}: {object:176785}",
		["{item:277976}, in the camp"] = "{item:277976}, в лагере",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "{item:286325} — у замерзшего озера, среди ледяных элементалей.",
		["{item:3083}: Leper Gnomes"] = "{item:3083}: лепрогномы",
		["{item:3084}: Leper Gnomes"] = "{item:3084}: лепрогномы",
		["{item:5026} and the {item:6652}"] = "{item:5026} и {item:6652}",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}: геоманты-туннельщики",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, рядом с камнем духов",
		["{item:6636}, beside the Spirit Stone"] = "{item:6636}, рядом с камнем духов",
		["{item:6652}: Stonesplinter Seers"] = "{item:6652}: ясновидцы из племени Камнедробов",
		["{item:6847}: Dark Iron Spies"] = "{item:6847}: шпионы из клана Черного Железа",
		["{npc:10090} in {zone:1455} takes it"] = "Сдается NPC {npc:10090} ({zone:1455})",
		["{npc:1126}: tame it with the {item:15908}"] = "{npc:1126}: приручите с помощью предмета {item:15908}",
		["{npc:1127}, on the way"] = "{npc:1127}, по пути",
		["{npc:1196}: tame it with the {item:15908}"] = "{npc:1196}: приручите с помощью предмета {item:15908}",
		["{npc:1201}, on the way"] = "{npc:1201}, по пути",
		["{npc:1201}: tame it with the {item:15908}"] = "{npc:1201}: приручите с помощью предмета {item:15908}",
		["{npc:1226}, upstairs: {item:16605}"] = "{npc:1226}, наверху: {item:16605}",
		["{npc:1226}: heal {npc:12427} south of {area:131}"] = "{npc:1226}: исцелите NPC {npc:12427} к югу от места {area:131}",
		["{npc:1231}, at the smithy"] = "{npc:1231}, у кузницы",
		["{npc:12427} kneels wounded on the ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer, on the walk back from Rumbleshot's camp. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12427} стоит раненый на коленях на гребне между двумя низкими стенами чуть южнее места {area:131}, через дорогу от учителя питомцев охотников, на обратном пути из лагеря Громобоя. Примените к нему {spell:613} (ранг 2), затем {spell:1243}: {spell:613} 1-го ранга не засчитывается.",
		["{npc:1252} stands by Eric's campfire in front of the {area:2102}; {npc:1241} is in the cellar west of it."] = "{npc:1252} стоит у костра Эрика перед зданием {area:2102}; {npc:1241} — в подвале к западу от него.",
		["{npc:1269}, on the way back; below ground"] = "{npc:1269}, на обратном пути; под землей",
		["{npc:12738}, next to him"] = "{npc:12738}, рядом с ним",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}: на время, пять минут, чтобы добраться до {npc:836} ({area:77})",
		["{npc:1377}, beside him"] = "{npc:1377}, рядом с ним",
		["{npc:1698}: blacksmiths only"] = "{npc:1698}: только для кузнецов",
		["{npc:1702}, beside {npc:5392}"] = "{npc:1702}, рядом с NPC {npc:5392}",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965} охраняет туннель из долины к востоку от места {area:77}; {npc:6782} стоит рядом с ним у входа.",
		["{npc:1977}, in the quarry"] = "{npc:1977}, в карьере",
		["{npc:2326}, inside the distillery"] = "{npc:2326}, внутри пивоварни",
		["{npc:257446}, inside {area:77}"] = "{npc:257446}, внутри: {area:77}",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}: {npc:5873} и ваш {item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597} ждет в пещере над фермой к северо-западу от места {area:806}; тропа наверх начинается за фермой.",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {npc:2523}, ваш {item:5176} и {item:263412}",
		["{npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "{npc:257808} дает вам {item:6636}. Поднимитесь на вершину над его лагерем, выпейте сапту рядом с камнем духов и победите NPC {npc:5893}, затем положите {item:6655} сюда: {object:61934}, на вершине Святилища Вечного Пламени.",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}: сдается NPC {npc:257597} у Южных ворот",
		["{npc:265813}: for {npc:1241}, in the cellar west of the distillery"] = "{npc:265813}: для NPC {npc:1241}, в подвале к западу от пивоварни",
		["{npc:265813}: for {npc:1702} at {area:189}"] = "{npc:265813}: для NPC {npc:1702} ({area:189})",
		["{npc:265813}: for {npc:2326} in the {area:2102}"] = "{npc:265813}: для NPC {npc:2326} ({area:2102})",
		["{npc:265813}: for {npc:5392} at {area:189}"] = "{npc:265813}: для NPC {npc:5392} ({area:189})",
		["{npc:2756} stands by {npc:8416} at the door of {area:77}. Gozwin's camp is in the hills just north-west; the {npc:269075} prowls around it."] = "{npc:2756} стоит рядом с {npc:8416} у двери ({area:77}). Лагерь Гозвина — на холмах чуть северо-западнее; вокруг него бродит {npc:269075}.",
		["{npc:460}, inside {area:77}"] = "{npc:460}, внутри: {area:77}",
		["{npc:5392}, at the depot"] = "{npc:5392}, у депо",
		["{npc:5480} trains warriors in {object:2100}, near Osric's shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480} обучает воинов здесь: {object:2100}, рядом с лавкой Осрика; поезд из зоны {zone:1455} прибывает сюда: {object:28027}, к северу от него. {npc:6089} и {npc:6090} стоят вместе у таверны ({object:2152}). {npc:6090} сражается с вами за свою кружку. Если {npc:5480} не предлагает задание {quest:1638}, идите сразу к NPC {npc:6089}: он дает задание {quest:1639} и без него.",
		["{npc:5505} in {zone:1453}; {zone:1426} has no druid trainer"] = "{npc:5505}, Зона: {zone:1453}; в зоне {zone:1426} нет учителя друидов",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: сдается NPC {npc:6122} ({zone:1453})",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122} ждет в подвале здания {object:2164} ({object:2101}).",
		["{npc:6179}: Redemption"] = "{npc:6179}: Искупление",
		["{npc:658}: a rune for {npc:895}"] = "{npc:658}: руна для NPC {npc:895}",
		["{npc:658}: read the {quest:98581}"] = "{npc:658}: прочитайте {quest:98581}",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, рядом со {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "Лагерь {npc:714} — в западной части долины. {item:10438} лежит в снегу к югу от него, сундук Феликса — у пещеры троллей, а феликсово ведро с гайками — к востоку от пещеры: подберите их по пути.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} и {npc:12738} стоят лагерем на юго-западной окраине долины, под пещерой троллей.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} находится внутри пещеры троллей к востоку от лагеря {npc:786}, а не на холме над ней: войдите в устье и идите по туннелю до конца.",
		["{npc:837}, inside {area:77}"] = "{npc:837}, внутри: {area:77}",
		["{npc:837}, the priest trainer"] = "{npc:837}, учитель жрецов",
		["{npc:895}, the hunter trainer"] = "{npc:895}, учитель охотников",
		["{npc:916}, the rogue trainer"] = "{npc:916}, учитель разбойников",
		["{npc:926}, the paladin trainer"] = "{npc:926}, учитель паладинов",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, у почтового ящика ({object:171524})",
		["{zone:1453} flight master"] = "Распорядитель полетов: {zone:1453}",
} end)()
t.guides["forever/alliance/gnome/01-dun-morogh"] = (function() return {
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "Обратно через туннель к пещере {npc:257597} над фермой.",
		["Back to {area:77}"] = "Обратно: {area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "Вернитесь к NPC {npc:257446} ({area:77}). Он даст вам {item:6635}: идите по отмеченной камнями тропе, которая поднимается на запад с юга долины к камню духов на гребне, выпейте сапту рядом с ним и поговорите: {npc:5891}, затем принесите Тео {item:6656}.",
		["Back to {npc:257597}"] = "Вернитесь: {npc:257597}",
		["Below ground"] = "Под землей",
		["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "Скальные вепри и молодые черные медведи бродят по полям от лагеря Громобоя на северо-восток до места {area:131} и депо: убивайте их на обратном пути.",
		["Druid trainer"] = "Учитель друидов",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Фарсен стоит лагерем на гребне, откуда с запада видно {area:134}. Поговорите с ним, чтобы получить его дальнее зрение.",
		["Feather Charms, from the Frostmane Novices"] = "Обереги из перьев, с новобранцев племени Мерзлогривов",
		["Firewood"] = "Дрова",
		["Flintfire's shipments lie on the cave floor, and {npc:278166} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "Грузы Кремнежара лежат на полу пещеры, а {npc:278166} пропал где-то внутри.\nОсторожно: вендиго стоят в пещере плотно, и в бою легко привлечь сразу нескольких; чтобы этого избежать, выманивайте их по одному атаками издалека снаружи.",
		["Follow the road east past the depot to {area:138}."] = "Идите по дороге на восток мимо депо сюда: {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Идите по дороге на северо-восток из места {area:131} к депо под дорогой в город {zone:1455}.",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Тролли-подростки из племени Мерзлогривов заполняют склоны к югу и востоку от лагеря {npc:786}.",
		["Heal and fortify {npc:12427}"] = "Исцелите NPC {npc:12427} и наложите на него стойкость",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Подвески медведя-ледокогтя, с троллей-подростков из племени Мерзлогривов на склонах над лагерем",
		["Inside {area:77}"] = "Внутри: {area:77}",
		["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Выйдите из города {zone:1453} через главные ворота, идите на юг сюда: {area:87} и на восток по дороге сюда: {area:62}. {npc:881} (уровень 9) стоит у фермерского дома.",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Выйдите из города {zone:1453} через главные ворота. Водопад ({quest:1861}) – к юго-западу от ворот, по пути на запад в зону {zone:1436}: наполните {item:7207} у его подножия.",
		["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "Лепрогномы вокруг поселка Пивоваров и дороги к месту {area:133} носят шестеренки и зубчатки. Медведи-ледолапы, старые скальные вепри и снежные леопарды бродят по холмам вокруг озера.",
		["Level 4 spells, before Gozwin's camp"] = "Заклинания 4-го уровня, до лагеря Гозвина",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Косматые молодые волки бродят по снегу чуть южнее места {area:77}.",
		["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Dark Iron Spies sneak around the lake shore east of the quarry; one of them drops the {item:274268}."] = "Душители из племени Каменной Челюсти у места {area:212}, к северу от карьера, и хребтоломы Каменной Челюсти дальше на востоке оставляют {quest:95214}. Шпионы из клана Черного Железа крадутся по берегу озера к востоку от карьера; один из них оставляет {item:274268}.",
		["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "Головоломы, костоломы и душители из племени Каменной Челюсти населяют карьер и склоны к северу от него; душители оставляют {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Троггы и сильные троггы из племени Каменной Челюсти копают по всему дну долины к югу от места {area:77}.",
		["Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with {npc:1241} and {skill:129} with {npc:2326} in {area:131}, mining and engineering at {area:189}."] = "Сядьте у костра Эрика (введите /sit) и дождитесь эффекта. Если вы изучили профессию, Эрик также предлагает для нее задание «Основы походной жизни», которое сдается учителю этой профессии: кузнечное дело — NPC {npc:1241}, {skill:129} — NPC {npc:2326} ({area:131}), горное дело и инженерное дело — здесь: {area:189}.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Малые скальные вепри пасутся вокруг лагеря {npc:714} и вдоль западной стороны долины.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Снежные леопарды и вепри бродят по снегу между ранчо и карьером. Кузнецы: медные слитки получают выплавкой ({item:2770}) или покупают у торговцев.",
		["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "Идите на юг по дороге сюда: {area:144}, по пути добирая уши, мясо и паучью сукровицу. {npc:1340} ходит по дороге через поселок.",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "Ясновидцы из племени Камнедробов (уровень 13) стоят среди троггов на юге места {area:923}, к югу от {npc:257808}; геоманты-туннельщики (уровень 12) работают здесь: {area:149}, в северной части озера. Троггы ходят группами, некоторые атакуют издалека: выманивайте по одному.",
		["Subdue the voidwalker"] = "Подчините демона Бездны",
		["The Fire Spirit Stone"] = "Камень духа огня",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "Жгучая бражка действует пять минут: идите прямо на север к NPC {npc:836} внутри места {area:77}.",
		["The boars"] = "Вепри",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "Дрова лежат в снегу вокруг замерзшего озера у приюта.",
		["The pilots stand at the depot; {npc:1269} is on the road back west, north of {area:131}."] = "Пилоты стоят у депо; {npc:1269} — на дороге обратно на запад, к северу от места {area:131}.",
		["The quarry troggs"] = "Троггы карьера",
		["The troggs"] = "Троггы",
		["The troll cave"] = "Пещера троллей",
		["The tunnel"] = "Туннель",
		["The {area:2257}"] = "{area:2257}",
		["The {object:269} in the basement"] = "{object:269} в подвале",
		["Upstairs"] = "Наверху",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Раз уж вы здесь: изучите владение посохами у NPC {npc:11867} ({object:2096}, 10 серебра); у оружия ближнего боя охотника важнее всего характеристики, а у двуручного их больше всего.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Раз уж вы здесь: изучите владение посохами у NPC {npc:11867} ({object:2096}, 10 серебра); при прокачке посох дает больше характеристик для заклинаний, чем одноручное оружие.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Раз уж вы здесь: изучите владение мечами у NPC {npc:11867} ({object:2096}, 10 серебра); с мечом в правой руке разбойник стабильно качается.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "Раз уж вы здесь: изучите навык {spell:202} у NPC {npc:11867} ({object:2096}, 10 серебра); с двуручным оружием паладин качается быстрее всего.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Раз уж вы здесь: изучите {spell:202} у NPC {npc:11867} ({object:2096}, 10 серебра); с двуручным оружием воин качается быстрее всего.",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Вы начинаете перед местом {area:77} — каменным залом в северной части долины. {npc:658} ждет у двери.",
		["Young wolves"] = "Молодые волки",
		["talk to the trainer"] = "поговорите с учителем",
		["{area:131} and the depot"] = "{area:131} и депо",
		["{area:77} is on the way north from {npc:786}'s camp to the tunnel: {npc:837}, the priest trainer inside, sends priests of level 5 to {npc:1226} in {area:131}."] = "{area:77} — по пути на север от лагеря {npc:786} к туннелю: {npc:837}, учитель жрецов внутри, отправляет жрецов 5-го уровня к NPC {npc:1226} ({area:131}).",
		["{item:13850}: the {object:176785}"] = "{item:13850}: {object:176785}",
		["{item:277976}, in the camp"] = "{item:277976}, в лагере",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "{item:286325} — у замерзшего озера, среди ледяных элементалей.",
		["{item:3083}: Leper Gnomes"] = "{item:3083}: лепрогномы",
		["{item:3084}: Leper Gnomes"] = "{item:3084}: лепрогномы",
		["{item:5026} and the {item:6652}"] = "{item:5026} и {item:6652}",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}: геоманты-туннельщики",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, рядом с камнем духов",
		["{item:6636}, beside the Spirit Stone"] = "{item:6636}, рядом с камнем духов",
		["{item:6652}: Stonesplinter Seers"] = "{item:6652}: ясновидцы из племени Камнедробов",
		["{npc:1127}, on the way"] = "{npc:1127}, по пути",
		["{npc:1201}, on the way"] = "{npc:1201}, по пути",
		["{npc:1226}, upstairs: {item:16605}"] = "{npc:1226}, наверху: {item:16605}",
		["{npc:1226}: heal {npc:12427} south of {area:131}"] = "{npc:1226}: исцелите NPC {npc:12427} к югу от места {area:131}",
		["{npc:1226}: {npc:258785} in {zone:1455} takes it"] = "{npc:1226}: сдается NPC {npc:258785} ({zone:1455})",
		["{npc:1241}, in the cellar west of the distillery"] = "{npc:1241}, в погребе к западу от пивоварни",
		["{npc:12427} kneels wounded on the ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer, on the walk back from Rumbleshot's camp. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12427} стоит раненым на коленях на гребне между двумя низкими стенами чуть южнее места {area:131}, через дорогу от учителя питомцев охотников, на обратном пути из лагеря Громобоя. Примените к нему {spell:613} (ранг 2), затем {spell:1243}: {spell:613} 1-го ранга не засчитывается.",
		["{npc:1252} stands by Eric's campfire in front of the {area:2102}; {npc:1241} is in the cellar west of it."] = "{npc:1252} стоит у костра Эрика перед местом {area:2102}; {npc:1241} — в погребе к западу от него.",
		["{npc:1269}, on the way back; below ground"] = "{npc:1269}, на обратном пути; под землей",
		["{npc:12738}, next to him"] = "{npc:12738}, рядом с ним",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}: на время, пять минут, чтобы добраться до {npc:836} ({area:77})",
		["{npc:1377}, beside him"] = "{npc:1377}, рядом с ним",
		["{npc:1698}: blacksmiths only"] = "{npc:1698}: только для кузнецов",
		["{npc:1702}, beside {npc:5392}"] = "{npc:1702}, рядом с NPC {npc:5392}",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965} охраняет туннель из долины к востоку от места {area:77}; {npc:6782} стоит рядом с ним у входа.",
		["{npc:1977}, in the quarry"] = "{npc:1977}, в карьере",
		["{npc:2326}, inside the distillery"] = "{npc:2326}, внутри пивоварни",
		["{npc:257446}, inside {area:77}"] = "{npc:257446}, внутри: {area:77}",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}: {npc:5873} и ваш {item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597} ждет в пещере над фермой к северо-западу от места {area:806}; тропа наверх начинается за фермой.",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {npc:2523}, ваш {item:5176} и {item:263412}",
		["{npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "{npc:257808} дает вам {item:6636}. Поднимитесь на вершину над его лагерем, выпейте сапту рядом с камнем духов и победите NPC {npc:5893}, затем положите {item:6655} сюда: {object:61934}, на вершине Святилища Вечного Пламени.",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}: сдается NPC {npc:257597} у Южных ворот",
		["{npc:265813}: for {npc:1241}, in the cellar west of the distillery"] = "{npc:265813}: для NPC {npc:1241}, в погребе к западу от пивоварни",
		["{npc:265813}: for {npc:1702} at {area:189}"] = "{npc:265813}: для NPC {npc:1702} ({area:189})",
		["{npc:265813}: for {npc:2326} in the {area:2102}"] = "{npc:265813}: для NPC {npc:2326} ({area:2102})",
		["{npc:265813}: for {npc:5392} at {area:189}"] = "{npc:265813}: для NPC {npc:5392} ({area:189})",
		["{npc:2756} stands by {npc:8416} at the door of {area:77}. Gozwin's camp is in the hills just north-west; the {npc:269075} prowls around it."] = "{npc:2756} стоит рядом с {npc:8416} у двери ({area:77}). Лагерь Гозвина — на холмах чуть северо-западнее; вокруг него бродит {npc:269075}.",
		["{npc:460}, inside {area:77}"] = "{npc:460}, внутри: {area:77}",
		["{npc:5392}, at the depot"] = "{npc:5392}, у депо",
		["{npc:5480} trains warriors in {object:2100}, near Osric's shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480} обучает воинов здесь: {object:2100}, возле лавки Осрика; поезд из зоны {zone:1455} прибывает сюда: {object:28027}, к северу от него. {npc:6089} и {npc:6090} стоят вместе у таверны ({object:2152}). {npc:6090} сражается с вами за свою кружку. Если {npc:5480} не предлагает задание {quest:1638}, идите сразу к NPC {npc:6089}: он дает задание {quest:1639} и без него.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} стоит в башне магов ({object:2101}); она дает вам флягу для водопада ({quest:1861}).",
		["{npc:5505} in {zone:1453}; {zone:1426} has no druid trainer"] = "{npc:5505}, Зона: {zone:1453}; в зоне {zone:1426} нет учителя друидов",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: сдается NPC {npc:6122} ({zone:1453})",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122} ждет в подвале здания {object:2164} ({object:2101}).",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, рядом со {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "Лагерь {npc:714} — в западной части долины. {item:10438} лежит в снегу к югу от него, сундук Феликса — у пещеры троллей, а феликсово ведро с гайками — к востоку от пещеры: подберите их по пути.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} и {npc:12738} стоят лагерем на юго-западной окраине долины, под пещерой троллей.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} находится внутри пещеры троллей к востоку от лагеря {npc:786}, а не на холме над ней: войдите в устье и идите по туннелю до конца.",
		["{npc:837}, inside {area:77}"] = "{npc:837}, внутри: {area:77}",
		["{npc:837}, the priest trainer"] = "{npc:837}, учитель жрецов",
		["{npc:912}, the warrior trainer"] = "{npc:912}, учитель воинов",
		["{npc:916}, the rogue trainer"] = "{npc:916}, учитель разбойников",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}, учитель магов, внутри: {area:77}",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, у почтового ящика ({object:171524})",
		["{zone:1453} flight master"] = "Распорядитель полетов: {zone:1453}",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "\"Тетушка\" Бернис Стоунфилд",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Назад к {npc:6122}. Используйте {item:6928} у круга призыва в подвале ({object:2164}) и победите призванного демона Бездны.",
		["Back to {zone:1429}"] = "Назад: {zone:1429}",
		["Billy plays in the {area:64}, east of the mine."] = "Билли играет здесь: {area:64}, к востоку от рудника.",
		["Chunks of Boar Meat"] = "Куски кабанины",
		["Class trainer"] = "Учитель классовых навыков",
		["Crystal Kelp Fronds"] = "Ветки хрустального фукуса",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Волшебники-плуты из Братства Справедливости стоят лагерем на берегах ({area:86}); с них падают и красные льняные банданы. {object:56} лежит в деревне мурлоков на северо-восточном берегу.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Лиходеи из Братства Справедливости стоят лагерем на поляне к востоку от аббатства и вдоль восточного края долины.",
		["Druid trainer"] = "Учитель друидов",
		["Follow the hills south to the tower, on the road west."] = "Идите по холмам на юг к башне, по дороге на запад.",
		["Follow the hills south to the tower."] = "Идите по холмам на юг к башне.",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "Идите по тропе на север к руднику. Снаружи кишат кобольды-рабочие; {object:83763} может упасть с любого кобольда в долине.",
		["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "Идите по дороге на восток мимо места {area:91} к мосту. Добейте лесных хищников и молодых лесных медведей у реки к югу от него.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Идите по дороге на север от места {area:87} в город {zone:1453}. {npc:5497} стоит в башне ({object:2101}); она даст вам флягу для водопада ({quest:1861}).",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Идите по дороге на север от места {area:87} в город {zone:1453}. {npc:6122} ждет в подвале ({object:2164}, {object:2101}).",
		["Follow the road south out of the valley to {area:87}. {npc:240} stands outside the smithy on the west side of the road, {npc:241} by the road south of it, and {npc:295} and {npc:253} in the Lion's Pride Inn across the road."] = "Идите по дороге на юг из долины. Цель: {area:87}. {npc:240} стоит у кузницы на западной стороне дороги, {npc:241} – у дороги к югу от нее, а {npc:295} и {npc:253} – в таверне «Гордость льва» через дорогу.",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Идите по дороге на юг из места {area:87}. Цель: {area:64}. {npc:251} ждет у дома.",
		["Follow the road south to the {area:120}, on the way into {zone:1436}. {npc:963} stands outside the barracks; {npc:955} stands inside. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "Идите по дороге на юг. Цель: {area:120}, по пути в зону {zone:1436}. {npc:963} стоит у казарм; {npc:955} – внутри. Задание {quest:91738} есть у него, только пока у вас {item:247824}: поговорите с ним, и оно сразу перейдет к сдаче.",
		["Follow the road west back to {area:87}; {npc:6306} stands on the lake shore before town. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Идите по дороге на запад обратно. Цель: {area:87}; {npc:6306} стоит на берегу озера перед городком. {npc:377} (жрецы), {npc:328} (маги) и {npc:917} (разбойники) – на втором этаже таверны: поднимитесь по лестнице внутри, стрелка не различает этажи.",
		["Fun with Elementals: {npc:248464}"] = "«Забавы с элементалями»: {npc:248464}",
		["He stands by the river west of the farm."] = "Он стоит у реки к западу от фермы.",
		["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Возвращайтесь через {area:87} и на восток вдоль дороги к {area:62}. {npc:881} (9 уровня) стоит у фермерского домика.",
		["Head east out of {area:87} along the lake shore. {npc:383} stands on the shore north-east of town."] = "Идите на восток из места {area:87} вдоль берега озера. {npc:383} стоит на берегу к северо-востоку от городка.",
		["Heal and fortify {npc:12423}"] = "Исцелите и укрепите: {npc:12423}",
		["If you skipped {quest:91740}, grind here to level 8.85 to stay on the route's plan."] = "Если вы пропустили {quest:91740}, убивайте монстров здесь до уровня 8.85, чтобы не отставать от маршрута.",
		["If you skipped {quest:91752}, grind here to level 5.48 to stay on the route's plan."] = "Если вы пропустили {quest:91752}, убивайте монстров здесь до уровня 5.48, чтобы не отстать от маршрута.",
		["If you skipped {quest:91752}, grind here to level 5.77 to stay on the route's plan."] = "Если вы пропустили {quest:91752}, убивайте монстров здесь до уровня 5.77, чтобы не отстать от маршрута.",
		["If you skipped {quest:91775}, grind here to level 8.39 to stay on the route's plan."] = "Если вы пропустили {quest:91775}, убивайте монстров здесь до уровня 8.39, чтобы не отставать от маршрута.",
		["Inside"] = "Внутри",
		["Inside {area:34}"] = "Внутри: {area:34}",
		["It lies by the river north-west of the logging camp."] = "Оно лежит у реки к северо-западу от лесозаготовок.",
		["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right.\nCareful: {npc:248362} (3) is elite: leave him unless you have a friend."] = "В туннелях рудника работают кобольды-работники. {npc:248362} ждет за вторым поворотом направо.\nОсторожно: {npc:248362} (3) – элитный противник: не трогайте его, если вы не с другом.",
		["Large Candles"] = "Большие свечи",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Выйдите из города {zone:1453} через главные ворота. Водопад ({quest:1861}) – к юго-западу от ворот, по пути на запад в зону {zone:1436}: наполните {item:7207} у его подножия.",
		["Level 5.48"] = "Уровень 5.48",
		["Level 5.77"] = "Уровень 5.77",
		["Level 8.39"] = "Уровень 8.39",
		["Level 8.85"] = "Уровень 8.85",
		["Lost Books: Kobold Miners and Tunnelers"] = "Потерянные книги: кобольды-шахтеры и кобольды-проходчики",
		["Mages: {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "Маги: {npc:198}, учитель магов, стоит на втором этаже аббатства: поднимитесь по лестнице внутри, стрелка не различает этажи.",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "Мурлоки и речные мурлоки-бегуны занимают восточный берег; груды мусора лежат в их лагере. Осторожно: мурлоки стоят близко друг к другу, поэтому в бою легко привлечь сразу двух-трех: выманивайте их по одному с края лагеря и не преследуйте убегающего до следующей группы.",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake."] = "К северо-востоку от лесозаготовок. Волшебники-плуты из Братства Справедливости стоят лагерем на берегах озера.",
		["Painted Gnoll Armbands"] = "Раскрашенные поручи гнолла",
		["Red Burlap Bandanas"] = "Красные холщовые банданы",
		["Red Linen Bandanas"] = "Красные льняные банданы",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "Недоростки и гонцы стаи Речной Лапы занимают холмы к югу от гарнизона, вдоль границы с зоной {zone:1436}.",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Гноллы из стаи Речной Лапы стоят лагерем на холмах к западу (ориентир: {area:86}); {quest:91725} лежат в их лагерях.",
		["Shaman trainer"] = "Учитель шаманов",
		["She stands by her cart at the vineyard east of the Abbey."] = "Она стоит у своей тележки на винограднике к востоку от аббатства.",
		["She stands outside the mine entrance. {npc:248362}, inside, is elite: grouping up is advised."] = "Она стоит у входа в рудник. {npc:248362} внутри – элита: лучше собрать группу.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Спелые красные яблоки: продает {npc:894}, для задания {quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Сядьте (/sit) у его костра, пока не получите эффект «{spell:1229451}»",
		["South down the road to the {area:64}."] = "По дороге на юг. Цель: {area:64}.",
		["Subdue the voidwalker"] = "Одолейте демона Бездны",
		["Tame {npc:1922}"] = "Приручить: {npc:1922}",
		["Tame {npc:524}"] = "Приручить: {npc:524}",
		["Tame {npc:822}"] = "Приручить: {npc:822}",
		["The Defias camp"] = "Лагерь Братства Справедливости",
		["The Fishing Traps sit along the west shore of the lake."] = "Ловушки ({object:694772}) стоят вдоль западного берега озера.",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "Ферма Стоунфилдов – к западу от рудника. Мамаша и \"Тетушка\" Бернис стоят у дома.\nОна сидит в доме на ферме.",
		["The bridge"] = "Мост",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "Лагерь – к северо-востоку от моста. Вязанки дров лежат вокруг лагеря и в лесу к северу от него.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Ящики с виноградом лежат на виноградниках за Братством Справедливости. {npc:103} ждет у хижины в восточном конце долины.",
		["The gnoll camps"] = "Лагеря гноллов",
		["The kobold camp"] = "Лагерь кобольдов",
		["The lake shore"] = "Берег озера",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: {npc:471} (7-10), the Mine Spiders (7-9) and {npc:248474} (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend."] = "Рудник – к юго-западу от лагерей гноллов. {item:247816} лежат у входа; туннели занимают кобольды-геоманты.\nОсторожно: {npc:471} (7-10), рудниковые пауки (7-9) и {npc:248474} (7) – элитные противники в глубине рудника: выманивайте кобольдов по одному у входа и отступайте, если подходит элитный; с другом проще.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "Рудник – к западу от виноградников. Оба уровня полны кобольдов-шахтеров и кобольдов-проходчиков; книжка с картинками – у NPC {npc:248464}, именного кобольда в нижних туннелях. {npc:248464} – элита: лучше собрать группу.",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too."] = "Фукус падает с мурлоков на восточном берегу. Для снятия шкур: серые лесные волки бродят по лесу между озером и местом {area:91}; шкуры дают и лесные хищники дальше к востоку.",
		["The vineyards and {npc:103}"] = "Виноградники и {npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Prowlers and Young Forest Bears on the way. Careful: {npc:248278} is a level 11 elite on the murloc shore. Only go for his head with a group or once you're level 10; otherwise leave him: it's optional."] = "{item:247813}, топор и ящик с инструментами лежат в реке к югу от моста. {npc:330}, большая свинья, роется здесь: {area:62}, к западу от реки, вместе с поросятами ({npc:390}): сначала отманите поросят. По пути убивайте лесных хищников и молодых лесных медведей. Осторожно: {npc:248278} – элита 11-го уровня на берегу мурлоков. Идите за его головой только с группой или с 10-го уровня; иначе не трогайте: это необязательно.",
		["The {quest:91736}"] = "{quest:91736}",
		["The {quest:91736} stands north of the {area:120}. Click it with four Shiny Red Apples in your bags: it takes them and gives you a {item:247824} on the spot (the quest never shows in your quest log). Keep the Applejack for {npc:955}: don't drink it."] = "{quest:91736} стоит к северу от места {area:120}. Щелкните по нему, имея в сумках четыре спелых красных яблока: он заберет их и сразу даст {item:247824} (задание не появляется в журнале заданий). Сохраните сидр для NPC {npc:955}: не пейте его.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248362} (level 3 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Это элитные противники: лучше собрать группу, поищите спутников. {npc:248362} (элита 3-го уровня) – нужна группа из 2 человек. Если вы один, пропустите: по маршруту вы доберете этот опыт убийством монстров.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248464} (level 6 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Это элитные противники: лучше собрать группу, поищите спутников. {npc:248464} (элита 6-го уровня) – нужна группа из 2 человек. Если вы один, пропустите: маршрут восполнит опыт за счет убийства монстров.",
		["Walk into the mine"] = "Войдите в рудник",
		["Walk through the mine"] = "Пройдите через рудник",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Раз уж вы здесь: изучите посохи у NPC {npc:11867} ({object:2096}, 10 серебра); при прокачке посох дает больше характеристик для заклинаний, чем одноручное оружие.",
		["Wolves"] = "Волки",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Вы начинаете перед аббатством. {npc:823} стоит у подножия лестницы, {npc:197} – в зале, {npc:951} и {npc:247229} – в библиотеке справа, {npc:196} – снаружи у северо-западного угла.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Молодые и лесные волки бродят по полям прямо вокруг аббатства.",
		["grind on {npc:118}"] = "убивайте: {npc:118}",
		["grind on {npc:40}"] = "убивайте: {npc:40}",
		["grind on {npc:80}"] = "убивайте: {npc:80}",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "его следопыт по кобольдам показывает, на каких кобольдов щелкать по дороге (цель: {area:87})",
		["talk to the trainer"] = "поговорите с учителем",
		["{area:18}: kill these as you meet them"] = "{area:18}: убивайте их по пути",
		["{area:34}: kill these as you meet them"] = "{area:34}: убивайте их по пути",
		["{area:54}: kill these as you meet them"] = "{area:54}: убивайте их по пути",
		["{area:64}: kill these as you meet them"] = "{area:64}: убивайте их по пути",
		["{item:247824}, from the still"] = "{item:247824}, из перегонного куба",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}: вепри-камнеклыки",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}: {object:83763} в лагере Братства Справедливости",
		["{item:981}; below ground"] = "{item:981}; под землей",
		["{npc:12423} kneels wounded by a tree on the west shore of {area:18}, among the Fishing Traps. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count. He walks off once both land and is back in about 3 minutes."] = "{npc:12423} лежит раненый у дерева на западном берегу ({area:18}), среди ловушек. Примените к нему {spell:613} (2-й ранг), затем {spell:1243}: 1-й ранг заклинания «{spell:613}» не засчитывается. Когда оба эффекта сработают, он уйдет и вернется примерно через 3 минуты.",
		["{npc:1430} cooks in the inn's kitchen. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:1430} готовит на кухне таверны. {npc:377} (жрецы), {npc:328} (маги) и {npc:917} (разбойники) стоят наверху в таверне: поднимитесь по лестнице внутри, стрелка не различает этажи.",
		["{npc:1430}: Camping 101 asks you to learn it; below ground"] = "{npc:1430}: «Походное дело для начинающих» просит выучить это; под землей",
		["{npc:1632}, beside {npc:6306}"] = "{npc:1632}, рядом с NPC {npc:6306}",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: приручите с помощью предмета {item:15908}",
		["{npc:197}, inside"] = "{npc:197}, внутри",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, учитель магов, в аббатстве",
		["{npc:2329}, in the Lion's Pride Inn"] = "{npc:2329}, в таверне «Гордость льва»",
		["{npc:240}, while William brews"] = "{npc:240}, пока Уильям варит зелье",
		["{npc:247229}, in the library; inside"] = "{npc:247229}, в библиотеке; внутри",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242} и {npc:248248} стоят у подножия башни.",
		["{npc:248278} is a level 11 elite on the murloc shore south of the bridge: grouping up is encouraged, look for people to do it with. {quest:91740} needs a group of 2. Skip it if you are alone: the route has you grind the XP back. Right-click the head for its quest."] = "{npc:248278}是桥南边鱼人河岸上的11级精英：建议组队，找人一起做。{quest:91740}需要2人小队。如果你独自一人就跳过：路线会让你把经验刷回来。右键点击它的头接取任务。",
		["{npc:248415} stands behind the Abbey, by the stables. {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:248415} стоит за аббатством, у конюшен. {npc:198}, учитель магов, стоит на втором этаже аббатства: поднимитесь по лестнице внутри, стрелка не различает этажи.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, у аббатства",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507} стоит с учителями ({area:87}). Каждое ее задание дает вам {item:15908}: используйте его на названном звере, затем верните жезл ей. Твердошкурые вепри и молодые лесные медведи бродят по холмам к югу от места {area:64}, серые лесные волки – по лесу к востоку (ориентир: {area:18}).",
		["{npc:253}, back in the inn"] = "{npc:253}, снова в таверне",
		["{npc:253}, inside"] = "{npc:253}, внутри",
		["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446} ({zone:1426}); {area:87}: учителя шаманов нет",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, рядом с ней: {spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261} охраняет мост на дороге к востоку; {npc:248265} стоит сразу за ним.",
		["{npc:263399} camps north-east of the inn. With a profession learned, he also offers its Camping 101, which its trainer takes: skinning, leatherworking and fishing on the lake shore, {skill:129} and blacksmithing in {area:87}."] = "{npc:263399} стоит лагерем к северо-востоку от таверны. Если у вас есть профессия, он также предложит «Походное дело для начинающих» по ней, которое принимает ее учитель: снятие шкур, кожевничество и рыбная ловля – на берегу озера, {skill:129} и кузнечное дело – в городке ({area:87}).",
		["{npc:263399}: for {npc:1632} on the lake shore"] = "{npc:263399}: для NPC {npc:1632} на берегу озера",
		["{npc:263399}: for {npc:1651} on the lake shore"] = "{npc:263399}: для NPC {npc:1651} на берегу озера",
		["{npc:263399}: for {npc:2329} in the Lion's Pride Inn"] = "{npc:263399}: для NPC {npc:2329} в таверне «Гордость льва»",
		["{npc:263399}: for {npc:514} at the {area:87} smithy"] = "{npc:263399}: для NPC {npc:514} в кузнице ({area:87})",
		["{npc:263399}: for {npc:6306} on the lake shore"] = "{npc:263399}: для NPC {npc:6306} на берегу озера",
		["{npc:278}, inside"] = "{npc:278}, внутри",
		["{npc:279} in {zone:1453} takes it (02-westfall)"] = "Его принимает {npc:279} ({zone:1453}) (02-westfall)",
		["{npc:295}, inside"] = "{npc:295}, внутри",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}: принимает {npc:5497} ({zone:1453})",
		["{npc:375}, the priest trainer"] = "{npc:375}, учитель жрецов",
		["{npc:375}, the priest trainer: {npc:377} in {area:87} takes it"] = "{npc:375}, учитель жрецов: его принимает {npc:377} ({area:87})",
		["{npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:377} (жрецы), {npc:328} (маги) и {npc:917} (разбойники) стоят наверху в таверне: поднимитесь по лестнице внутри, стрелка не различает этажи.",
		["{npc:377}, upstairs"] = "{npc:377}, наверху",
		["{npc:377}, upstairs: {item:16605}"] = "{npc:377}, наверху: {item:16605}",
		["{npc:377}: heal {npc:12423} at {area:18}"] = "{npc:377}: исцелите NPC {npc:12423} ({area:18})",
		["{npc:377}: {npc:376} in {zone:1453} takes it"] = "{npc:377}: его принимает {npc:376} ({zone:1453})",
		["{npc:459}, outside the Abbey"] = "{npc:459}, у аббатства",
		["{npc:476} walks around {area:54}: look inside the circle on the map"] = "{npc:476} ходит здесь: {area:54}: ищите внутри круга на карте",
		["{npc:514}, at the smithy across the road"] = "{npc:514}, в кузнице через дорогу",
		["{npc:514}, at the smithy beside Dughan: {npc:1416} in {zone:1453} takes it (02-westfall)"] = "{npc:514}, в кузнице рядом с Даганом: задание принимает {npc:1416} ({zone:1453}) (02-westfall)",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}: приручите с помощью предмета {item:15908}",
		["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "{npc:5504} ({zone:1453}); {area:87}: учителя друидов нет",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}: принимает {npc:6122} ({zone:1453})",
		["{npc:6306}, inside"] = "{npc:6306}, внутри",
		["{npc:6306}, on the lake shore east of town; inside"] = "{npc:6306}, на берегу озера к востоку от городка; внутри",
		["{npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:6306}, {npc:383} и {npc:1651} стоят на берегу к востоку от городка ({area:18}).",
		["{npc:6306}: skinners only, the pelts are skinned; inside"] = "{npc:6306}: только для снятия шкур, шкуры снимаются с добычи; внутри",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, у конюшен к югу от аббатства",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6} копаются на виноградниках к северо-востоку от аббатства. Иногда с них падает {quest:91741}: щелкните по нему правой кнопкой.",
		["{npc:80} walks around {area:34}: look inside the circle on the map"] = "{npc:80} ходит по месту {area:34}: ищите внутри круга на карте",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}: приручите с помощью предмета {item:15908}",
		["{npc:823}, at the Abbey steps"] = "{npc:823}, у лестницы аббатства",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, снова у лестницы аббатства",
		["{npc:894} sells the Shiny Red Apples for the {quest:91736}. Apples looted from kobolds and crates count too: the purchase ticks itself once you have four."] = "{npc:894} продает спелые красные яблоки для объекта {quest:91736}. Яблоки с кобольдов и из ящиков тоже подходят: покупка отметится сама, когда у вас будет четыре.",
		["{npc:911}, the warrior trainer; inside"] = "{npc:911}, учитель воинов; внутри",
		["{npc:915}, the rogue trainer"] = "{npc:915}, учитель разбойников",
		["{npc:925}, the paladin trainer"] = "{npc:925}, учитель паладинов",
		["{npc:952}, upstairs"] = "{npc:952}, наверху",
		["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955}: ему нужен ваш {item:247824}; внутри",
		["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963}: для {npc:234} у {area:108}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "{object:694855} растет на полях вокруг виноградников и фермы Стоунфилдов; кровь дают вепри-камнеклыки поблизости.\nВепри-камнеклыки пасутся между виноградниками и фермой.",
		["{quest:76}'s entrance"] = "Вход: {quest:76}",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it.\nCareful: {npc:248464} (6), a kobold deep in the mine, is elite, and {npc:79} (10, rare) walks the tunnels: pull the kobolds one at a time."] = "{quest:87} – внутри ({area:57}), а не на холме над ним: войдите и держитесь левее до дальнего конца нижнего уровня; по лестнице наверх не поднимайтесь. С бандитов из Братства Справедливости у виноградников иногда падает {item:1972}: щелкните по нему правой кнопкой.\nОсторожно: {npc:248464} (6), кобольд в глубине рудника, – элитный противник, а {npc:79} (10, редкий) бродит по туннелям: выманивайте кобольдов по одному.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} и {npc:330}",
		["{zone:1429}: kill these as you meet them"] = "{zone:1429}: убивайте их по пути",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "Сядьте (/sit) у костра {npc:265811}, пока не получите эффект «{spell:1229451}»",
		["Back at {area:256}"] = "Снова здесь: {area:256}",
		["Back to the moonwell."] = "Назад к лунному колодцу.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "Назад на вершину древа ({area:256}). {object:654846} лежит рядом с ним.",
		["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "Снова наверх, к персонажу {npc:3567}, когда тенетники перебиты и мох ({npc:272116}) у вас.",
		["Befouled Webwoods"] = "Оскверненные тенетники",
		["Below ground"] = "Под землей",
		["Bloodfeather harpies"] = "Гарпии из стаи Кровавого Пера",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Примените {spell:18960}. {npc:11802} – здесь: {area:2361}; {quest:5929} – в лесу к северо-западу. Затем {npc:11800} ({area:2361}) доставит друидов прямо сюда: {area:702} – маршрут полета не нужен. {npc:11802} стоит наверху в своем здании: поднимитесь внутри, стрелка не различает этажи.",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Каждое задание Дазалара дает вам предмет {item:15908}: примените его на названном звере, затем верните жезл ему ({area:186}). Чащобные тенетники ползают вокруг деревни, ночные саблезубы-охотники и совы-крикуны бродят по лесу к югу от нее.",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Выведите из обители: {npc:275744}; отчет принимает {npc:2081} ({area:186}).",
		["Fandral in {zone:1457} takes it"] = "Задание принимает Фэндрал ({zone:1457})",
		["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442}."] = "Летите обратно сюда: {area:702} – от {npc:3841}, отдайте {item:16263}: {npc:10118} на пристани, затем летите обратно ({area:442}).",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442}."] = "Еще раз летите сюда: {area:702} – и поднимитесь через портал к {npc:4217}, затем летите обратно ({area:442}).",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Идите по дороге на юго-запад из {area:188}. {npc:2150} сидит у дороги чуть восточнее места {area:186}.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Душители из племени Кривой Сосны прячутся вдоль дороги к западу от места {area:258}.",
		["Gnarlpine Shamans"] = "Шаманы из племени Кривой Сосны",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Спуститесь обратно: {area:702}, затем летите сюда: {area:442}. {object:177525} стоит на холмах чуть восточнее деревни: используйте там {item:15208}, победите Лунокогтя и поговорите: {npc:12144}.",
		["Grells"] = "Грелли",
		["Heal and fortify {npc:12429}"] = "Исцелите и укрепите: {npc:12429}",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Покиньте долину ({area:188}) по тропе к юго-востоку от древа ({area:256}): {npc:6780} стоит рядом с ней, где она спускается к дороге на Доланаар ({area:186}).",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside. {npc:8584} waits in the trees west of the cave mouth."] = "Облезлые ночные саблезубы и щетинистые вепри бродят к северу от древа ({area:256}), по пути к пещере. {npc:1994} – в ее глубине. {npc:8584} ждет среди деревьев к западу от входа в пещеру.",
		["Nightsabers"] = "Ночные саблезубы",
		["North to {area:257}"] = "На север: {area:257}",
		["North-east from Ursal's den, back to {area:186}."] = "От логова Урсала на северо-восток, назад: {area:186}.",
		["North-west of Dolanaar, on the way to the {area:264}, Befouled Webwoods creep through the woods; {npc:272116} prowls at their east edge and carries the {item:281023}.\n{npc:272116} is elite (level 12): grouping up is advised. Clear the webwoods around him first and pull him on his own."] = "К северо-западу от Доланаара, по пути сюда: {area:264} – по лесу ползают оскверненные тенетники; {npc:272116} рыщет у их восточного края и носит {item:281023}.\n{npc:272116} – элитный противник (12-й уровень): рекомендуется собрать группу. Сначала перебейте тенетников вокруг него, затем выманите его одного.",
		["Sentinel Arynia again"] = "Снова часовой Арания",
		["South from the glade toward Ursal: Shayla walks the road west of {area:186}, from where the path down from the glade meets it south-west to the bend at about 38,54 and back."] = "С поляны на юг к Урсалу: Шейла ходит по дороге к западу от места {area:186} – от места, где к ней спускается тропа с поляны, на юго-запад до поворота примерно у 38,54 и обратно.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "К юго-востоку от Доланаара: {npc:2080}. Вокруг него на берегу бродят плеточники-ростки.",
		["South-west of the barrow. The moonwell sits by the pools."] = "К юго-западу от обители. Лунный колодец – у озер.",
		["Speak with the {quest:5929}"] = "Поговорите: {quest:5929}",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Снова идите по дороге на северо-запад от места {area:186}; она по-прежнему лежит у дороги, по пути в город {zone:1457}.",
		["The WANTED poster outside the inn"] = "Плакат «РАЗЫСКИВАЕТСЯ» у таверны",
		["The moonwell"] = "Лунный колодец",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "Лунный колодец – в центре поляны. {object:6752} растет в ее северной части.",
		["The named harpies"] = "Именные гарпии",
		["The road to {zone:1457}"] = "Дорога в город {zone:1457}",
		["The road west to the {area:264} runs through {area:186}: hand {npc:3567} the jewel on the way."] = "Дорога на запад ({area:264}) проходит через {area:186}: по пути отдайте самоцвет: {npc:3567}.",
		["The trainers stand upstairs inside {area:256}, along the ramp that winds up the tree: {npc:3593} and {npc:3594} on the first level, {npc:3595} above them, {npc:3596} and {npc:3597} at the top. The arrow cannot tell the levels apart."] = "Учителя стоят наверху внутри древа ({area:256}), вдоль пандуса, вьющегося вверх: {npc:3593} и {npc:3594} – на первом ярусе, {npc:3595} – выше, {npc:3596} и {npc:3597} – на вершине. Стрелка не различает ярусы.",
		["The {area:478}"] = "{area:478}",
		["The {object:177525}"] = "{object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "{object:4406} лежат в глубине пещеры ({area:257}): идите по центральному проходу, на развилке налево, вверх до высокого уступа. Гиацинтовые грибы падают с греллей, лунные лилии растут у прудов к северу от древа ({area:256}).",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Прибрежные крабы снуют по берегу под деревней; {quest:983} стоит на пляже чуть южнее пристани. На мелководье плавают крепкозубы Темного берега. {object:175207} лежит на берегу чуть южнее деревни.",
		["Upstairs"] = "Наверху",
		["Use the {item:18152} at the moonwell"] = "Используйте {item:18152} у лунного колодца",
		["Use the {item:5185} at the moonwell"] = "Используйте {item:5185} у лунного колодца",
		["Use the {item:5619} at the moonwell"] = "Используйте {item:5619} у лунного колодца",
		["Use the {item:5621} at the moonwell"] = "Используйте {item:5621} у лунного колодца",
		["Walk Lynessa out and keep her alive"] = "Выведите Линессу, не дав ей погибнуть",
		["Webwood Lurkers"] = "Чащобные тенетники",
		["West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "На запад по дороге к городу. Шейла ходит по этому участку дороги – от стрелки на юго-запад до поворота примерно у 38,54 и обратно: если ее нет у стрелки, идите по дороге на юго-запад. Клыки падают с любого фурболга из племени Кривой Сосны: подходят и душители на этой дороге, и фурболги из обители, и из лагеря ({area:261}).",
		["West from the webwoods to the {area:265}, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors."] = "От тенетников на запад к реке ({area:265}), затем на север вдоль нее до поляны: мшистые опухоли падают с древесников на ее берегах.",
		["With a profession learned, {npc:265811} also offers its Camping 101, which its trainer takes: alchemy and herbalism beside {npc:6286}, {skill:129} with {npc:6094} in the inn, skinning and leatherworking at the Maneweavers' camp on the road west."] = "Если вы изучили профессию, {npc:265811} также предлагает задание «Походное дело для начинающих», которое принимает учитель этой профессии: алхимия и травничество – рядом с персонажем {npc:6286}, {skill:129} – {npc:6094} в таверне, снятие шкур и кожевничество – в лагере Гривотков на дороге к западу.",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "Вы начинаете у подножия великого древа ({area:256}, {area:188}).",
		["Young Nightsabers and Young Thistle Boars roam around {area:256}. Grells carry {item:3297} in the woods west of the tree, where the Gnarlpine Totems stand."] = "Вокруг древа ({area:256}) бродят молодые ночные саблезубы и молодые щетинистые вепри. {item:3297} носят грелли в лесу к западу от древа, где стоят тотемы племени Кривой Сосны.",
		["talk to the trainer"] = "поговорите с учителем",
		["{area:186} again"] = "Снова здесь: {area:186}",
		["{area:258}'s mouth"] = "Вход: {area:258}",
		["{area:736}, outside the barrow"] = "{area:736} – снаружи обители",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "{item:159}: продает {npc:6736}, для персонажа {npc:6094}",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "{item:3371}: продает {npc:3614}, рядом с персонажем {npc:6094}",
		["{npc:10216}, on the pier"] = "{npc:10216} – на пристани",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401} – в Храме Луны: Звездные осколки",
		["{npc:12429} kneels wounded on the rocks at the north edge of {area:259}, on the walk back to {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count. She runs off once both land and is back in about 5 minutes."] = "{npc:12429} лежит раненая на камнях у северного края озера ({area:259}), по пути обратно ({area:186}); над ней нет значка задания. Примените на нее «{spell:613}» (2-й уровень), затем «{spell:1243}»: 1-й уровень заклинания «{spell:613}» не засчитывается. Когда оба заклинания сработают, она убегает и возвращается примерно через 5 минут.",
		["{npc:1992}, south of the tree"] = "{npc:1992} – к югу от древа",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}: приручите его с помощью предмета {item:15908}",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}: приручите его с помощью предмета {item:15908}",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038} ждет в пещере, внизу или наверху на уступе; держитесь правой стороны.",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}: приручите его с помощью предмета {item:15908}",
		["{npc:2077}, by the path"] = "{npc:2077} – у тропы",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}: знак для персонажа {npc:3596}",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}: задание принимает {quest:922} ({zone:1457})",
		["{npc:2082}, on the tree's ramp"] = "{npc:2082} – на пандусе древа",
		["{npc:2107} stands upstairs in a house in the village, east of the moonwell: go up inside, the arrow cannot tell the floors apart. {object:126158} is in the house on the hill at the east end of the village."] = "{npc:2107} стоит наверху в доме в деревне, к востоку от лунного колодца: поднимитесь внутри, стрелка не различает этажи. {object:126158} – в доме на холме в восточной части деревни.",
		["{npc:2151} patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her."] = "{npc:2151} патрулирует дорогу к западу от деревни: если ее нет у стрелки, идите по дороге, пока не встретите ее.",
		["{npc:2151}, on the road west of the village"] = "{npc:2151} – на дороге к западу от деревни",
		["{npc:265811}, by the campfire"] = "{npc:265811} – у костра",
		["{npc:265811}: for {npc:3603}, beside {npc:6286}"] = "{npc:265811}: для персонажа {npc:3603}, рядом с персонажем {npc:6286}",
		["{npc:265811}: for {npc:3604}, beside {npc:6286}"] = "{npc:265811}: для персонажа {npc:3604}, рядом с персонажем {npc:6286}",
		["{npc:265811}: for {npc:3605}, by the road west"] = "{npc:265811}: для персонажа {npc:3605}, у дороги к западу",
		["{npc:265811}: for {npc:6094} in the inn"] = "{npc:265811}: для персонажа {npc:6094} в таверне",
		["{npc:265811}: for {npc:6287}, by the road west"] = "{npc:265811}: для персонажа {npc:6287}, у дороги к западу",
		["{npc:272034} and {npc:272044} fly just west of the moonwell, {npc:272046} further north."] = "{npc:272034} и {npc:272044} летают чуть западнее лунного колодца, {npc:272046} – дальше к северу.",
		["{npc:3514}, at the top of the tree"] = "{npc:3514} – на вершине древа",
		["{npc:3515}, south of the inn"] = "{npc:3515} – к югу от таверны",
		["{npc:3516}, in the {area:1658}"] = "{npc:3516} – здесь: {area:1658}",
		["{npc:3519}, by the moonwell"] = "{npc:3519} – у лунного колодца",
		["{npc:3567}: {quest:932}'s Befouled Webwoods and the elite {npc:272116}'s moss, on the walk to the {area:264}"] = "{npc:3567}: оскверненные тенетники для задания «{quest:932}» и мох элитного противника ({npc:272116}) – по пути сюда: {area:264}",
		["{npc:3594}, the rogue trainer"] = "{npc:3594} – учитель разбойников",
		["{npc:3595}, the priest trainer, on the second level of {area:256} on the way down: {npc:3600} in {area:186} takes it"] = "{npc:3595} – учитель жрецов, на втором ярусе древа ({area:256}) по пути вниз: задание принимает {npc:3600} ({area:186})",
		["{npc:3596}, the hunter trainer"] = "{npc:3596} – учитель охотников",
		["{npc:3597}, the druid trainer at {area:256}"] = "{npc:3597} – учитель друидов ({area:256})",
		["{npc:3600}: heal {npc:12429} by {area:259}"] = "{npc:3600}: исцелите персонажа {npc:12429} у озера ({area:259})",
		["{npc:3600}: {npc:11401} in {zone:1457} takes it"] = "{npc:3600}: задание принимает {npc:11401} ({zone:1457})",
		["{npc:3602}: {npc:4217} in {zone:1457} takes it"] = "{npc:3602}: задание принимает {npc:4217} ({zone:1457})",
		["{npc:3603}, beside {npc:6286}"] = "{npc:3603} – рядом с персонажем {npc:6286}",
		["{npc:3604}, beside {npc:6286}"] = "{npc:3604} – рядом с персонажем {npc:6286}",
		["{npc:3605}, beside {npc:6287}"] = "{npc:3605} – рядом с персонажем {npc:6287}",
		["{npc:3649}, north end of the village"] = "{npc:3649} – в северной части деревни",
		["{npc:4092}, in the Temple of the Moon"] = "{npc:4092} – в Храме Луны",
		["{npc:4146} in {zone:1457} takes it"] = "Задание принимает {npc:4146} ({zone:1457})",
		["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{npc:4146} ({area:1658}): {spell:5149}",
		["{npc:4217}, in the {area:1658}"] = "{npc:4217} – здесь: {area:1658}",
		["{npc:4241}, on the {area:1659} just inside the city"] = "{npc:4241} – {area:1659}, сразу у входа в город",
		["{npc:6094}, in the inn"] = "{npc:6094} – в таверне",
		["{npc:6287}, camped beside the road before Shayla"] = "{npc:6287} – в лагере у дороги, не доходя до Шейлы",
		["{npc:7999}, above {npc:4092}"] = "{npc:7999} – выше, над персонажем {npc:4092}",
		["{npc:8583}, east of the tree"] = "{npc:8583} – к востоку от древа",
		["{object:673378}, just west of the moonwell"] = "{object:673378} – чуть западнее лунного колодца",
