t.guides["forever/class/rogue/poisons-alliance"] = (function() return {
		["Back to {npc:7207}"] = "Назад: {npc:7207}",
		["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "В Forever ядам учит эта цепочка, а не учитель; вместе с ними вы получите рецепт: {item:7676}.",
		["Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {spell:8681} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon."] = "Идите на север через Элвиннский лес в город {zone:1453}; Матиас Шоу – наверху в здании ШРУ. Он обучает навыку «Яды» и дает рецепт: {item:7676}. Яды не покупают, а делают: на каждую партию {spell:8681} нужны {item:2928} и {item:3371}, которые продают {npc:1325} и {npc:1326} здесь: {object:2100}, рядом со ШРУ. Купите по стопке каждого, откройте «Яды» в книге заклинаний, чтобы изготовить их, затем нанесите яд на оружие.",
		["Poisons (Alliance)"] = "Яды (Альянс)",
		["The cure's ingredients"] = "Ингредиенты лекарства",
		["{spell:921} the {npc:7051} for the {item:7923}"] = "{spell:921}: {npc:7051} – добудьте {item:7923}",
} end)()
t.guides["forever/class/rogue/poisons-horde"] = (function() return {
		["/salute {npc:3401}"] = "/salute: {npc:3401}",
		["Back to {npc:3401}"] = "Вернитесь: {npc:3401}",
		["Fly back to {zone:1454} ({area:392} or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {spell:8681} takes one of each."] = "Летите обратно в город {zone:1454} (из места {area:392} или с Перекрестка; быстрее умереть у башни и вернуться к Перекрестку через целителя душ). Потом сохраните {item:8072}. Прежде чем покинуть {area:263}, купите у Реккула {item:2928} и пустые колбы: когда Хинотт обучит вас ядам, на каждую партию {spell:8681} понадобится по одному из каждого.",
		["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "В Forever яды изучаются через эту цепочку, а не у учителя; заодно вы получаете рецепт: {item:7676}.",
		["Pick Pocket Foreman Silixiz for {item:8072}"] = "Обшарьте карманы бригадира Силиксиза: {item:8072}",
		["Poisons (Horde)"] = "Яды (Орда)",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {spell:8681} from Rekkul's dust and vials, and use it on your weapon."] = "Сядьте на дирижабль из города {zone:1454} в {zone:1458} и идите по дороге на юг через зону {zone:1421} в {area:287}, к поселению {area:272}. {npc:2391} работает в здании рядом с точкой полетов, возле NPC {npc:2216}, снаружи стоит повозка. Если вы потеряли образец смеси Занзила, откажитесь от задания и возьмите его снова у NPC {npc:3401}. Постойте рядом с ним около минуты, пока он варит лекарство; если оно так и не будет готово, откажитесь от задания и возьмите его у него снова. Затем откройте «Яды» в книге заклинаний, чтобы сделать {spell:8681} из пыли и колб Реккула, и нанесите яд на оружие.",
		["Wait for the cure"] = "Дождитесь лекарства",
		["{item:8074}: {npc:7288} (elite)"] = "{item:8074}: {npc:7288} (элитный)",
		["{npc:2391}: Poisons"] = "{npc:2391}: Яды",
		["{quest:2458}: keep the {item:8051}"] = "{quest:2458}: сохраните {item:8051}",
} end)()
