t.guides["forever/class/warlock/incubus-horde"] = (function() return {
		["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "На 20-м уровне: суккуб и инкуб из Forever – ее брат-близнец мужского пола, – каждый с сумкой для осколков душ.",
		["Succubus and Incubus (Horde)"] = "Суккуб и инкуб (Орда)",
		["{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-27) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so the guide waits for level 24 first (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes."] = "{area:422} – на юге зоны {zone:1440}, к юго-западу от места {area:431}. Чащобные камнедвиги и заскорузлые потрошители (25-27 уровень) у озера роняют {item:190232} примерно в одном случае из двадцати, и одинокий {npc:3931} (30) тоже может его уронить: рассчитывайте на немало убийств, поэтому гайд сначала ждет 24-го уровня (в Forever это задание 27-го уровня); если суккуб уже подчинена, можно отложить его до прокачки на 20-х уровнях в зоне {zone:1440}. Они возрождаются через пять минут.",
} end)()
t.guides["forever/class/warlock/orb-of-orahil"] = (function() return {
		["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "Сфера для левой руки или посох ближе к 40-му уровню – на выбор путь гончей Скверны или инфернала.",
		["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "На 35-м уровне {npc:3326} ({object:172960}) отправит вас сюда: {npc:6266} ({area:392}).",
		["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "На 35-м уровне {npc:4563} ({object:36082}) отправит вас сюда: {npc:6266} ({area:392}). Дирижабль из зоны {zone:1420} летит в зону {zone:1411}.",
		["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "На 35-м уровне {npc:461} ({object:2164}, {object:2101}) отправит вас сюда: {npc:6266} ({area:392}).",
		["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "На 35-м уровне {npc:5172} ({zone:1455}) отправит вас сюда: {npc:6266} ({area:392}).",
		["Choose an acolyte"] = "Выберите послушника",
		["Orb of Orahil"] = "Сфера Орахила",
		["The demon's spirit"] = "Дух демона",
		["The {item:15107}"] = "{item:15107}",
		["The {item:15108}"] = "{item:15108}",
		["{item:12649}, from a {npc:4676}"] = "{item:12649}, добыча: {npc:4676}",
		["{item:7291}, from the Burning Blade Summoners"] = "{item:7291}: призыватели из клана Пылающего Клинка",
		["{npc:6252}: he gives you the {item:12646}"] = "{npc:6252}: он даст вам {item:12646}",
		["{npc:6254}: she gives you the {item:12647}"] = "{npc:6254}: она даст вам {item:12647}",
		["{npc:6546} lives at her farm in the middle of {zone:1445}, south of the road from the {zone:1413} and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Hand in the orb now; Cleansing waits for level 38. Before you accept it, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the {npc:6549} out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or {spell:710} and damage over time, a level 38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from {npc:6546} again."] = "{npc:6546} живет на своей ферме в центре зоны {zone:1445}, к югу от дороги из зоны {zone:1413} и к юго-западу от Терамора; рядом стоит целитель душ. Зыбун, кроколиск 45-го уровня, патрулирует ручьи чуть к северо-востоку. Сдайте сферу сейчас; «Очищение» ждет 38-го уровня. Прежде чем взять его, перебейте пауков и кроколисков вокруг ее загона. Когда вы берете задание, запускается 3-минутный таймер: она идет к загону и выпускает противника {npc:6549}. Он элитный (40-й уровень): лучше собрать группу; чернокнижник около 40-го уровня справится в одиночку со «Страхом» или {spell:710} и периодическим уроном, на 38-м возьмите друга. Таймер идет и после убийства, поэтому сдайте задание сразу. Если время вышло, откажитесь от задания и снова возьмите его у NPC {npc:6546}.",
} end)()
t.guides["forever/class/warlock/orb-of-soranruk"] = (function() return {
		["A rare off-hand orb or staff for your 20s, for fragments from two dungeons."] = "Редкая сфера для левой руки или посох для 20-х уровней за фрагменты из двух подземелий.",
		["Back to {npc:6247}"] = "Назад: {npc:6247}",
} end)()
t.guides["forever/class/warlock/shard-of-the-green-flame"] = (function() return {
		["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "Редкий предмет для левой руки на 50+ уровне от {npc:14469} и {npc:14470} (зона {zone:1448}); в том же лагере дают задание «Просьба беса».",
		["Back to {npc:14469}"] = "Вернитесь к {npc:14469}",
		["{area:1763} lies just south of {area:1997}, west of the road. The guide waits for level 53 first: its Legionnaires are 55. Of its two caves, {area:1770} is the northern one, further up the hill; the other has no Legionnaires. {area:1770}'s tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward {npc:9516}'s chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of {area:1763} and {area:1770} are all hostile."] = "{area:1763} – чуть южнее места {area:1997}, к западу от дороги. Сначала гайд ждет 53-го уровня: его легионеры – 55-го. Из двух пещер {area:1770} – северная, выше по склону; в другой легионеров нет. Туннели ({area:1770}) идут на север под холмами, а джеденарские легионеры (55-й уровень) стоят в дальних залах, от первых пандусов до покоев NPC {npc:9516}; в ближнем бою они бьют «Апперкотом». Эссенция падает в трех случаях из четырех, но появляется их всего около одиннадцати: расчистите путь и, если нужно, переждите пятиминутное возрождение. Все культисты ({area:1763}, {area:1770}) враждебны.",
		["{item:18626}, at {object:179677}"] = "{item:18626} — у объекта {object:179677}",
} end)()
t.guides["forever/class/warlock/tome-of-sacrifice"] = (function() return {
		["A rare off-hand at 60, {npc:14463}'s payment for capturing a {npc:12396} in the {zone:1419}."] = "Редкий предмет для левой руки на 60-м уровне — плата {npc:14463} за поимку NPC {npc:12396} (зона: {zone:1419}).",
		["Back to {npc:14463}"] = "Обратно к {npc:14463}",
} end)()
