} end)()
t.guides["forever/class/warrior/brutal-armor"] = (function() return {
		["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "На 20-м уровне {npc:3041}, учитель воинов ({zone:1456}), отправляет вас к NPC {npc:6394} ({area:378}).",
		["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "На 20-м уровне {npc:3354} ({object:172958}) отправляет вас к NPC {npc:6394} ({area:378}).",
		["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "На 20-м уровне {npc:4595}, учитель воинов ({zone:1458}), отправляет вас к NPC {npc:6394} ({area:378}).",
		["Hillsbrad Miners"] = "Хилсбрадские шахтеры",
		["Iron Bars"] = "Железные слитки",
		["Iron Bars: {npc:8673}"] = "Железные слитки: {npc:8673}",
		["Roogug in {area:1717}"] = "Ругуг. Локация: {area:1717}",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, his guards come with him. The guide waits for level 26 first. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Ругуг – элитный свинобраз (28-й уровень) в подземелье {area:1717} на южной окраине зоны {zone:1413}; подземелье на пятерых: нужна группа из пяти человек, с ним приходят его стражи. Сначала гайд ждет 26-го уровня. Внутри на первой развилке идите налево, перейдите мост из лиан над свинарниками, пройдите мимо зала с большим котлом: он ждет в зале справа. Он применяет {spell:403} и призывает земляных грохотунов. Флакон падает всегда.",
		["The Dragonmaw orcs (level 26-30) camp in the middle of the {zone:1437}; from {area:321} in Arathi head south over the {area:881} ({area:150} is Alliance). With {quest:1846} from {npc:6411} in your log, every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a {item:7131} (without the quest they drop none): right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast {spell:686}, Bonewarders raise skeletons."] = "Орки клана Драконьей Пасти (уровни 26-30) стоят лагерем в центре зоны {zone:1437}; из места {area:321} в Арати идите на юг через {area:881} ({area:150} принадлежит Альянсу). Если в журнале есть задание {quest:1846} от NPC {npc:6411}, с каждого налетчика, болотного бегуна, центуриона, хранителя теней и костостража падает {item:7131} (без задания не падает ничего): щелкните по ней правой кнопкой мыши, чтобы проверить; примерно одна из четырех оказывается прочной, остальные ломаются, так что на 8 штук понадобится 30 убийств или больше. Проверять можно на ходу или в бою. Орки убегают за помощью при 15% здоровья; налетчики набрасывают сеть, центурионы бьют щитом, хранители теней применяют {spell:686}, костостражи поднимают скелетов.",
		["You need 10 {item:7127}. The guide waits for level 25 first. The Hillsbrad Miners (level 26-27) work the mine in the hills west of {area:271} and drop the azurite four kills in five; they fight in {spell:71}, sunder your armor and run for help at 30% health. Fly to {area:272} and head south-west."] = "Нужно 10 шт. {item:7127}. Сначала гайд ждет 25-го уровня. Хилсбрадские шахтеры (26-27 уровень) работают в шахте на холмах к западу от места {area:271} и роняют азурит в четырех случаях из пяти; они дерутся в защитной стойке ({spell:71}), раскалывают вашу броню и при 30% здоровья бегут за подмогой. Летите сюда: {area:272}, и идите на юго-запад.",
		["{item:6841}, from Roogug"] = "{item:6841} с Ругуга",
} end)()
t.guides["forever/class/warrior/fire-hardened-armor"] = (function() return {
		["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "На 20-м уровне {npc:5113}, учитель воинов ({zone:1455}), отправляет вас к NPC {quest:1698} в Красногорье.",
		["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "На 20-м уровне {npc:7315}, учитель воинов ({zone:1457}), отправляет вас к NPC {quest:1698} в Красногорье.",
		["Charred and Galvanized Horns"] = "Обугленные и гальванизированные рога",
		["Enter the {area:98} and come back"] = "Войдите сюда и вернитесь: {area:98}",
		["Fire Hardened Armor"] = "Закаленный огнем доспех",
		["Roogug in {area:1717}"] = "Ругуг — {area:1717}",
		["Scorched Spider Fangs"] = "Опаленные паучьи клыки",
		["Starts now at 20 with a shield; a hauberk at 28, then a coif, leggings and gauntlets from three smiths."] = "Начинается с 20 уровня со щита; на 28 уровне – кольчуга, затем капюшон, поножи и рукавицы у трех кузнецов.",
		["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five. The Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "Воргены из стаи Ночной Погибели в зоне {zone:1431} (вестники Тьмы, Ярые Клыки, тенеткачи, воргены и нечистые воргены, 26-31 уровень) к югу и западу от места {area:42} роняют {quest:1705} в четырех случаях из пяти. Нечистые воргены отравляют и воют; Ярые Клыки вызывают {spell:3427}.",
		["The chimaeras live south-west of {area:460} in the {area:465}; the guide waits for level 26 first. You need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "Химеры живут к юго-западу от места {area:460}, здесь: {area:465}; сначала гайд ждет 26-го уровня. Нужно 12 обугленных рогов с химер-слетков (25-27 уровень) и молодых химер (23-25) – падают в четырех случаях из пяти, – и {item:6840} с NPC {npc:6167} (28, самая большая), тоже в четырех случаях из пяти. Там живут всего три слетка, две молодые химеры и одна матриарх, каждая возрождается через 5 минут, так что придется подождать. Слетки и матриарх плюются ядом ({spell:3396}), молодые применяют {spell:403}. Альянс: летите сюда: {area:467}, и идите на юг.",
		["{item:6841}, from Roogug"] = "{item:6841} — с Ругуга",
		["{npc:6170} (level 32, not elite) carries the {item:6845}, four kills in five; the guide waits for level 30 first. He walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. He poisons and howls."] = "{npc:6170} (32-й уровень, не элитный) носит {item:6845}, падает в четырех случаях из пяти; сначала гайд ждет 30-го уровня. Он ходит между глубиной и входом шахты ({area:2161}) к юго-востоку от места {area:42}, так что ждите у входа и выманите его наружу. Он отравляет и воет.",
} end)()
