t.guides["forever/class/warrior/whirlwind-weapon"] = (function() return {
		["At 30, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "На 30-м уровне {npc:3041}, учитель воинов ({zone:1456}), отправляет вас к NPC {npc:6236} ({area:720}, {zone:1413}).",
		["At 30, {npc:3354} in the {object:172958} sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "На 30-м уровне {npc:3354} ({object:172958}) отправляет вас к NPC {npc:6236} ({area:720}, {zone:1413}).",
		["At 30, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "На 30-м уровне {npc:4595}, учитель воинов ({zone:1458}), отправляет вас к NPC {npc:6236} ({area:720}, {zone:1413}).",
		["At 30, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "На 30-м уровне {npc:5113}, учитель воинов ({zone:1455}), отправляет вас к NPC {npc:6236} ({area:720}, {zone:1413}).",
		["Click {object:89931} with the 24 charms in your bags and {quest:1712} in your log. Its window asks for the charms straight away, with nothing to accept: Continue, then Complete, and it hands you the {quest:1714}."] = "Щелкните по объекту {object:89931}, когда в сумках 24 оберега, а в журнале – {quest:1712}. Его окно сразу просит обереги, без принятия задания: «Продолжить», затем «Завершить», и оно выдаст {quest:1714}.",
		["The cauldron wants 8 of each charm, 24 in all, and each exile drops its charm about one kill in three, so plan on some 70 kills. All are level 38-39, not elite: the guide waits for level 37 first, and a friend helps. Burning Exiles (fire) by the {area:334} in the north-west, north-west of {area:320}; Thundering Exiles (air) by the {area:336} south-east of {area:320}, casting {spell:403} from 40 yards; Cresting Exiles (water) by the {area:333}, north-west of {area:321}, with {spell:122}. About a dozen of each, back in under 7 minutes. The charms trade and sell on the auction house; using one banishes another kind of exile for a while (Burning on Thundering, Thundering on Cresting, Cresting on Burning)."] = "Котлу нужно по 8 оберегов каждого вида, всего 24, и каждый изгой роняет свой оберег примерно в одном случае из трех, так что рассчитывайте примерно на 70 убийств. Все они 38-39 уровня, не элитные: сначала гайд ждет 37-го уровня, и друг пригодится. Пылающие изгои (огонь) – у места {area:334} на северо-западе, к северо-западу от места {area:320}; грохочущие изгнанники (воздух) – у места {area:336} к юго-востоку от места {area:320}, бьют {spell:403} с 40 м; морские изгои (вода) – у места {area:333}, к северо-западу от места {area:321}, применяют {spell:122}. Каждых около дюжины, возрождаются меньше чем за 7 минут. Обереги можно передавать и продавать на аукционе; применение оберега на время изгоняет изгоя другого вида (пылающий – грохочущего, грохочущий – морского, морской – пылающего).",
		["The exiles of Arathi"] = "Изгнанники Нагорья Арати",
		["{npc:6176} camps by ruins on the east bank of the river that runs past {area:272}, a short walk north-east of the town, just over the border in {zone:1416}; his cauldron stands beside him. Horde: fly to {area:272}. Alliance: fly to {area:271} and go north along the river; {area:272}'s guards are level 42 elites, so keep away from the town. Accepting {quest:1712} gives you {item:6929}, the list of what he needs: 8 {item:3357}, 30 Bloodscalp Tusks and the {item:6851} from his cauldron. The cauldron's {item:6851} is not a quest you take: it never shows in your quest log. Come back with its charms and hand them in at the cauldron."] = "{npc:6176} стоит лагерем у руин на восточном берегу реки, что течет мимо поселения {area:272}, недалеко к северо-востоку от него, сразу за границей зоны {zone:1416}; рядом с ним стоит его котел. Орда: летите сюда: {area:272}. Альянс: летите сюда: {area:271}, и идите на север вдоль реки; стражники ({area:272}) – элитные противники 42-го уровня, так что держитесь подальше от поселения. Взяв задание {quest:1712}, вы получите {item:6929} – список того, что ему нужно: 8 шт. {item:3357}, 30 клыков троллей из клана Кровавый Скальп и {item:6851} из его котла. {item:6851} из котла – не задание, которое берут: оно никогда не появляется в журнале заданий. Возвращайтесь с оберегами и сдайте их у котла.",
		["{spell:2458} at 30 and a {spell:1680} axe, sword or warhammer at 40."] = "{spell:2458} на 30-м уровне и топор, меч или боевой молот ({spell:1680}) на 40-м.",
} end)()
