		["Flight path here: {area:3425} ({npc:15178})."] = "Маршрут полета здесь: {area:3425} ({npc:15178}).",
		["Flight path here: {area:541} (Gryfe)."] = "Маршрут полета здесь: {area:541} (Грайф).",
		["Flight path here: {area:976} ({npc:7823})."] = "Маршрут полета здесь: {area:976} ({npc:7823}).",
		["Flight path here: {area:976} ({npc:7824})."] = "Маршрут полета здесь: {area:976} ({npc:7824}).",
		["Flight path here: {zone:1450} (Faustron)."] = "Маршрут полета здесь: {zone:1450} (Фаустрон).",
		["Flight path here: {zone:1450} (Sindrayl)."] = "Маршрут полета здесь: {zone:1450} (Синдрайл).",
		["Fly to {area:1237} if you have it, otherwise to {area:431}, and walk east out of {zone:1440} into {zone:1447}."] = "Летите сюда: {area:1237}, если маршрут есть, иначе сюда: {area:431} – и идите на восток ({zone:1440} → {zone:1447}).",
		["Fly to {area:3137} if you have it, otherwise to {area:415}, and walk east out of {zone:1440} into {zone:1447}."] = "Летите сюда: {area:3137}, если маршрут есть, иначе сюда: {area:415} – и идите на восток ({zone:1440} → {zone:1447}).",
		["From western {zone:1446} take the path down into {zone:1449}. {area:541} in the north is a neutral camp."] = "С запада зоны {zone:1446} спуститесь по тропе: {zone:1449}. {area:541} на севере – нейтральный лагерь.",
		["Horde town: Alliance characters only need to touch its edge (guards)"] = "Город Орды: персонажам Альянса достаточно коснуться его края (стража)",
		["Starts in {zone:1446}, south of {zone:1445}. The last area of this guide completes the {zone:1414} map. 20 areas to discover here, levels 40-50."] = "Начинается здесь: {zone:1446}, к югу от зоны {zone:1445}. Последняя местность этого гайда завершает карту ({zone:1414}). Здесь нужно открыть 20 местностей, 40-50 уровни.",
		["Take the {area:1769} tunnel in northern {zone:1448} through to {zone:1450} (druids: {spell:18960}). {area:2361} is neutral."] = "Пройдите через туннель ({area:1769}) на севере зоны {zone:1448} в зону {zone:1450} (друиды: {spell:18960}). {area:2361} – нейтральная.",
		["The other exit of the {area:1769} tunnel leads into {zone:1452}. {area:2255} is a neutral goblin town with flight masters for both factions."] = "Другой выход из туннеля ({area:1769}) ведет в зону {zone:1452}. {area:2255} – нейтральный город гоблинов с распорядителями полетов для обеих фракций.",
		["any one of these names counts"] = "засчитывается любое из этих названий",
		["{zone:1446} is south of {zone:1445} and {zone:1441}. {area:976} is a neutral goblin town."] = "{zone:1446} – к югу от зон {zone:1445} и {zone:1441}. {area:976} – нейтральный город гоблинов.",
		["{zone:1448} is north of {zone:1440}."] = "{zone:1448} – к северу от зоны {zone:1440}.",
		["{zone:2482} is reached from {zone:1452} through {area:2256} in the south. It is Forever's endgame leveling zone."] = "В зону {zone:2482} можно попасть из зоны {zone:1452} через место {area:2256} на юге. Это зона прокачки Forever для конца игры.",
} end)()
t.guides["forever/exploration/zephras-isle"] = (function() return {
		["Exploration: {zone:2521}"] = "Исследование: {zone:2521}",
		["Skyborne start here. Everyone else takes a skyboat, about every five minutes; either faction may take either one."] = "Небеснорожденные начинают здесь. Остальные летят на небесном корабле, он отправляется примерно каждые пять минут; любая фракция может сесть на любой из двух.",
		["The skyboat leaves the cliffs south of {area:17045}, north of {zone:1456} (another flies from {area:279})."] = "Небесный корабль отправляется с утесов к югу от места {area:17045}, к северу от города {zone:1456}; другой летит от места {area:279}.",
		["The skyboat leaves the north side of {area:279} in the {zone:1416} (another flies from north of {zone:1456})."] = "Небесный корабль отправляется с северной стороны места {area:279} ({zone:1416}); другой летит с севера от города {zone:1456}.",
		["any one of these names counts"] = "засчитывается любое из этих названий",
} end)()
t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "Помогите NPC {npc:261366}: держитесь рядом, когда на гребень поднимутся {npc:261367} и солдаты ({area:21})",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites in the camp's north-east, near {npc:3438}: pull {npc:3438} and the quilboar away from them one at a time."] = "Назад в лагерь Иглогривых. Геоманты и защитники держат его восточную половину; среди них ходит {npc:3438}.\nОсторожно: трупоедки и берсерки из племени Иглогривых (18-19) – элитные противники в северо-восточной части лагеря, рядом с NPC {npc:3438}: выманивайте {npc:3438} и свинобразов подальше от них по одному.",
		["Bristleback camps"] = "Лагеря Дыбогривых",
		["Burning Blade Cultists hold {area:1898} in northern {zone:1411}; they drop the {item:6652}. The {item:5026} comes from the Razormane on your next visit to their camp."] = "Сектанты из клана Пылающего Клинка ({npc:3199}) удерживают {area:1898} на севере зоны {zone:1411}; с них падает {item:6652}. {item:5026} добудете у Иглогривых в следующий заход в их лагерь.",
		["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Примените {spell:18960}. {npc:11802} стоит наверху в своем доме, здесь: {area:2361}. Поднимитесь внутри: стрелка не различает этажи.",
		["Dogran is chained up in the quilboar camp west of the road."] = "Догран закован в цепи в лагере свинобразов к западу от дороги.",
		["Down the {area:458} to {area:378} again."] = "Снова на юг по дороге ({area:458}). Цель: {area:378}.",
		["Fill the {item:7766} at the quilboar watering hole"] = "Наполните {item:7766} у водопоя свинобразов",
		["Finish the Plainstrider Beaks"] = "Доберите клювы долгоногов",
		["Finish the Raptor Heads"] = "Доберите головы ящеров",
		["Fly from the Crossroads to {area:1638}. {quest:853} waits in the {area:2197}, the cave under {area:1640}: hand in the spores there first, while their time runs. Then {npc:3033} trains you on {area:1639}."] = "Летите с Перекрестка сюда: {area:1638}. {quest:853} ждет в пещере под возвышенностью {area:1640} ({area:2197}): сначала сдайте там споры, пока не вышло время. Затем {npc:3033} обучит вас здесь: {area:1639}.",
		["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "Летите сюда: {area:1638} – на обучение: {npc:3033} – здесь: {area:1639}.",
		["Follow the road east to the outpost above the {area:814}."] = "Идите по дороге на восток к заставе над рекой ({area:814}).",
		["Follow the road south-east to {area:392} on the coast."] = "Идите по дороге на юго-восток: {area:392} на побережье.",
		["Follow the {area:458} south to {area:378}."] = "Идите по дороге ({area:458}) на юг. Цель: {area:378}.",
		["Grimtotem camp"] = "Лагерь Зловещего Тотема",
		["He gives you the {item:15826}"] = "Он даст вам {item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "Затем он предложит {quest:1838} (1838, 30-й уровень): для него нужно место {area:1717}, и оно отправит вас по всему Калимдору и Восточным королевствам. Его описывает классовый гайд воина «{quest:1838}».",
		["In from the north gate: {npc:3464} first, {npc:3338} by the inn, then up to {npc:3449} and {npc:3429} on the tower platform, where the flight master stands."] = "Войдите через северные ворота: сначала {npc:3464}, {npc:3338} у таверны, затем поднимитесь к NPC {npc:3449} и {npc:3429} на площадку башни, где стоит распорядитель полетов.",
		["In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end.\nPlainstriders here count toward the beaks.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "В лагере водоискатели и терноплеты держат западную половину, охотники – середину; ящики с припасами стоят на восточном краю.\nДолгоноги здесь тоже дают клювы.\nОсторожно: трупоедки и берсерки из племени Иглогривых (18-19) – элитные противники; они стоят в северо-восточной части лагеря, у ящиков с припасами: выманивайте свинобразов подальше от них по одному.",
		["Inside"] = "Внутри",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "Сохраните: {npc:12696} ({zone:1440}), следующий гайд",
		["Kolkar camp"] = "Лагерь Колкар",
		["Lost Barrens Kodos roam the plains around the Kolkar camp north-west of {npc:3389}; herbalists pick {item:2449} there too."] = "Потерявшиеся степные кодо бродят по равнинам вокруг лагеря Колкар к северо-западу от {npc:3389}; травники там же собирают {item:2449}.",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "На север. Цель: {area:383}. {npc:3682} стоит лагерем под холмами; у отшельника на гребне за ним ({npc:261366}) найдется работа, только когда {npc:3682} отправит вас наверх.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate."] = "На север по дороге ({area:458}) к Перекрестку: {npc:3448} – у южных ворот, {npc:3432} – у таверны, {npc:3428} – к западу от северных ворот.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate. Keep the {item:5075}: {npc:3430} takes it on the next stop in {area:378}."] = "На север по дороге ({area:458}) к Перекрестку: {npc:3448} – у южных ворот, {npc:3432} – у таверны, {npc:3428} – к западу от северных ворот. Сохраните {item:5075}: {npc:3430} примет его при следующем заходе сюда: {area:378}.",
		["North-west to the {area:383}: the Witchwing Slayers hold their western end; they wear the rings.\nCareful: Some stealthed harpy ambushers wait in the area and stay hidden until you get close. A level 19 elite harpy also patrols there."] = "На северо-запад: {area:383}; душегубки из стаи Зачарованного Крыла держат западный край; кольца – у них.\nОсторожно: в округе прячутся невидимые гарпии-засадницы, они не видны, пока вы не подойдете близко. Там же патрулирует гарпия-элита 19 уровня.",
		["On the way back down the {area:1076}, {npc:11856} is held in {npc:11858}'s hut at the bend in the road. Once you take her quest she walks straight off south-east to {area:2538}, the burned village, without waiting: stay close, or the quest fails.\nCareful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly."] = "На обратном пути вниз по тропе ({area:1076}) {npc:11856} удерживают в хижине NPC {npc:11858} у поворота дороги. Как только вы возьмете ее задание, она сразу пойдет на юго-восток к месту {area:2538}, в сожженную деревню, не дожидаясь вас: держитесь рядом, иначе задание будет провалено.\nОсторожно: в сожженной деревне на нее нападут трое из племени Зловещего Тотема, и атаковать они будут ее, а не вас: отвлеките их на себя и побыстрее убейте заклинателя.",
		["Over the {area:814} bridge below {area:379} and south along the {zone:1411} bank to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "По мосту ({area:814}) под местом {area:379} и на юг вдоль берега ({zone:1411}) до узкой тропы, ведущей в гору: {npc:5900} хранит святилище на вершине. Осторожнее с обрывами по пути наверх и спускайтесь по той же тропе.",
		["Plainstrider Beaks as you go"] = "Клювы долгоногов по пути",
		["Plainstriders roam the plains all over the {zone:1413}, and about one in four drops a beak: kill the ones you pass on the way."] = "Долгоноги бродят по всей зоне {zone:1413}, примерно с каждого четвертого падает клюв: убивайте встречных по пути.",
		["Raptor Heads as you go"] = "Головы ящеров по пути",
		["Raptor nests"] = "Гнезда ящеров",
		["Razormane camp"] = "Лагерь Иглогривых",
		["Razormane camp: {npc:3429}'s quilboar"] = "Лагерь Иглогривых: кабанолюды для NPC {npc:3429}",
		["South-west from {area:392} across the plains to the {area:1697}: the three nests sit together south-west of the oasis, and Sunscale Scytheclaws guard them. Each nest needs a {item:5165}: kill Sunscale raptors (most drop one) until you have three, then use a feather at each nest."] = "На юго-запад от места {area:392} через равнины. Цель: {area:1697}. Три гнезда находятся рядом к юго-западу от оазиса, их охраняют яркочешуйчатые смертехваты. Для каждого гнезда нужен предмет {item:5165}: убивайте яркочешуйчатых ящеров (с большинства он падает), пока не наберете три, затем используйте перо у каждого гнезда.",
		["Sunscale raptors here count toward the heads."] = "Яркочешуйчатые ящеры здесь тоже дают головы.",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "Таурены: {npc:11957} ждет на южном холме над мостом. Небеснорожденные: {npc:272054} стоит к югу от двух мостов. Затем – логова к востоку от озера: выйдите из облика, щелкните по статуе у входа, чтобы получить пять минут незаметности, держитесь подальше от духов внутри и возьмите по одной реликвии каждого вида; {item:280680} лежит у подножия статуи белой кошки.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "{item:5097} падает с надзирателей и головорезов Торговой компании у рудника в северо-восточном углу зоны.",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers. {npc:3394} stands in the Kolkar camp west of the pools."] = "Пруды – сразу к северу от NPC {npc:3389}. Зайдите в воду, чтобы исследовать их; спелые грибы для Хелбрима растут вокруг. Убивайте всех встречных Колкар ради наручей. {npc:3394} стоит в лагере Колкар к западу от прудов.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "Дорога поднимается на север – {area:1076}. Хижина: {quest:1483} – там, где дорога сворачивает на восток к месту {area:461}.",
		["The {area:2363}"] = "{area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960} – ущелье под местом {object:172982}.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792} лежит у северного края места {area:382}, у башни Торговой компании. В нем – {item:15883} для задания {quest:30}.",
		["Thunder Lizards and Lightning Hides graze just across the bridge below {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Рокочущие ящерицы ({npc:3130}) и бурешкуры ({npc:3131}) пасутся сразу за мостом ниже заставы {area:379}.\nОсторожно: Халикор, элитный противник 12-го уровня, бродит среди ящериц ({area:369}): высматривайте его, прежде чем нападать.",
		["Thunder lizards across the river"] = "Рокочущие ящерицы за рекой",
		["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "Над теми же равнинами к югу от лагеря кружат грозовые змеи-облачники.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "Громоголовы пасутся на равнинах чуть южнее места {area:378}. Среди них бродит синий громоящер {quest:884}: его хвостовой шип начинает задание.",
		["Twitching Antennae"] = "Дергающиеся усики",
		["Twitching Antennae from the silithid"] = "Дергающиеся усики с силитидов",
		["Upstairs"] = "Наверху",
		["West from the burned village to {area:2539}: {npc:12816} stands just outside it, before the village."] = "На запад от сожженной деревни к месту {area:2539}: {npc:12816} стоит прямо перед деревней.",
		["West to the {area:383}. The Witchwing harpies nest all over them; any of them can drop a talon. {quest:819} lies in their hills. Savannah Prowlers hunt the plains between {npc:3389} and the hills: take their claws on the way.\nCareful: There are 2 Witchwing Ambushers (level 17-18). They stay stealthed with Sneak while out of combat."] = "На запад: {area:383}. Гарпии из стаи Зачарованного Крыла гнездятся повсюду; коготь может упасть с любой. {quest:819} лежит в этих холмах. Хищники саванны охотятся на равнинах между NPC {npc:3389} и холмами: соберите их когти по пути.\nОсторожно: здесь 2 засадницы из стаи Зачарованного Крыла (уровень 17-18). Вне боя они скрыты незаметностью.",
		["While you are in the camp: {npc:3429}'s Water Seekers and Thornweavers in its western half, the Hunters in the middle, the supply crates at its eastern end.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "Пока вы в лагере: водоискатели и терноплеты для NPC {npc:3429} – в западной половине, охотники – в середине, ящики с припасами – на восточном краю.\nОсторожно: трупоедки и берсерки из племени Иглогривых (18-19) – элитные противники; они стоят в северо-восточной части лагеря, у ящиков с припасами: выманивайте свинобразов подальше от них по одному.",
		["You arrive from {area:379}. {npc:3489} and {npc:3338} stand by the inn, Helbrim and {npc:3464} by the north gate; {npc:3615}, {npc:3429} and {npc:3449} on the tower platform."] = "Вы приходите с заставы {area:379}. {npc:3489} и {npc:3338} стоят у таверны, Хелбрим и {npc:3464} – у северных ворот; {npc:3615}, {npc:3429} и {npc:3449} – на площадке башни.",
		["Zhevra Runners graze along the road east toward {area:392}: take their hooves on the way out."] = "Жевры-бегуны пасутся вдоль дороги на восток к месту {area:392}: соберите копыта по пути.",
		["{area:1898} cultists"] = "Сектанты: {area:1898}",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}: из объекта {object:177785} в озере",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{item:2449}: продает {npc:3490}; травники собирают на равнинах",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} ({area:2361}) отправляет туда друидов по воздуху",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}, {area:2362}",
		["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "{npc:11802} стоит на верхнем этаже своего здания ({area:2361}): поднимитесь внутри, стрелка не различает этажи.",
		["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}. {quest:28} runs on a timer: no teleport or Hearthstone until {npc:11799} has it."] = "{npc:11802} стоит наверху в своем здании – {area:2361}: поднимитесь внутри, стрелка не различает этажи. Безделушки из святилища лежат на дне: {area:656} – и исчезают за несколько минут: плывите с одной прямо к месту {area:2362} на северо-западном берегу, используйте ее там и поговорите с NPC {npc:11799}. У задания {quest:28} есть таймер: никаких телепортов и Камня возвращения, пока его не примет {npc:11799}.",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}: приветствие от {npc:3033}",
		["{npc:11856}, inside {npc:11858}'s hut"] = "{npc:11856}, в хижине NPC {npc:11858}",
		["{npc:11857}: keep it, {npc:11864} at {area:460} in the {zone:1413} & Stonetalon guide"] = "{npc:11857}: сохраните, {npc:11864} ({area:460}) – в гайде «{zone:1413} и Когтистые горы»",
		["{npc:16227}, beside {npc:3442}"] = "{npc:16227} – рядом с NPC {npc:3442}",
		["{npc:3338} by the inn first, then the innkeeper, Helbrim by the north gate, {npc:3429} and {npc:3449} on the tower platform, {npc:3432} by the inn, and {npc:3448} at the south gate last. His seed test waits for the {npc:3395} pass at the {area:388}: go straight on north-west to the {area:383}. After the spores Helbrim offers {quest:853}, a delivery to {zone:1456} within 45 minutes: this route doesn't go there, so leave it (Druids take it on the next Crossroads stop, right before their flight to {zone:1456})."] = "Сначала {npc:3338} у таверны, затем хозяин таверны, Хелбрим у северных ворот, {npc:3429} и {npc:3449} на площадке башни, {npc:3432} у таверны и последним – {npc:3448} у южных ворот. Его проверка семян подождет до похода к NPC {npc:3395} ({area:388}): идите прямо на северо-запад сюда: {area:383}. После спор Хелбрим предлагает задание {quest:853} – доставку в {zone:1456} за 45 минут: этот маршрут туда не идет, так что не берите его (друиды берут его при следующем заходе на Перекресток, прямо перед полетом в {zone:1456}).",
		["{npc:3390}: 45 minutes, for Zamah on the {zone:1456} step next"] = "{npc:3390}: 45 минут, для Замы на следующем шаге ({zone:1456})",
		["{npc:3391}, upstairs"] = "{npc:3391}, на втором этаже",
		["{npc:3395} walks among the Kolkar at the {area:388} south-east of the Crossroads. Test {npc:3448}'s seeds at the bubbling fissure on the oasis' east bank while you are there."] = "{npc:3395} ходит среди Колкар у места {area:388} к юго-востоку от Перекрестка. Раз уж вы там, проверьте семена NPC {npc:3448} у бурлящей расщелины на восточном берегу оазиса.",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. He walks that shore, from about 46,36 in the north to 46,42 in the south: if he isn't at the arrow, follow the shore until you meet him. Hand his head to {npc:3389} on your last Crossroads stop. Oasis Snapjaws crawl in the oasis' water there: their shells are for {npc:3448}."] = "{npc:3396} ведет Колкар на западном берегу ({area:387}), к югу от NPC {npc:3389}. Он ходит вдоль этого берега, примерно от 46,36 на севере до 46,42 на юге: если его нет там, куда указывает стрелка, идите вдоль берега, пока не встретите его. Отдайте его голову NPC {npc:3389} при последнем заходе на Перекресток. Там в воде оазиса ползают оазисные хрустогрызы: их панцири нужны NPC {npc:3448}.",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, на вершине башни",
		["{npc:3430}, in the cage"] = "{npc:3430}, в клетке",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{npc:3432} предложит {quest:95774}, когда будет сдано задание {quest:4921}",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}: пульт управления – {area:382}, позже",
		["{npc:3446}, beside the {object:3972} poster"] = "{npc:3446}, рядом с плакатом ({object:3972})",
		["{npc:3448}: the Oasis Snapjaws at {area:387}, with {npc:3396} after the {zone:1454} trip"] = "{npc:3448}: оазисные хрустогрызы – {area:387}, вместе с NPC {npc:3396} после поездки в {zone:1454}",
		["{npc:3448}: the bubbling fissure at the {area:388}, on the {npc:3395} pass"] = "{npc:3448}: бурлящая расщелина ({area:388}), по пути к NPC {npc:3395}",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}: гарпии будут позже – {area:383}",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465} закован в цепи внутри крепости. Поговорите с ним, чтобы начать сопровождение, и держитесь рядом: на выходе нападут солдаты Терамора. Он доведет вас обратно. Цель: {area:392}.",
		["{npc:3615}, on the tower"] = "{npc:3615}, на башне",
		["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197} живет здесь: {area:2539} – деревня троллей сразу на входе в Когтистые горы, в конце дороги на запад от {npc:3389}.",
		["{npc:4201}: for {npc:3442}, beside {area:392}'s flight master at the end of the {zone:1413} & Stonetalon guide"] = "{npc:4201}: для NPC {npc:3442}, рядом с распорядителем полетов ({area:392}), в конце гайда «{zone:1413} и Когтистые горы»",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878} стоит лагерем у дороги на восток к месту {area:392}.",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900} делает из смолы и мешочка предмет {item:6636}. Используйте его у жаровни рядом с ним, чтобы появился {npc:5893}; убейте его ради предмета {item:6655}, затем положите уголек в жаровню.",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901} ждет на холме к югу (ориентир: {area:392}), по пути на север.",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907} стоит на гребне к северу от лагеря Иглогривых.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, ваш {item:5176} и {item:263412}",
		["{npc:5909}, a few steps away"] = "{npc:5909}, в нескольких шагах",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018} – {object:172961}, на западе города.",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018} стоит здесь: {object:172961}, в западной части города.",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}: {npc:4606} ({zone:1458}), через два гайда",
		["{object:3972} poster"] = "Плакат: {object:3972}",
		["{quest:1492}, on the dock"] = "{quest:1492}, на причале",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}: {area:384}, следующий гайд",
		["{quest:853}, in the {area:2197}"] = "{quest:853} ({area:2197})",
		["{zone:1454} class quests"] = "Классовые задания: {zone:1454}",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["Back north-west up the road to the {area:228}."] = "Обратно на северо-запад по дороге: {area:228}.",
		["Class trainer"] = "Учитель классовых навыков",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "Идите по дороге на северо-восток к дому Йориков: {area:238}.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood."] = "Идите по дороге на юг. {object:1627} стоит у дороги, к северу от Деревни Погребальных Костров.",
		["Inside"] = "Внутри",
		["Mottled Worgs"] = "Крапчатые ворги",
		["Mottled Worgs prowl the hills around the house."] = "Крапчатые ворги рыщут по холмам вокруг дома.",
		["North again to the Yoricks' house."] = "Снова на север к дому Йориков.",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field."] = "К северу от места {area:228}. {npc:1983} бродит по {area:240}: убейте ее, затем пройдите через поле.",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "Поговорите с NPC {npc:10181} ({object:36126}): {quest:93739}",
		["Speak with {npc:10540}, in Grommash Hold"] = "Поговорите с NPC {npc:10540} в Крепости Громмаш",
		["Speak with {npc:3230}, in Grommash Hold"] = "Поговорите с NPC {npc:3230} в Крепости Громмаш",
		["Take the road north toward {zone:1420}: the Yoricks' house at {area:238} is on the way. {quest:425} lurks a short walk west of it."] = "Идите по дороге на север ({zone:1420}): дом Йориков ({area:238}) по пути. {quest:425} прячется недалеко к западу от него.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Рогоз и копейник растут вдоль воды – {object:172958}, к востоку от Волока.",
		["The {object:172960} is the canyon under the {object:172982}; {quest:829} stands at its far end."] = "{object:172960} – ущелье под местом {object:172982}; {quest:829} стоит в дальнем конце.",
		["Vile Fin murlocs"] = "Мурлоки из племени Злобного Плавника",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228} – городок Отрекшихся у склепа посреди леса. Все нужные NPC стоят у входа в склеп; {npc:2226}, укротитель летучих мышей, – чуть к востоку.",
		["{npc:11044}, in the Apothecarium"] = "{npc:11044}, в Районе Фармацевтов",
		["{npc:11046}, the alchemy trainer, stands next door to {npc:3348}."] = "{npc:11046}, учитель алхимии, стоит по соседству с NPC {npc:3348}.",
		["{npc:11046}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11046}: «Основы походной жизни», от костра Бракка – {zone:1411}",
		["{npc:11066}, the enchanting trainer, works in the Drag."] = "{npc:11066}, учитель наложения чар, работает на Волоке.",
		["{npc:11066}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11066}: «Основы походной жизни», от костра Бракка – {zone:1411}",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937}: для Квинна, на дороге на север в конце",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978} ждет к северо-востоку от дома. Проводите его к NPC {npc:1950}; по пути нападают ворги.",
		["{npc:2226}: {npc:4556} in the {zone:1458}, at the end of this guide; no need to buy the flight"] = "{npc:2226}: {npc:4556} – {zone:1458}, в конце этого гайда; покупать полет не нужно",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} обучает паладинов – {area:159}, недалеко на север по дороге от башен дирижаблей. Возвращайтесь по той же дороге в Серебряный бор.",
		["{npc:2855}, the tailoring trainer, is in the {object:172958}."] = "{npc:2855}, учитель портняжного дела, находится здесь: {object:172958}.",
		["{npc:2855}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:2855}: «Основы походной жизни», от костра Бракка – {zone:1411}",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348} и {npc:3347} держат лавку алхимии на Волоке; {npc:11046} – по соседству.",
		["{npc:3365}, the leatherworking trainer, works in the {object:172958}."] = "{npc:3365}, учитель кожевничества, работает здесь: {object:172958}.",
		["{npc:3365}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3365}: «Основы походной жизни», от костра Бракка – {zone:1411}",
		["{npc:3404}, the herbalism trainer, keeps her shop in the Drag."] = "{npc:3404}, учитель травничества, держит лавку на Волоке.",
		["{npc:3404}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3404}: «Основы походной жизни», от костра Бракка – {zone:1411}",
		["{npc:4551}, the bat handler"] = "{npc:4551}, укротитель летучих мышей",
		["{npc:4551}: keep {item:16210}, Podrig takes it on the next stop at the {area:228}, at 22"] = "{npc:4551}: сохраните {item:16210}, Подриг заберет его на следующей остановке – {area:228}, на 22 уровне",
		["{npc:4556}, the weapon merchant beside the bat handler"] = "{npc:4556}, торговец оружием рядом с укротителем летучих мышей",
		["{npc:4586}, the engineering trainer, works in the {zone:1458}."] = "{npc:4586}, учитель инженерного дела, работает здесь: {zone:1458}.",
		["{npc:4586}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4586}: «Основы походной жизни», от костра NPC {npc:265812} в Тирисфальских лесах",
		["{npc:4598}, the mining trainer, works in the {zone:1458}."] = "{npc:4598}, учитель горного дела, работает здесь: {zone:1458}.",
		["{npc:4598}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4598}: «Основы походной жизни», от костра NPC {npc:265812} в Тирисфальских лесах",
		["{npc:4605}, the blacksmithing trainer, works in the {zone:1458}."] = "{npc:4605}, учитель кузнечного дела, работает здесь: {zone:1458}.",
		["{npc:4605}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4605}: «Основы походной жизни», от костра NPC {npc:265812} в Тирисфальских лесах",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, внутри Крепости Громмаш",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}: {quest:93739}, обход вождей Орды",
		["{npc:7088}, the skinning trainer, stands in the {object:172958}."] = "{npc:7088}, учитель снятия шкур, стоит здесь: {object:172958}.",
		["{npc:7088}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:7088}: «Основы походной жизни», от костра Бракка – {zone:1411}",
		["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264} сдается не персонажу, а объекту {object:24776} – могиле в нескольких шагах к югу от входа в склеп.",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Bael'dun fortress"] = "Крепость Бейл'дана",
		["East along the road from {area:2539} to {npc:4049}'s camp, on the way to {area:378}."] = "На восток по дороге от места {area:2539} к лагерю ({npc:4049}), по пути к месту {area:378}.",
		["Fly to the Crossroads from the wind rider master: {npc:2995} on {zone:1456}'s central rise."] = "Летите на Перекрестки у распорядителя ветрокрылов: {npc:2995} на центральном возвышении ({zone:1456}).",
		["Fly to {area:1638}"] = "Лететь: {area:1638}",
		["Fly to {area:1638} first: two of its elders give quests worked on this guide's and the next guide's walks."] = "Сначала летите сюда: {area:1638} – двое старейшин выдают там задания, которые выполняются по ходу этого и следующего гайдов.",
		["Fly to {area:378}"] = "Лететь: {area:378}",
		["Fly to {area:392}"] = "Лететь: {area:392}",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Идите по дороге на север к месту {area:467}. По пути пасутся беговые олени-рогачи ({npc:4018}); сокотвари ({npc:4020}), сумеречные бегуны ({npc:4067}) и волшебные дракончики ({npc:4016}) бродят в лесу под пиком, а кенарийские друиды занимают рощу там.",
		["Follow the road west past Regthar's bunkers and {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "Идите по дороге на запад мимо бункеров Регтара и лагеря ({npc:4049}) в Когтистые горы: {npc:3995} ждет под землей здесь: {area:2539}, у подножия тропы ({area:1076}).",
		["Follow the road west past Regthar's bunkers: {npc:4049} camps beside it at the edge of Stonetalon."] = "Идите по дороге на запад мимо бункеров Регтара: {npc:4049} стоит лагерем у дороги на краю Когтистых гор.",
		["From {area:2539} follow the road east to {npc:4049}'s camp, then south-east across the plains to {area:378}."] = "От места {area:2539} идите по дороге на восток к лагерю ({npc:4049}), затем на юго-восток через равнины к месту {area:378}.",
		["From {area:378} follow the road west through the gate into {zone:1412}, then north past {area:222} to {zone:1456}; a lift at the foot of the bluffs takes you up."] = "От места {area:378} идите по дороге на запад через ворота в зону {zone:1412}, затем на север мимо места {area:222} к городу {zone:1456}; подъемник у подножия утесов поднимет вас наверх.",
		["Gaea Dirt Mounds"] = "Земляные курганы Геи ({object:177929})",
		["Gaea Seeds"] = "Семена Геи ({item:16205})",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "К юго-западу от Солнечного Камня лежит выжженная {area:465}. Посадите семена Геи в земляные курганы на дне долины; с огненных элементалей падают {item:16312}. Гарпии и душительницы из стаи Кровавой Ярости гнездятся на севере, душегубки и бродяжницы – на юге.",
		["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "Летательная машина дворфов стоит на площадке внутри раскопок. Используйте на ней {item:5021}, полученную от NPC {npc:3341}.",
		["The flying machine"] = "Летательная машина",
		["The road west past {npc:4049}'s camp"] = "Дорога на запад мимо лагеря ({npc:4049})",
		["The {area:1718}"] = "{area:1718}",
		["The {object:667362} grows on the bottom of {area:464}, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath."] = "{object:667362} растет на дне озера ({area:464}), у того же южного берега: ныряйте к растениям и кучам сушеной мутной травы – и то и другое дает стручки. Следите за дыханием.",
		["To {zone:1456}"] = "Цель: {zone:1456}",
		["Up the {area:1076} past {npc:4201} and west to {area:460}; coming from {npc:4073}, back west past Ziz's hut."] = "Вверх по тропе ({area:1076}) мимо NPC {npc:4201} и на запад к месту {area:460}; если идете от NPC {npc:4073} – обратно на запад мимо хижины Зиза.",
		["Up the {area:1076} to {npc:4201}' hut, then east along the road toward {area:461}: {npc:4074} patrols the road just east of the fork, {npc:4073} the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them."] = "Вверх по тропе ({area:1076}) к хижине ({npc:4201}), затем на восток по дороге к месту {area:461}: {npc:4074} патрулирует дорогу чуть восточнее развилки, {npc:4073} – склоны дальше к северо-востоку под утесом. Оба – одиночные роботы-крошшеры; они бродят, так что идите по дороге, пока не встретите их.",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}, с любой гарпии из стаи Кровавой Ярости",
		["{npc:10079} stands at the top of the {area:1718}, beside {npc:12576}."] = "{npc:10079} стоит наверху ({area:1718}), рядом с NPC {npc:12576}.",
		["{npc:10079}, at the top of the lift"] = "{npc:10079}, наверху у подъемника",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}: сверкающие солнечные камни ({item:277936}) с гарпий из стаи Кровавой Ярости",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, рядом с NPC {npc:11862}",
		["{npc:11862}, up on the ledge"] = "{npc:11862}, наверху на уступе",
		["{npc:11864} stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her."] = "{npc:11864} стоит у костра в Солнечном Камне: весть Макабы о том, что Кайя жива, предназначена ей.",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, на дереве чуть восточнее {npc:3341}",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "{npc:2995}, распорядитель ветрокрылов, стоит на центральном возвышении: получите у него маршрут полета, если его у вас нет. {npc:3024} и {npc:4721} стоят недалеко к востоку от него.",
		["{npc:3024}: the {object:667362} grows in {area:464}, by Sun Rock"] = "{npc:3024}: {object:667362} растет здесь: {area:464}, у Солнечного Камня",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, на вершине башни",
		["{npc:3430}, in the cage"] = "{npc:3430}, в клетке",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, у северного края лагеря",
		["{npc:3442} stands beside the flight master you land at."] = "{npc:3442} стоит рядом с распорядителем полетов, у которого вы приземлитесь.",
		["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442}: {quest:1094}, от NPC {npc:4201}",
		["{npc:4049}: {npc:4074} and {npc:4073} roam east of {npc:4201}, on the way up"] = "{npc:4049}: {npc:4074} и {npc:4073} бродят к востоку от NPC {npc:4201}, по пути наверх",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "Следующее задание {npc:4198}, «Гордан», – на стороне Альянса в зоне {zone:1440}. Пропустите его.",
		["{npc:4198}, outside the gate"] = "{npc:4198}, за воротами",
		["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721}: склянка – в зоне {zone:1440}, следующий гайд",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "Хижина ({npc:5899}) стоит на гребне над водопоем свинобразов, к югу от места {area:378}, по пути в {area:359}.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}: синий бурдюк наполняется в зоне {zone:1440}, следующий гайд",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}: красный бурдюк из места {area:272}",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}, большой трешадон, плавает на мелководье у места {area:391}, к востоку от {npc:3388}.",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
		["{zone:1456} first: two of its elders give quests worked on this guide's and the next guide's walks. Fly to {area:378}; from there it is a walk west into {zone:1412} and north to the bluffs."] = "Сначала {zone:1456}: двое старейшин выдают там задания, которые выполняются по ходу этого и следующего гайдов. Летите сюда: {area:378}; оттуда идите на запад в зону {zone:1412} и на север к утесам.",
		["{zone:1456}'s central rise"] = "{zone:1456}, центральное возвышение",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "Снова на юг по дороге. Там, где она сворачивает на восток в {area:287}, {npc:2214} ждет здесь: {area:285}.",
		["Below ground"] = "Под землей",
		["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177790}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "По дороге через Серебряный бор: {area:228}. От башен дирижаблей – на юг через Тирисфальские леса; от предмета {object:177790} – на юго-восток от побережья к дороге. {npc:2121} и {npc:1937} стоят у входа в склеп.",
		["Druid trainer"] = "Учитель друидов",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Все наги из клана Зловещего Хвоста вдоль берега к северу от заставы роняют головы.",
		["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "От лагеря Сирета идите на северо-восток через зону {zone:1413} к дороге к северу от Перекрестка; разбойники, идущие от башни Физзула, идут к ней на запад. {npc:8582} стоит на сторожевой башне ({area:1703}), где дорога входит в зону {zone:1440}.",
		["Naga brazier"] = "Жаровня наг",
		["Naga heads"] = "Головы наг",
		["Out of the inn to the {area:431} flight master and fly to {area:1637}."] = "Из таверны идите к распорядителю полетов ({area:431}) и летите сюда: {area:1637}.",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Выведите NPC {npc:271181} {npc:267214} из оврага к главной дороге за четыре минуты; если поддержание прервется, попросите {npc:267214} снова.",
		["Thistlefur Hold"] = "Логово Колючего Меха",
		["{area:431} is just north up the road. Coming in from the south, the flight master and {npc:12696}'s hunt board at {area:428} come first, then the vendors. {npc:12867} at the lumber camp offers Ashenvale Outrunners: leave it for the next {zone:1440} visit, at 26."] = "{area:431} – чуть севернее по дороге. Если идти с юга, сначала будут распорядитель полетов и доска охоты NPC {npc:12696} ({area:428}), затем торговцы. {npc:12867} в лагере лесорубов предлагает «Вестницы Ясеневого леса»: оставьте это задание до следующего визита в зону {zone:1440}, на 26-м уровне.",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}, с NPC {npc:1973}",
		["{npc:12837}, inside the inn"] = "{npc:12837}, в таверне",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}: Дарталия – {area:272}",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{npc:2391} ({area:272}) обучает: Яды – сохраните задание",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} обучает паладинов – {area:159}, недалеко на север по дороге от башен дирижаблей. Возвращайтесь по той же дороге в Серебряный бор.",
		["{npc:271181}, on the road"] = "{npc:271181}, на дороге",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875} стоит здесь: {object:172960}. Используйте {item:6626} на круге призыва и победите суккуба, чтобы подчинить ее.",
		["{npc:6389} stands just west of the crypt entrance: hand him {item:16210} from the {zone:1458}."] = "{npc:6389} стоит чуть западнее входа в склеп: отдайте ему {item:16210} из города {zone:1458}.",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["Back down to Masoj on the hillside above {area:290}."] = "Спуститесь обратно к Масоджу на склон над местом {area:290}.",
		["Back to {area:272}"] = "Назад: {area:272}",
		["Bears, creepers and lions"] = "Медведи, ползуны и львы",
		["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings. Their locks need keys: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues and Watchmen hold the camps along the way."] = "Друлл и {npc:2238} прикованы в постройках внутреннего двора ({area:275}). Для их замков нужны ключи: {npc:2427} носит {item:3467}, а {npc:2428} — {item:3499}, оба в крепости. Убейте их, затем откройте оба замка.\nИз места {area:272} идите на юго-восток в холмы по пути к месту {area:275}. Лагеря на пути занимают разбойники и сторожа Синдиката.",
		["Drull's ball and chain"] = "Ядро и цепь Друлла",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "Наполните {item:7768} у колодца рядом с таверной: {object:107045}",
		["Inside"] = "Внутри",
		["Just south of Masoj, the {item:3502} grow on the hillsides above the river."] = "Сразу к югу от Масоджа на склонах над рекой растет {item:3502}.",
		["Keep it: the {area:287} coast, later on the route"] = "Сохраните его: побережье ({area:287}), позже по маршруту",
		["Masoj hides on the hillside above {area:290}, south-west of Durnholde, on the way down to the blossoms."] = "Масодж прячется на склоне над местом {area:290}, к юго-западу от Дарнхольда, по пути вниз к цветам.",
		["Masoj wants an Apothecary Vial placed on three peaks. The southern one is the hilltop above {area:290}, south-east of the blossoms: use a vial at the top."] = "Масоджу нужно, чтобы на трех вершинах поставили склянки аптекаря. Южная — холм над местом {area:290}, к юго-востоку от цветов: используйте склянку на вершине.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "Фермы к востоку от городка {area:287}. {npc:232} работает на поле у северного фермерского дома, {npc:2403} — на поле юго-восточнее; батраки и фермеры повсюду. {npc:2451} ухаживает за полем к югу от ферм.",
		["The northern peak"] = "Северная вершина",
		["The northern peak rises south-east of {area:272}, on the way down towards Durnholde."] = "Северная вершина возвышается к юго-востоку от места {area:272}, по пути вниз к Дарнхольду.",
		["The smithy"] = "Кузница",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "Кузница стоит в центре городка {area:287}. {npc:2404} и его подмастерья работают у горна; {object:1736} сложена рядом. {npc:2449} ходит по улице к северу от нее.",
		["The southern peak"] = "Южная вершина",
		["The western peak"] = "Западная вершина",
		["The {object:556670} poster by the inn"] = "Плакат у таверны: {object:556670}",
		["Train with {npc:3033}. Before you fly on, {npc:3024} and {npc:4721}, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts."] = "Обучитесь у NPC {npc:3033}. Перед вылетом возьмите два задания у NPC {npc:3024} и {npc:4721}, недалеко к востоку от распорядителя ветрокрылов: их выполняют по пути в следующих гайдах. Затем летите на Перекресток, где начинается следующий гайд.",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "К западу от Мельницы Таррен по холмам на пути к фермам бродят серые медведи, лесные моховые ползуны и голодные горные львы. {item:3477} падает с ползунов редко; нужен только один.",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["{area:272} is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square."] = "{area:272} – ваша база в этом гайде: камень возвращения дважды вернет вас сюда. Все стоят вокруг городской площади.",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}: используйте половинку здесь: {area:2362}",
		["{item:3692}: the Peasants in the fields"] = "{item:3692}: хилсбрадские крестьяне на полях",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} ({area:2361}) отправляет туда друидов по воздуху",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}, в Аптекарии",
		["{npc:2055}, in the {zone:1458}"] = "{npc:2055}, {zone:1458}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215}: приказы для NPC {npc:270438}, по пути к Дарнхольду",
		["{npc:2238}'s ball and chain"] = "Ядро и цепь: {npc:2238}",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274} — собака NPC {npc:232}, у северного фермерского дома ({area:286}).",
		["{npc:2391}: Poisons"] = "{npc:2391}: Яды",
		["{npc:270438}, once {quest:98094} is in"] = "{npc:270438}, после сдачи задания {quest:98094}",
		["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024}: {quest:97538}, мирквид у места {area:464} рядом с Солнечным Утесом",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606} стоит здесь: {object:36070}.",
		["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721}: {quest:1195}, флакон с хохочущих сестер ({zone:1440})",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "Недалеко к северу от лагерей Галак пещера ({area:1557}) ведет вниз к самому дальнему залу, где горит {object:20807}. Используйте на ней {item:5868}, затем сразу заберите {item:5869}: пламя гаснет ненадолго, и если оно разгорится снова, склянка пропадет. Затем идите на восток к плато NPC {npc:2986}.\nОсторожно: у жаровни стоят два огненных стража Галак (30), а по пещере ходит кентавр-стражник: оттяните их по одному, прежде чем гасить пламя.",
		["Back east to {area:484}: it lies on the way from {area:487} to {npc:2986}'s mesa."] = "Назад на восток: {area:484} – по пути от места {area:487} к плато NPC {npc:2986}.",
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "Назад на юг к лагерю, затем наверх: {zone:1456} – для полета в {area:378}.",
		["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "Назад к NPC {npc:12867} в лагерь лесорубов, на дороге на север к Заставе Расщепленного Дерева.",
		["Class trainer"] = "Учитель классовых навыков",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Поднимитесь по тропе на вершину: {area:2097}. {npc:10646} в плену рядом с NPC {npc:10896} (29): сначала уберите стражу и {npc:10896}, затем освободите ее и защищайте на спуске; по пути нападут засадники Зловещего Тотема.",
		["Felmusk satyrs"] = "Сатиры из племени Мускуса Скверны",
		["Fly to {area:1638}"] = "Летите сюда: {area:1638}",
		["Fly to {area:1638} from Zoram'gar. If you don't know its flight path, fly to {area:378} and walk north through {zone:1412} instead."] = "Летите сюда из форта Зорам'гар: {area:1638}. Если вы не знаете этот маршрут, летите в {area:378} и идите на север через {zone:1412}.",
		["Fly to {area:378}"] = "Летите сюда: {area:378}",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Идите по главной дороге на восток мимо места {area:415} (Альянс: держитесь дороги). {npc:12678}, большой медведь-гризли, бродит здесь: {area:418} – к югу от дороги, к западу от места {area:421}. Его лапа начинает следующее охотничье задание.",
		["From the {area:2360} head north-east to the Warsong lumber camp on the road: {npc:12867} stands there."] = "От места {area:2360} идите на северо-восток к Лесозаготовкам Песни Войны у дороги: там стоит {npc:12867}.",
		["Galak centaurs"] = "Кентавры из племени Галак",
		["Gazebo"] = "Беседка",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "{item:273001}, с обглоданных трупов ({npc:264096})",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "Продолжайте идти по дороге на восток. {npc:12858} ждет к юго-западу от Лесозаготовок Песни Войны. Он со своими бойцами штурмует {area:2360}: дайте им принять удар на себя и держитесь рядом с NPC {npc:12858}, пока {npc:12860} не погибнет.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "Убейте NPC {npc:10720}, который придет за {npc:10638}",
		["Laughing Sisters"] = "Смеющиеся сестры",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "К северу от лагеря пауки заполонили кладбище – {area:17044}. Используйте {item:273015} ({npc:264074}) на обглоданных трупах ({npc:264096}); с прядильщиц падает {item:273181}. {npc:264082} сидит в северном конце: ее {item:273658} начинает задание {quest:96294}.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "К северо-западу от заставы Расщепленного Дерева в лесу стоит лагерь сатиров из племени Мускуса Скверны. Рога могут упасть с любого сатира.",
		["On the way back north-east to Splintertree: {npc:12676} prowls the woods south-east of the Warsong lumber camp."] = "На обратном пути на северо-восток к заставе Расщепленного Дерева: {npc:12676} рыщет в лесу к юго-востоку от Лесозаготовок Песни Войны.",
		["Only if the {npc:10617} dropped his plot for you: {npc:10638} stands at {area:2237}."] = "Только если {npc:10617} выронил для вас свой план: {npc:10638} стоит здесь: {area:2237}.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Спуститесь на подъемнике, затем идите по дороге на восток через каньоны: {area:484}, деревня тауренов на вершинах столовых гор. Ее подъемник – на северной стороне.",
		["Sapphires of Aku'Mai"] = "Сапфиры Аку'май",
		["South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; {area:421} is west of it. Use the {item:5867} at the moonwell to fill it."] = "К югу от Приюта Чащобы лунный колодец лежит в низине к западу от реки, его трудно заметить с дороги; {area:421} – к западу от него. Используйте {item:5867} у лунного колодца, чтобы наполнить его.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "Поговорите с NPC {npc:3057} ({area:1638}): {quest:93739}",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Спуститесь на подъемнике. Яйцо лежит в гнезде на дне каньона в одном из трех мест: к юго-востоку от столовых гор (52.3,55.2), к востоку (56.4,50.4) или к юго-западу (37.6,56.1).",
		["The Earthen Ring"] = "Служители Земли",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Фурболги из племени Гиблой Чащи занимают лес к востоку от места {area:421}, к югу от дороги. Установите {item:16972} на {object:178206} и охраняйте: фурболги придут его сломать. {npc:12918} придет последним; его тотем падает в корзину.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks a long path between the camps: if you meet him, kill him, his note starts a quest for {area:2237}. Don't wait for him."] = "Лагеря Галак заполняют каньон к северу от заставы Вольного Ветра; разведчики, пастухи и ветроловки есть в каждом лагере. Одинокий {npc:10617} ходит между лагерями длинным маршрутом: если встретите его, убейте – его записка начинает задание для места {area:2237}. Не ждите его специально.",
		["The Laughing Sisters, dryads, wander {area:426} around {npc:12677}'s woods; one of them drops {npc:4721}'s {item:5867}, which can take several kills."] = "Смеющиеся сестры, дриады, бродят здесь: {area:426} – по лесу, где обитает {npc:12677}; одна из них роняет {item:5867} для NPC {npc:4721}, на это может уйти несколько убийств.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "Сапфиры – синие кристаллы на стенах туннелей, ведущих к порталу ({area:2797}), под землей и вне подземелья: нырните из ямы под стену в пещеру. Сатиры и наги в туннелях – элита: лучше собрать группу. Кристаллы быстро появляются снова, так что глубоко идти не нужно.",
		["The Wanted poster beside {npc:10537}"] = "Плакат «Разыскивается» рядом с {npc:10537} утесов",
		["The fountain stands in the middle of the {area:418}, where {npc:12678} roams: use the {item:7767} there."] = "Фонтан стоит посреди места {area:418}, где бродит {npc:12678}: используйте там {item:7767}.",
		["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "Ночные эльфы из задания {quest:6503} (23-24) рыщут в лесах к югу и юго-востоку от лагеря лесорубов; они скрываются, так что смотрите в оба.",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "Путь к сапфирам – через затонувшие руины в северном конце берега: спуститесь по лестнице в яму.",
		["Warsong lumber camp"] = "Лесозаготовки Песни Войны",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "К западу от заставы Вольного Ветра, под местом {area:2097}, – лагеря Зловещего Тотема. Тайные записки лежат в сундучках для бумаг ({object:176344}) в юго-восточном, юго-западном и северо-западном лагерях.",
		["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "К западу от Мистрального озера бродит {npc:12678}, большой медведь-гризли: {area:418}. Теперь с него падает лапа.",
		["for {npc:5901}, south of {area:392}: next guide"] = "для NPC {npc:5901}, к югу от поселения {area:392}: следующий гайд",
		["{area:2797} ruins"] = "Руины: {area:2797}",
		["{area:418} fountain"] = "Фонтан: {area:418}",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}, с прядильщиц ({npc:264081})",
		["{item:5867}, at the {object:20806}"] = "{item:5867}, у объекта {object:20806}",
		["{item:5867}, from a {npc:4054}"] = "{item:5867}, с NPC {npc:4054}",
		["{item:5868}, at the {object:20807}"] = "{item:5868}, у объекта {object:20807}",
		["{item:5869}, from the {object:20807}"] = "{item:5869}, из объекта {object:20807}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}, у распорядителя полетов",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "Следующее задание {npc:10428}, «Священное пламя», заканчивается в {zone:1456}, вне маршрута. Пропустите его.",
		["{npc:10617}'s {quest:4881}, if you meet him"] = "{quest:4881} от {npc:10617}, если встретите его",
		["{npc:11116}, beside {npc:4877}"] = "{npc:11116}, рядом с NPC {npc:4877}",
		["{npc:12196}, beside her"] = "{npc:12196}, рядом с ней",
		["{npc:12676}, a big nightsaber, prowls the same woods further east, on the way north to Splintertree. Her claw starts the next hunt quest."] = "{npc:12676}, большая ночная саблезубая кошка, рыщет в тех же лесах восточнее, по пути на север к Заставе Расщепленного Дерева. Ее коготь начинает следующее охотничье задание.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, теневая пантера, рыщет в лесу вокруг места {area:426}, к западу от лагеря сатиров. Ее голова начинает следующее охотничье задание.",
		["{npc:12696} keeps the hunt board at {area:428}, by the flight master: take {quest:6383} and hand it straight back. {npc:12678}, {npc:12676} and {npc:12677} drop their trophies only after it."] = "{npc:12696} ведет доску охоты здесь: {area:428}, у распорядителя полетов. Возьмите задание {quest:6383} и сразу сдайте его. {npc:12678}, {npc:12676} и {npc:12677} роняют свои трофеи только после этого.",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}: только если у вас есть страницы руководства",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "Затем {npc:12736} предложит задание ({area:2797}); не берите без группы.",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}, добавленный в Forever, стоит на западном берегу ({area:421}) с тремя быстрыми заданиями драконоборцев.",
		["{npc:259118} offers {quest:96261} only once {quest:96259} is handed in."] = "{npc:259118} предложит {quest:96261} только после сдачи задания {quest:96259}.",
		["{npc:259118}: {quest:96261} comes once this is handed in"] = "{npc:259118}: {quest:96261} – после сдачи этого задания",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986} стоит на вершине столовой горы к востоку от лагерей Галак. Для задания {quest:1149} сойдите с края досок рядом с ним: вы приземлитесь невредимым.",
		["{npc:3024} stands beside {npc:4721}, east of {npc:2995}."] = "{npc:3024} стоит рядом с NPC {npc:4721}, к востоку от NPC {npc:2995}.",
		["{npc:4721} stands a short walk east of {npc:2995}."] = "{npc:4721} стоит недалеко к востоку от NPC {npc:2995}.",
		["{npc:4721}: {npc:4722} at {area:484}, later in this guide"] = "{npc:4721}: {npc:4722} ({area:484}), позже в этом гайде",
		["{npc:4722} stands in {area:484}: {npc:4721}'s filled phial is for him."] = "{npc:4722} стоит здесь: {area:484}. Наполненный фиал от NPC {npc:4721} – для него.",
		["{npc:4722}: the {object:20807} in {area:1557}, among the Galak camps"] = "{npc:4722}: {object:20807} ({area:1557}), среди лагерей Галак",
		["{npc:4877}, the trade supplies vendor: the Screeching harpies of {area:487}; inside the inn"] = "{npc:4877}, торговец товарами: визгливые гарпии ({area:487}); в таверне",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole south of {area:378}, on the road to the {area:485}."] = "Хижина: {npc:5899} – на гребне над водопоем свинобразов к югу от места {area:378}, на дороге к месту {area:485}.",
		["{object:176344}, north-west camp"] = "{object:176344}, северо-западный лагерь",
		["{object:176344}, south-east camp"] = "{object:176344}, юго-восточный лагерь",
		["{object:176344}, south-west camp"] = "{object:176344}, юго-западный лагерь",
		["{zone:1456}'s central rise"] = "{zone:1456}, центральное возвышение",
} end)()
t.guides["forever/horde/30-40/01-hillsbrad-foothills"] = (function() return {
		["Back east to {area:272}."] = "Возвращайтесь на восток сюда: {area:272}.",
		["Back to the fields: the Peasants work south of the farmhouses. Careful: A fleeing peasant that reaches the town hall can bring back adds; snares or roots keep them from escaping."] = "Назад в поля: крестьяне работают к югу от фермерских домов. Осторожно: сбежавший крестьянин, добравшийся до ратуши, может привести подмогу; замедление или обездвиживание не дает им убежать.",
		["Back to {area:272}"] = "Назад: {area:272}",
		["Back to {area:272}."] = "Назад сюда: {area:272}.",
		["Below ground"] = "Под землей",
		["Boulderfist camp"] = "Лагерь клана Тяжелого Кулака",
		["Daggerspine naga"] = "Наги из клана Пронзающего Гребня",
		["Daggerspine shore"] = "Берег наг Пронзающего Гребня",
		["Drull's ball and chain"] = "Ядро и цепь Друлла",
		["Fly to {area:272}"] = "Летите сюда: {area:272}",
		["For characters of 29 to 33, but most quests here are level 32-34, a few up to 36: on purpose, for their experience. The Syndicate, {area:279}'s guards and the Boulderfist ogres are 31-35, so pull them one at a time."] = "Для персонажей 29-33 уровня, но большинство заданий здесь 32-34 уровня, а некоторые – до 36-го: намеренно, ради опыта. Синдикат, стражники ({area:279}) и огры из клана Тяжелого Кулака – 31-35 уровня, так что выманивайте их по одному.",
		["From {area:271} head north past {area:272} and follow the road on into the Alterac foothills. {quest:535} waits by the Syndicate camp. He offers his errand only while you carry {npc:2229}'s Infiltration: hand him the stout at once, and his reward is the Syndicate Missive Krusk wants. A missive from the Syndicate here does the same: with one in your bags the guide passes {quest:535}."] = "От места {area:271} идите на север мимо поселения {area:272} и дальше по дороге в предгорья Альтерака. {quest:535} ждет у лагеря Синдиката. Он предлагает поручение, только пока у вас есть «Шпионская работа» от NPC {npc:2229}: сразу отдайте ему эль, и в награду он даст «Послание Синдиката», которое нужно Круску. Послание с членов Синдиката здесь подойдет так же: если оно есть в сумках, гайд пропускает шаг с {quest:535}.",
		["Head back south down the road to {area:272}."] = "Возвращайтесь на юг по дороге сюда: {area:272}.",
		["Hillsbrad Peasants"] = "Хилсбрадские крестьяне",
		["Inside"] = "Внутри",
		["Inside {area:288}"] = "Внутри: {area:288}",
		["On to {area:287} town, south-west of the yeti caves. The town hall is on the town's west side: {npc:2335} (30) and {npc:2448} are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town."] = "Дальше – в городок {area:287}, к юго-западу от пещер йети. Ратуша – в западной части городка: {npc:2335} (30) и {npc:2448} внутри, там же городской реестр; рядом висит прокламация. По городку ходят члены совета.",
		["Only if {quest:535}'s missive didn't come your way: the Syndicate Footpads and Thieves (32-34) around the camps west of the road carry missives too; about one in three drops one. Careful: at 31-32 they are still above you and stand close together, with Wizards (34-35) among them: pull one at a time from the camp's edge."] = "Только если послание от {quest:535} к вам не попало: преступники и воры Синдиката (32-34) у лагерей к западу от дороги тоже носят послания; примерно с каждого третьего падает одно. Осторожно: на 31-32 уровне они все еще выше вас и стоят кучно, а среди них – волшебники (34-35): выманивайте по одному с края лагеря.",
		["Shindigger keg"] = "Бочонок «Землекопского крепкого»",
		["South-east of Tarren Mill. Drull and {npc:2238} are chained in the keep's courtyard buildings: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks."] = "К юго-востоку от Мельницы Таррен. Друлл и {npc:2238} прикованы в постройках во дворе крепости: {npc:2427} носит {item:3467}, а {npc:2428} – {item:3499}, оба в крепости. Убейте их, затем откройте оба замка.",
		["South-west, the Cave and Ferocious Yetis (30-32) fill the {area:277} in the hills west of {area:272}; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but at 29-30 they hit hard and come in pairs."] = "К юго-западу пещерные и лютые йети (30-32) заполняют {area:277} в холмах к западу от поселения {area:272}; примерно у одного из шестнадцати есть жезл. Оставайтесь в этих пещерах: горные и гигантские йети (32-34) из пещеры дальше к северу тоже носят его, но на 29-30 уровне они бьют сильно и ходят парами.",
		["Syndicate missives"] = "Донесения Синдиката",
		["The smithy"] = "Кузница",
		["The third flame burns in the smaller cave up in the hills north of the caverns.\nCareful: Giant and Mountain Yetis (32-34) stand around the flame, often in pairs, and Frostmaw, a rare yeti (37), roams nearby. At 30-31 they are over your level: pull the yetis one at a time from the cave mouth before you use the Rod, and watch for Frostmaw before you go in."] = "Третье пламя горит в пещере поменьше, выше в холмах к северу от пещер.\nОсторожно: вокруг пламени стоят гигантские и горные йети (32-34), часто парами, а рядом бродит Ледочрев, редкий йети (37). На 30-31 уровне они выше вас: выманивайте йети по одному от входа в пещеру, прежде чем применять жезл, и высматривайте Ледочрева, прежде чем входить.",
		["The {area:279} crater's eastern rim"] = "Восточный край кратера {area:279}",
		["Torn Fin beach"] = "Пляж мурлоков Рваного Плавника",
		["Torn Fin murlocs"] = "Мурлоки из племени Рваного Плавника",
		["Town hall"] = "Ратуша",
		["Train"] = "Обучение",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Обучитесь, пока вы здесь ({zone:1458}): учителя – здесь: {object:36070}, {object:36073} и {object:36082} (паладины: {npc:260093}).",
		["Train your new spells."] = "Изучите новые заклинания.",
		["West across the foothills to {area:287} town: the smithy stands in the middle of it. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it."] = "На запад через предгорья к поселению {area:287}: кузница стоит в его центре. {npc:2404} и его подмастерья работают у горна; {object:1736} сложена рядом.",
		["West past the hills to the farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere."] = "На запад за холмы, к фермам к востоку от поселения {area:287}. {npc:232} работает в поле у северного фермерского дома, {npc:2403} – на поле дальше к юго-востоку; батраки и фермеры повсюду.",
		["You missed Darthalia's first errands, from the 22-25 {area:287} guide: they come first now. They are a few levels below you and quick, and they open the rest of the {quest:527} in this guide."] = "Вы пропустили первые поручения Дарталии из гайда по {area:287} (22-25): теперь они идут первыми. Они на несколько уровней ниже вас и быстрые, а еще открывают остальную часть цепочки {quest:527} в этом гайде.",
		["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388}: аукцион или алхимик, для задания {quest:515}.",
		["{item:3703}, for {npc:2333}"] = "{item:3703}, для персонажа {npc:2333}",
		["{npc:2229} wants his two scouts freed from {area:275} before he trusts you with Infiltration."] = "{npc:2229} хочет, чтобы вы освободили двух его разведчиков ({area:275}), прежде чем доверит вам «Шпионскую работу».",
		["{npc:2238}'s ball and chain"] = "Ядро и цепь: {npc:2238}",
		["{npc:2792}, by the gate"] = "{npc:2792}, у ворот",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}, Крепость Громмаш, если у вас есть это задание",
		["{object:1761}, inside"] = "{object:1761}, внутри",
		["{zone:1458} trainers"] = "Учителя: {zone:1458}",
} end)()
t.guides["forever/horde/30-40/02-thousand-needles"] = (function() return {
		["Back south to {npc:11863}'s tower."] = "Обратно на юг к башне, где ждет {npc:11863}.",
		["Clam beds"] = "Отмели с моллюсками",
		["Fly to {area:460}"] = "Летите сюда: {area:460}",
		["Fly to {area:484}"] = "Летите сюда: {area:484}",
		["Head north along the coast, then inland to the ruined tower of {area:2405}: {npc:11863} waits inside. The coast's clams and naga come after {area:599}, on one walk north to {area:2406}."] = "Идите на север вдоль побережья, затем вглубь суши к разрушенной башне ({area:2405}): внутри ждет {npc:11863}. Моллюски и наги на побережье – после этого места: {area:599}; их вы пройдете за один переход на север сюда: {area:2406}.",
		["Keep north to {area:598}. The Slitherblade Myrmidons, Naga and Sorceresses hold the beach; pull them one at a time. Any Slitherblade can drop {item:15881}."] = "Продолжайте путь на север: {area:598}. Пляж удерживают мирмидоны, наги и колдуньи из клана Скользящего Клинка; выманивайте их по одному. {item:15881} может выпасть с любой наги Скользящего Клинка.",
		["Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}. He is well above you: rest to full first. {object:177786} stands on the shore beside the statue: open it with both keys."] = "Плывите к острову у самой северной оконечности ({area:2406}) и используйте {item:15766} на объекте {object:177673}: появится {npc:12369} (38); убейте его, чтобы получить {quest:6027}. Он намного сильнее вас: сначала полностью восстановитесь. {object:177786} стоит на берегу рядом со статуей: откройте его обоими ключами.",
		["The zeppelin lands at the tower outside {zone:1454}'s main gate. {npc:5639} walks the Drag: if he isn't at the arrow, look along its streets to the south-west. {npc:5640} stands in the {object:172961} on the west side of the city."] = "Дирижабль причаливает к башне у главных ворот города {zone:1454}. {npc:5639} бродит по Аллее Чести: если его нет у стрелки, поищите на улицах к юго-западу. {npc:5640} стоит здесь: {object:172961}, в западной части города.",
		["West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a {item:15874}. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry {item:15878}, about one in seven."] = "На запад к берегу. Гигантские мягкопанцирные моллюски лежат на мелководье, а разъяренные рифовые ползуны бродят по пляжу: каждый моллюск, открытый на морском дне, и некоторые ползуны дают {item:15874}. Откройте каждый в сумке, чтобы достать мясо.\nСухощелкие ползуны и клешнецы на том же пляже носят {item:15878} – примерно один из семи.",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["{item:15766}, on the {object:177673}"] = "{item:15766} – на объекте {object:177673}",
		["{item:15878}, from the Drysnap crabs"] = "{item:15878} – с сухощелких крабов",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881} – с наг Скользящего Клинка",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "Следующее поручение {npc:5641} – повелитель демонов с элитной охраной: пропустите его.",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892} стоит здесь: {object:172957}.",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527} и ваш {item:5177}",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905} также выдает задание о помощи стихий ({area:1717}) – цепочку 33-40 к оружию бури: forever/class/shaman/call-of-air-horde.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: ваш {item:5178}",
		["{object:177787} lies on the ground just south-west of {npc:11863}'s tower, on the way down to the shore: read it. Its two keys drop only while you have the quest."] = "{object:177787} лежит на земле к юго-западу от башни, где ждет {npc:11863}, по пути вниз к берегу: прочитайте его. Оба ключа выпадают, только пока у вас есть задание.",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/30-40/03-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Обратно на север к лагерю.",
		["Back to {object:3202}."] = "Вернитесь: {object:3202}.",
		["Boat to {area:35}"] = "Корабль: {area:35}",
		["Dizzywig's parts go back to Kravel in the {area:439}, off the route: leave them."] = "Детали Шестерень надо вернуть Кравелу в место {area:439}, это не по маршруту: оставьте их.",
		["Fly to {area:35}"] = "Летите: {area:35}",
		["Fly to {area:392}"] = "Летите: {area:392}",
		["Fly to {object:3202}"] = "Летите: {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. {npc:773} wants it investigated: walk among its tents. From here on, keep every page of {quest:338} you loot: {npc:716} takes them on your next Stranglethorn visit."] = "Идите по дороге на север из места {object:3202}; охотничий лагерь Эрнестуэя — на холме к северо-востоку от реки. {npc:773} просит его осмотреть: пройдите между палатками. С этого момента сохраняйте каждую страницу из книги «{quest:338}»: {npc:716} примет их при следующем посещении Тернистой долины.",
		["Green Hills pages"] = "Страницы «Зеленых холмов»",
		["Leave {area:35} through the tunnel and follow the road north to {object:3202}, the orc camp on the west side of the vale. Stay on the road: the jungle beside it is above your level."] = "Покиньте {area:35} через туннель и идите по дороге на север к месту {object:3202} — лагерю орков на западной стороне долины. Не сходите с дороги: джунгли рядом выше вашего уровня.",
		["Mosh'Ogg camp"] = "Лагерь Мош'Огг",
		["Nesingwary's camp"] = "Лагерь Эрнестуэя",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "К северо-западу от Лагеря Гром'гол под водой у побережья лежит {area:104}. {item:4094} лежит на морском дне у затонувших руин; следите за дыханием и мурлоками.",
		["River Crocolisks lie along the river below the camp. Young Stranglethorn Tigers prowl west of the camp, Young Panthers east of it. Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it. Careful: The troll camps have many patrolling mobs, so other trolls often join a fight."] = "Речные кроколиски лежат вдоль реки ниже лагеря. Молодые тигры Тернистой долины бродят к западу от лагеря, молодые пантеры — к востоку. Идите на запад мимо лагеря. Ящеры Тернистой долины (33-34) охотятся на полянах, а тролли Кровавого Скальпа занимают руины на побережье: с любого из них может выпасть клык. {item:4614} выпадает с них очень редко: если выпадет, прочтите. Осторожно: в лагерях троллей много патрулей, поэтому к бою часто присоединяются другие тролли.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "Тенебрюхие пантеры будут гораздо позже, у объекта {object:3202}",
		["from {npc:4723}"] = "с NPC {npc:4723}",
		["{area:2408} flight master"] = "Распорядитель полетов: {area:2408}",
		["{area:35} first: the goblins' boat sails there from {area:392}, and every {area:35} quest is for the north of the vale, which you then walk up into."] = "Сначала {area:35}: туда ходит корабль гоблинов из места {area:392}, а все задания из места {area:35} ведут на север долины, куда вы затем подниметесь пешком.",
		["{item:5852}, in {object:20691}"] = "{item:5852}, в объекте {object:20691}",
		["{npc:2464} stands in the middle of {object:3202}, {npc:2497} near the zeppelin tower, {npc:2465} beside the flight master."] = "{npc:2464} стоит в центре места {object:3202}, {npc:2497} — у башни дирижаблей, {npc:2465} — рядом с распорядителем полетов.",
		["{npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs beside the flight master."] = "Лавка NPC {npc:2495} — в здании к востоку от таверны; {npc:2498} на нижнем этаже таверны, {npc:2496}, {npc:737} и {npc:773} — наверху, рядом с распорядителем полетов.",
		["{npc:2496}, upstairs"] = "{npc:2496}, на втором этаже",
		["{npc:2496}: Cozzle's footlocker is at {area:37}, later in this guide"] = "{npc:2496}: сундучок Козла находится у места {area:37}, позже в этом гайде",
		["{npc:2496}: for Pozzik at the {area:2240}, on the way to {zone:1446} around level 43"] = "{npc:2496}: для Поззика на месте {area:2240}, по пути в {zone:1446} примерно на 43-м уровне",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}: для Нагорья Арати, позже по маршруту",
		["{npc:3391} waits upstairs in the house by the flight master; {quest:1111} stands on the docks, beside the boat."] = "{npc:3391} ждет на втором этаже дома у распорядителя полетов; {quest:1111} стоит на причале, рядом с кораблем.",
		["{npc:3391}, upstairs"] = "{npc:3391}, на втором этаже",
		["{npc:3391}: for {npc:4631} in {area:35}, where the boat goes"] = "{npc:3391}: для NPC {npc:4631} в месте {area:35}, куда идет корабль",
		["{npc:4631} stands on the pier where the boat docks. {npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs, {npc:2858} the flight master on the upper deck."] = "{npc:4631} стоит на пирсе, где причаливает корабль. Лавка NPC {npc:2495} — в здании к востоку от таверны; {npc:2498} на нижнем этаже таверны, {npc:2496}, {npc:737} и {npc:773} — наверху, {npc:2858}, распорядитель полетов, — на верхней палубе.",
		["{npc:4631}, on the pier"] = "{npc:4631}, на пирсе",
		["{npc:4723} (38) is inside the Venture Co. house on {area:37}'s west shore, among the geologists: his key opens {object:20691} in the same house, which holds the blueprints for {npc:2496}."] = "{npc:4723} (38) находится в доме Торговой компании на западном берегу места {area:37}, среди геологов: его ключ открывает {object:20691} в том же доме, где лежат чертежи для NPC {npc:2496}.",
		["{quest:1111}, on the docks"] = "{quest:1111}, на причале",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Fly to {area:378}"] = "Летите сюда: {area:378}",
		["Head back west to Brackenwall with the head: {npc:4503} stands at the south edge of the village where the road comes in, {npc:4791} in the village."] = "Возвращайтесь с головой на запад в Гиблотопь: {npc:4503} стоит на южном краю деревни, у въезда, {npc:4791} – в деревне.",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "Ярл живет здесь: {area:497}, к юго-востоку от места {area:502}.",
		["Mirefin murlocs"] = "Мурлоки Болотного Плавника",
		["South-east from the manor to {area:513}: the {object:20925} lies on the sea floor off the docks on the isle's east side. Swim in and out and keep off the piers and the town: Theramore's guards are level 53-57."] = "На юго-восток от поместья к месту {area:513}: {object:20925} лежит на морском дне у причалов на восточной стороне острова. Подплывайте и уплывайте, держитесь подальше от пирсов и городка: стражники Терамора 53-57 уровня.",
		["Stinky Ignatz"] = "«Вонючка» Игнац",
		["Swamp Eye Jarl"] = "Ярл «Болотный Глаз»",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "На развилке сверните на север к деревне огров Гиблотопь.",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "Мурлоки племени Болотного Плавника толпятся на побережье к востоку и северо-востоку от места {area:502}; головы падают со всех видов.",
		["The {area:2657}"] = "{area:2657}",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "только если у вас есть {item:3853} ({skill:164} или аукцион)",
		["{area:2408} flight master"] = "Распорядитель полетов: {area:2408}",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}: для Ярла «Болотного Глаза»",
		["{npc:3446} stands below Gazlowe's house by the flight master, towards the docks."] = "{npc:3446} стоит под домом Газлоу, у распорядителя полетов, ближе к причалам.",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, на южном краю деревни, у въезда",
		["{npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out."] = "{npc:4983} ждет здесь: {area:2302}, к востоку от деревни. Следуйте за ним к Риту и не дайте ему погибнуть в завязавшемся бою.",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019} ждет в лагере гоблинов в западной части места {area:596}.",
		["{object:20985}, beside the manor"] = "{object:20985}, у усадьбы",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, теперь, когда {npc:4791} прочел донесение",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/30-40/05-arathi-highlands"] = (function() return {
		["Back to {area:321}"] = "Назад: {area:321}",
		["Below ground"] = "Под землей",
		["Fleshstalker raptors"] = "Ящеры-плотоглоты",
		["Fly to {area:272}"] = "Летите сюда: {area:272}",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "Плотоглоты нагорья (36-37) охотятся на южном нагорье: стая к северу от места {area:316} и еще одна на равнине к западу. Выманивайте по одному.",
		["Inside"] = "Внутри",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "Внутренний круг – к югу от западного, к востоку от Стромгарда.",
		["The magus offers a dungeon errand next: leave it."] = "Затем маг предлагает поручение в подземелье: не берите его.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:1763} poster by the inn"] = "Плакат у таверны: {object:1763}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} – в дальнем конце ущелья.",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Обучитесь, пока вы здесь ({zone:1458}): учителя – здесь: {object:36070}, {object:36073} и {object:36082} (паладины: {npc:260093}).",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "К западу от бухты налетчики и колдуньи из клана Пронзающего Гребня (38-40) занимают берег: выманивайте по одному. Два затонувших корабля лежат на мелководье, карты и журналы – внутри; самоцветы лежат на дне вокруг кораблей.",
		["{npc:2792}, by the gate"] = "{npc:2792}, у ворот",
		["{zone:1458} trainers"] = "Учителя: {zone:1458}",
} end)()
t.guides["forever/horde/30-40/06-badlands"] = (function() return {
		["Below ground"] = "Под землей",
		["Head west along the road towards {area:340}; {npc:2921}'s camp sits in the {area:1878} halfway there."] = "Идите на запад по дороге к месту {area:340}; лагерь {npc:2921} – здесь: {area:1878}, на полпути.",
		["Into the {zone:1418}"] = "В край {zone:1418}",
		["Keep north on the road; the chest lies in the {area:1517} dig site, at the foot of the ruins north-west of the road."] = "Идите дальше на север по дороге; сундук – на раскопках ({area:1517}), у подножия руин к северо-западу от дороги.",
		["Lesser Rock Elementals"] = "Младшие каменные элементали",
		["Rock Elementals"] = "Каменные элементали",
		["Stonevault troggs"] = "Трогги Каменного Свода",
		["The road north to {area:1517} runs through the {area:1877}: {npc:2817} and {npc:4618} take the wings and the flakes on the way."] = "Дорога на север к месту {area:1517} проходит здесь: {area:1877}. По пути {npc:2817} и {npc:4618} принимают крылья и хлопья.",
		["The small elementals drift across the flats between {area:340} and {npc:2921}'s camp, on the road back east. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards."] = "Маленькие элементали бродят по равнине между местом {area:340} и лагерем {npc:2921}, по дороге обратно на восток. С любого каменного элементаля в зоне могут падать осколки каменного элементаля для {npc:6868}.",
		["for Helgrum in {area:75}, around level 42"] = "для Хелгрума ({area:75}), примерно на 42-м уровне",
		["{area:340} is the Horde fortress built into the cliffs at the zone's western edge. {npc:5394} stands on {area:340}'s upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart."] = "{area:340} – крепость Орды в скалах у западного края зоны. {npc:5394} стоит на верхнем ярусе ({area:340}), высоко над распорядителем полетов: поднимайтесь по пандусам, стрелка не различает ярусы.",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106}: письмо Пшикса Медноштифа ({area:439})",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Below ground"] = "Под землей",
		["Draenethyst crystals"] = "Кристаллы дренетиста",
		["Fly to {area:35}"] = "Летите: {area:35}",
		["Fly to {object:3202}"] = "Летите сюда: {object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "Идите вдоль берега на юг. Наги-исследователи бродят по берегу и носят связки тростника; {object:759} бурлит в холмах чуть к востоку.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "Отдайте Унбагве клыки и оставайтесь рядом: он призовет три волны горилл, затем {npc:1514}. Бейтесь с ними по одному.",
		["Inside"] = "Внутри",
		["Into the {zone:1435}"] = "В край {zone:1435}",
		["Ironjaw Basilisks"] = "Железозубые василиски",
		["Jungle Stalkers"] = "Тропические ловцы",
		["Jungle stalkers"] = "Ящеры-ловчие",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "Выйдите из города через туннель; записка лежит в пиратской бухте чуть к северу от места {area:35}.",
		["Mistvale gorillas"] = "Гориллы из Мглистой долины",
		["Nesingwary's camp"] = "Лагерь Эрнестуэя",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "Нобору бродит по поляне к юго-западу от места {area:76}; его дубина начинает задание.",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "К северо-востоку от Мглистой долины в джунглях стоят лагерем последователи Занзила; смесь может быть у любого из них.",
		["Pirate ghosts"] = "Призраки пиратов",
		["Ride north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "Езжайте на северо-восток сюда: {area:76}. Кристаллы стоят по пути к клетке ({npc:5391}).",
		["Sawtooth crocolisks"] = "Острозубые кроколиски",
		["Skullsplitter warriors"] = "Воины из племени Дробителей Черепов",
		["South of Booty Bay the Bloodsail swashbucklers camp on the {area:43}; the charts and the orders lie in their tents. Any Bloodsail can carry snuff and {npc:2493}'s eye, so keep killing until you have both."] = "К югу от Пиратской бухты висельники из шайки Кровавого Паруса стоят лагерем здесь: {area:43}; карты и приказы лежат в их палатках. Нюхательный табак и глаз {npc:2493} может нести любой пират Кровавого Паруса: убивайте, пока не получите оба.",
		["The Bloodsail ships"] = "Корабли Кровавого Паруса",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "Тропические ловцы (40-41) охотятся на побережье к югу от места {object:3202}. Они намного выше вас: выманивайте по одному и отдыхайте между боями.",
		["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank."] = "Кроколиски лежат в лужах вокруг лагеря {npc:5391} и к югу, к месту {area:75}; бок падает примерно с каждого четвертого.",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "Гориллы бродят по долине вокруг Унбагвы. Потроха падают со старых горилл; клык может упасть с любой.",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp.\nThe last skulls are in the ruins a short walk west, on the way back to {object:3202}."] = "Следующие трофейные черепа – в небольших руинах чуть к северу от лагеря воинов.\nПоследние черепа – в руинах недалеко к западу, по пути обратно сюда: {object:3202}.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "Ящеры-ловчие охотятся в джунглях к югу от места {object:3202}, ближе к западному побережью.",
		["The three ghostly pirates haunt the jungle north of {area:35}, near Zanzil's camps: {npc:2535} and {npc:2536} stand together, {npc:2537} further east."] = "Три призрачных пирата бродят в джунглях к северу от места {area:35}, у лагерей Занзила: {npc:2535} и {npc:2536} стоят вместе, {npc:2537} – дальше к востоку.",
		["The {area:43}"] = "{area:43}",
		["Venture Co. mine"] = "Рудник Торговой компании",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them. Stay on the Bloodscalps here until level 41: {quest:586}, at the cauldron next, sends you to Skullsplitters of 41-43. Or, with a group, run the {area:1517} dungeon instead.\nOn the coast between Zul'Kunda and {object:3202} an {npc:2635} (level 38 elite) shares the spawns of the ordinary crocolisks: kill it if it is up and take its skin for {npc:2495}."] = "К западу от экспедиции вожди племени Кровавого Скальпа – {npc:1061} и {npc:1062} – стоят вместе в руинах Зул'Кунды. Сначала перебейте охрану, затем выманите их. Бейте троллей Кровавого Скальпа здесь до 41-го уровня: задание {quest:586}, следующее у котла, отправит вас к Дробителям Черепов 41-43 уровня. Или, с группой, пройдите вместо этого подземелье {area:1517}.\nНа побережье между Зул'Кундой и местом {object:3202} {npc:2635} (элитный, 38-й уровень) появляется на месте обычных кроколисков: если он на месте, убейте его и снимите шкуру для {npc:2495}.",
		["Zanzil's camps"] = "Лагеря Занзила",
		["Zul'Kunda"] = "Зул'Кунда",
		["Zul'Mamwe"] = "Зул'Мамбве",
		["for a later stop in the {zone:1435}"] = "для более поздней остановки ({zone:1435})",
		["the Drowned City's entrance, underwater"] = "вход в Затонувший город, под водой",
		["the {object:2076}"] = "{object:2076}",
		["the {object:2076}, beside {npc:2497}"] = "{object:2076}, рядом: {npc:2497}",
		["{npc:2495}, inside: the {item:4105}"] = "{npc:2495}, внутри: {item:4105}",
		["{npc:2495}: the {npc:2635} suns on the coast between Zul'Kunda and {object:3202}, later on this loop"] = "{npc:2495}: {npc:2635} греется на побережье между Зул'Кундой и местом {object:3202}, позже на этом круге",
		["{npc:2496}, on the balcony beside MacKinley"] = "{npc:2496}, на балконе рядом с Мак-Кинли",
		["{npc:2519}: the cavern entrance under the {area:104}, west of the camp"] = "{npc:2519}: вход в пещеру под местом {area:104}, к западу от лагеря",
		["{npc:4631}, on the docks: Gazlowe's letter, if you carry it"] = "{npc:4631}, на пристани: письмо Газлоу, если оно у вас есть",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391} в плену здесь: {area:76}, на северо-востоке болота. Освободите его и следуйте за ним, отбиваясь от болотных тварей.",
		["{quest:95770}: west of {object:3202}, swim out over the {area:104} and dive to the cavern entrance in the reef; the quest completes as you find it. Leave the cavern for now: the jungle stalkers are south along the coast."] = "{quest:95770}: к западу от места {object:3202} плывите над местом {area:104} и нырните к входу в пещеру в рифе; задание выполнится, как только вы его найдете. Пока не заходите в пещеру: ящеры-ловчие – к югу вдоль побережья.",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Fly to {area:1638}"] = "Летите сюда: {area:1638}",
		["Fly to {area:484}"] = "Летите сюда: {area:484}",
		["Fly to {object:3202}"] = "Летите сюда: {object:3202}",
		["Fly to {zone:1454}. From the flight master: the {object:172960}, then the Drag, then the {object:172958}."] = "Летите в {zone:1454}. От распорядителя полетов: {object:172960}, затем Волок, затем {object:172958}.",
		["Grimtotem camp"] = "Лагерь Зловещего Тотема",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "Кодо: {npc:3685}, рядом с персонажем {npc:3690} ({area:222}).",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "К северу от гноллов огры занимают заставу на холме; выманивайте огров-магов к себе. Кобальт – в кучах земли вокруг заставы, а свиток лежит на земле внутри.",
		["North-west of the ruins, the yetis den in {area:1105}; every yeti there can drop a thick hide."] = "К северо-западу от руин, в месте {area:1105}, логово йети; толстая шкура может упасть с любого йети там.",
		["Only with the distress beacon: any beast, gnoll or ogre in {zone:1444} can drop it, about one kill in a hundred; use it to start the quest. The robot sits in a small cave on the north side of {area:1105}, just north-west of the ruins. Escort it to the dock on the {area:1108}; yetis and gorillas ambush you on the way. Its reward waits in {area:35} for a later visit.\nCareful: Three ambushes spawn during the escort, and the robot warns you before each one. The first is 3 yetis, just after the robot leaves the cave and climbs toward the road. The second is 3 gorillas, on the path that runs along the cliff. The third is about 4 gnolls, one of them a caster, where the route turns off toward the dock."] = "Только с аварийным маяком: он может упасть с любого зверя, гнолла или огра в краю {zone:1444}, примерно один раз из ста; используйте его, чтобы начать задание. Робот сидит в небольшой пещере в северной части места {area:1105}, чуть к северо-западу от руин. Сопроводите его к причалу в месте {area:1108}; по пути нападут йети и гориллы. Награда ждет здесь: {area:35} – заберете позже.\nОсторожно: во время сопровождения будет три засады, и робот предупреждает перед каждой. Первая – 3 йети, сразу после того, как робот выйдет из пещеры и поднимется к дороге. Вторая – 3 гориллы, на тропе вдоль утеса. Третья – около 4 гноллов, один из них заклинатель, там, где маршрут сворачивает к причалу.",
		["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "Ящеры: Зьольнир, рядом с персонажем {npc:7953} ({area:367}).",
		["Ride north-east to the goblin harbour on the coast."] = "Езжайте на северо-восток к гоблинской гавани на побережье.",
		["Ride west from the hive to the ogre ruins below {area:1105}. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb."] = "Езжайте на запад от улья к руинам огров ниже места {area:1105}. Там шаманы, чернокнижники и изверги; сфера – у магов-лордов в южной части.",
		["Riding at 40"] = "Верховая езда на 40-м уровне",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "Таурены племени Зловещего Тотема стоят лагерем у рощи хамелеонов; рога есть у налетчиков, натуралистов и шаманов.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "Улей Цуккаш врыт в холмы к юго-востоку от лагеря; {quest:7731} ждет в самой дальней камере.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "Тактическая карта лежит в лагере Древолапов к югу от Лагеря Мохаче.",
		["Upstairs"] = "Наверху",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Волки: {npc:3362}, рядом: {npc:4752}.",
		["Woodpaw battle map"] = "Тактическая карта Древолапов",
		["Woodpaw north camp"] = "Северный лагерь Древолапов",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["for the {zone:1425}, around level 48"] = "для края {zone:1425}, примерно на 48-м уровне",
		["for {area:35}, around level 50"] = "для места {area:35}, примерно на 50-м уровне",
		["for {zone:1454}, around level 45"] = "для города {zone:1454}, примерно на 45-м уровне",
		["the Rage Scar yetis, on the next visit to {zone:1444}"] = "йети Яростного Шрама – при следующем посещении края {zone:1444}",
		["water pouches in your bags"] = "бурдюки с водой в сумках",
		["{area:1105} yetis"] = "Йети: {area:1105}",
		["{area:392} for the Felsteed"] = "{area:392} – для коня Скверны",
		["{area:976} is the walled goblin town just past the {zone:1446} border."] = "{area:976} – обнесенный стеной гоблинский город сразу за границей края {zone:1446}.",
		["{npc:3690}, riding trainer"] = "{npc:3690}, учитель верховой езды",
		["{npc:4630}: the {item:5852} from {npc:2496}, if you carry them"] = "{npc:4630}: {item:5852} от персонажа {npc:2496}, если они у вас есть",
		["{npc:4706}, beside {npc:4630}"] = "{npc:4706}, рядом: {npc:4630}",
		["{npc:4752}, riding trainer"] = "{npc:4752}, учитель верховой езды",
		["{npc:6986}, the Drag"] = "{npc:6986}, Волок",
		["{npc:7010}, the Drag"] = "{npc:7010}, Волок",
		["{npc:7953}, riding trainer"] = "{npc:7953}, учитель верховой езды",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}: для города {zone:1454}, примерно на 45-м уровне",
		["{quest:2863}: one hour from now"] = "{quest:2863}: в течение часа",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "Назад на восток мимо места {area:75}: артефакты Атал'ай лежат в воде и на берегах (задание: {quest:1424}).",
		["Below ground"] = "Под землей",
		["Dragon caves"] = "Драконьи пещеры",
		["Fly to {area:1099}"] = "Летите сюда: {area:1099}",
		["Fly to {area:75}"] = "Летите сюда: {area:75}",
		["Frayfeather hippogryphs"] = "Блеклоперые гиппогрифы",
