t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["Back through the tunnel and take the {zone:1452} exit, then ride south to {area:2246}."] = "Назад через туннель к выходу ({zone:1452}), затем на юг сюда: {area:2246}.",
		["Back to {area:2268}"] = "Назад: {area:2268}",
		["Below ground"] = "Под землей",
		["Both quests lead to {zone:1451}: keep them."] = "Оба задания ведут в край {zone:1451}: сохраните их.",
		["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "Осторожно: {npc:10411} становится невидимым вне боя и призывает горгулий-камнекрылов, когда начинается бой. Их всего 3, и они возрождаются каждые 15 мин.",
		["Class trainer"] = "Учитель классовых навыков",
		["Drink the {item:11243} at the graveyard just east of {area:976}: it kills you, and only as a ghost can you see {npc:9299}, in a rocky crevice in the hills due north of it. Talk to him there, then run back to your body and resurrect: the Conspicuous Gravestone he sends you to stands in that graveyard."] = "Выпейте {item:11243} на кладбище чуть к востоку от места {area:976}: он вас убьет, и только в облике призрака можно увидеть {npc:9299} – в скальной расщелине в холмах прямо к северу от кладбища. Поговорите с ним там, затем бегите обратно к телу и воскресните: приметное надгробие, к которому он вас отправит, стоит на том же кладбище.",
		["Fly to {area:1638}"] = "Летите сюда: {area:1638}",
		["Fly to {area:2268}"] = "Летите сюда: {area:2268}",
		["Fly to {area:272}"] = "Летите сюда: {area:272}",
		["Fly to {area:976}"] = "Летите сюда: {area:976}",
		["Follow the road east from the {zone:1422}, over the river and across the whole {zone:1423}, to the {object:92525}'s chapel in the far east."] = "Следуйте по дороге на восток от края {zone:1422}, через реку и через весь край {zone:1423}, к часовне ({object:92525}) на крайнем востоке.",
		["Free Darrowshire Spirits: talk to them"] = "Освободите духов Дарроушира: поговорите с ними",
		["Frenzied Plaguehounds and Monstrous Plaguebats share the fields around {area:2272} and {area:2271}, south of {area:2273}."] = "Бесноватые чумные псы и чудовищные чумные нетопыри бродят по полям вокруг мест {area:2272} и {area:2271}, к югу от места {area:2273}.",
		["Go through {area:1769} and take the {zone:1450} branch of the tunnel. {npc:11801} is in {area:2361}."] = "Пройдите через место {area:1769} и сверните в ответвление туннеля ({zone:1450}). {npc:11801} – здесь: {area:2361}.",
		["Inside"] = "Внутри",
		["Keep {quest:5152}: {npc:10927} lives at {area:197} in the {zone:1422}."] = "Сохраните задание {quest:5152}: {npc:10927} живет здесь: {area:197} ({zone:1422}).",
		["Moontouched Owlbeasts"] = "Луноподобные совухи",
		["Only if a {quest:8471} dropped for you: {npc:11558} waits at the {zone:1448} entrance of {area:1769}, and speaks to you only at Neutral with the Timbermaw."] = "Только если у вас выпал предмет {quest:8471}: {npc:11558} ждет у входа ({area:1769}) со стороны края {zone:1448} и говорит с вами только при нейтральном отношении Древобрюхов.",
		["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "Карликовые чумные псы и чумные нетопыри бродят по холмам к северу от места {area:2260}, среди них ползают личинки-падальщики; продвигайтесь на север к месту {area:2627}.",
		["Ride back south to {area:272} and fly to {area:2268}."] = "Езжайте обратно на юг сюда: {area:272} и летите сюда: {area:2268}.",
		["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Pull them one at a time."] = "Езжайте на восток сюда: {area:2255} и дальше на север; луноподобные совухи бродят по южным склонам ({area:2241}). Выманивайте по одному.",
		["Ride north up the road from {area:272}. {npc:10927}'s house stands by the road at {area:197}, and {npc:10936}'s monument is in the graveyard behind it."] = "Езжайте на север по дороге от места {area:272}. Дом NPC {npc:10927} стоит у дороги ({area:197}), а памятник ({npc:10936}) – на кладбище за ним.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Езжайте на северо-запад в Андорал. {npc:10667} ждет в разрушенной таверне в западной части города; скелеты внутри – 54-57-го уровня, так что держитесь краев.",
		["Ride south from the lodge to {area:2264}, on the road. {item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith {quest:5211} in your log (from {npc:11063} at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the {item:15447}."] = "Езжайте на юг от дома по дороге сюда: {area:2264}. {item:15447} портится за десять минут: быстро убивайте воинов Плети в городе и сразу перетрите семь кусков предметом {item:15454}.\nОсторожно: незримые слуги зовут на помощь в радиусе 25 м, когда их здоровье падает до 40%. Вне боя они также становятся невидимыми ({spell:10228}). Если зов о помощи прозвучит в городе, в бой может вступить много противников. Сражайтесь на окраинах, чтобы снизить риск.\nЕсли в журнале есть задание {quest:5211} (от {npc:11063} в начале этого руководства), воины Плети вокруг города оставляют духов Дарроушира: поговорите с каждым, чтобы освободить его. Освободите их до того, как возьметесь за {item:15447}.",
		["Ride west to the {area:2260}."] = "Езжайте на запад сюда: {area:2260}.",
		["Scare {npc:7583} with {item:12928}"] = "Напугайте {npc:7583} с помощью предмета {item:12928}",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "Летопись лежит среди заплесневелых фолиантов в ратуше Андорала; открывайте их, пока не найдете нужный.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "Голова куклы и две ее половинки лежат в домах вокруг NPC {npc:10926}; соедините их в сумке.",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "Перевал из Ун'Горо выходит сюда: {area:3077} – кладбище на северо-востоке края {zone:1451}. {npc:13220} стоит среди могил.",
		["To {area:197}"] = "Сюда: {area:197}",
		["Upstairs"] = "Наверху",
		["Use {item:12928} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "Используйте игрушку {item:12928} на гоблинше {npc:7583} ({area:976}). {npc:10977} и {npc:10978} – позже по маршруту.",
		["Zaeldarr lurks just west of {area:2262}."] = "Заэлдарр прячется чуть к западу от места {area:2262}.",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["a message for {npc:11063} at {area:2268}"] = "послание для NPC {npc:11063} ({area:2268})",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "Призрак {npc:10926} стоит в руинах ({area:2262}) на юго-западе.",
		["{npc:10927}, upstairs"] = "{npc:10927}, наверху",
		["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner."] = "Призрак {npc:11140} стоит у хижины ({area:2627}) в северо-западном углу.",
		["{npc:15193}'s champion holds the {area:2260} farmhouse, north of the {area:2261}."] = "Защитник ({npc:15193}) занимает дом на ферме ({area:2260}) к северу от места {area:2261}.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} ({area:1639}); {npc:246344}",
		["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771} стоит лагерем у дороги к месту {area:1336}, к югу от места {area:976}.",
		["{quest:3914} goes back to {npc:8737} in Un'Goro: keep it."] = "{quest:3914} сдается {npc:8737}у в Ун'Горо: сохраните задание.",
		["{quest:5168}'s items lie in the later Plaguelands zones: keep it."] = "Предметы для задания {quest:5168} – в Чумных землях, позже: сохраните его.",
		["{quest:5211}'s spirits come with the {area:2264} stop later in this guide: keep it."] = "Духи для задания {quest:5211} появятся при остановке здесь: {area:2264}, позже в этом руководстве: сохраните задание.",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["A torn scroll lies at the entrance of the {area:2261}, the crypt south of the {area:2260}."] = "Рваный свиток лежит у входа сюда: {area:2261} – склеп к югу от места {area:2260}.",
		["Andorhal watchtowers and silos"] = "Сторожевые башни и силосы Андорала",
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "Вернитесь в Южный Ветер и поднимитесь на башню. Если потревожить улей наверху, вылезут душители из улья Аши; у одного из них – {item:17346}.",
		["Back to {area:3425}"] = "Назад: {area:3425}",
		["Below ground"] = "Под землей",
		["Class trainer"] = "Учитель классовых навыков",
		["Dredge Crushers and Pincers"] = "Земляные сокрушители и клешневики",
		["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "Землечерпы, камнехвостые скорпиды и песчаные пауки-быстроноги бродят по пескам чуть к северу от крепости.",
		["East along the road, {npc:11077} guards the cauldron at {area:200}."] = "На восток по дороге: {npc:11077} охраняет котел ({area:200}).",
		["Escort {npc:9999}"] = "Сопроводите NPC {npc:9999}",
		["Flayers and Rock Stalkers"] = "Живодеры и скальные пауки-скакуны",
		["Fly to {area:976}. Still carrying {quest:2741}? The machine stands in the middle of town."] = "Летите сюда: {area:976}. Задание {quest:2741} еще при вас? Машина стоит в центре города.",
		["Hameya's mound"] = "Курган Хамейи",
		["Hameya's scroll"] = "Свиток Хамейи",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "Двигайтесь на север вдоль западных дюн; земляные сокрушители и камнехвостые клешневики встречаются отсюда до крепости.",
		["Inside"] = "Внутри",
		["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "Сохраните приманку: {npc:9684} – 56-го уровня, а второй круг проходит мимо его логова.",
		["Keep {quest:3942}: {npc:9116} is at the {area:2479}, on the next guide's way through {zone:1448}."] = "Сохраните задание {quest:3942}: {npc:9116} – здесь: {area:2479}, по пути следующего руководства через край {zone:1448}.",
		["Mark {npc:10902} with the {item:12815}"] = "Отметьте предметом {item:12815}: {npc:10902}",
		["Mark {npc:10903} with the {item:12815}"] = "Отметьте предметом {item:12815}: {npc:10903}",
		["Mark {npc:10904} with the {item:12815}"] = "Отметьте предметом {item:12815}: {npc:10904}",
		["Mark {npc:10905} with the {item:12815}"] = "Отметьте предметом {item:12815}: {npc:10905}",
		["Radley and Durgen"] = "Рэдли и Дурген",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "Езжайте на восток сюда: {area:537}, поднимитесь и используйте предмет {npc:10541} у лавового жерла у вершины, затем возвращайтесь на запад к персонажу {npc:10302}.",
		["Ride east to {npc:1855}'s hut by the {area:2619} and hear him out."] = "Езжайте на восток к хижине {npc:1855} у места {area:2619} и выслушайте его.",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "Езжайте на северо-восток сюда: {area:3077}; из края {zone:1451} вы уйдете через перевал рядом.",
		["Ride north-east to {area:3447}."] = "Езжайте на северо-восток сюда: {area:3447}.",
		["Ride north-west to {npc:1855}'s hut."] = "Езжайте на северо-запад к хижине {npc:1855}.",
		["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "Езжайте на юг в Андорал. {npc:10667} ждет в разрушенной таверне в западной части города. Встаньте в дверях каждой из четырех башен с предметом {item:12815}, чтобы отметить ее; держитесь окраин города. Используйте предмет {item:12627} у силосов в центре города, чтобы выманить временных паразитов.",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "Езжайте на юго-восток сюда: {area:3447}, под скалами Ун'Горо.",
		["Ride south-west to {npc:10667} in Andorhal."] = "Езжайте на юго-запад к персонажу {npc:10667} в Андорал.",
		["Ride west to the Horde camp north of {area:2744}."] = "Езжайте на запад к лагерю Орды к северу от места {area:2744}.",
		["Ride west to the walled hold in the middle of the desert. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Езжайте на запад к обнесенной стеной крепости в центре пустыни. {npc:15189} стоит наверху в своем здании: поднимитесь внутри, Стрелка не различает этажи.",
		["Scourge Champions"] = "Воители Плети",
		["Scourge Champions roam the {area:2270}, north of the chapel. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants."] = "Воители Плети бродят здесь: {area:2270}, к северу от часовни. Проведите предметом {npc:11063} ({item:13156}) над каждым убитым: нужны черепа, которые отзываются.",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "Гейзеры силитиста извергаются по всей южной пустыне. Войдите в оставленный гейзером силитист и отнесите его к экстрактору Орды в лагере Кирики; в бою или верхом вы его теряете.",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "Камнехвостые живодеры и скальные пауки-скакуны бродят по дюнам к юго-западу от лагеря Кирики.",
		["The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too."] = "Светящиеся осколки табличек лежат вокруг лагеря Сумеречного Молота на дальнем северо-западе; они падают и с пылевихрей и пустынных грохотунов.",
		["The libram lies further north, on the way to {area:190}."] = "Либрам лежит дальше к северу, по пути к месту {area:190}.",
		["The lockboxes sit in Andorhal's ruined houses around {npc:10667}'s inn. Careful: Ghouls and skeletons usually stand next to the boxes and attack when you come close. Searing ghouls also hurt anyone nearby and will break stealth."] = "Сундучки стоят в разрушенных домах Андорала вокруг таверны, где находится {npc:10667}. Осторожно: рядом с сундучками обычно стоят вурдалаки и скелеты, они нападают, когда вы подходите. Обжигающие вурдалаки также ранят всех поблизости и выводят из незаметности.",
		["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "Сумка лежит в горах на дальнем юге, за Лагерем Бронзоборода. Рядом патрулирует Смертехват, элитный скорпид: хватайте сумку, пока его нет.",
		["The shield lies at {area:201}, south of {npc:1855}'s hut."] = "Щит лежит здесь: {area:201}, к югу от хижины {npc:1855}.",
		["The spare texts from the cultists"] = "Лишние тексты с культистов",
		["Twilight Vanguard"] = "Авангард Сумеречного Молота",
		["Upstairs"] = "Наверху",
		["Use {npc:10980} on {npc:10977}"] = "Используйте игрушку {npc:10980} на персонаже {npc:10977}",
		["{item:20377} from {npc:11739}, 130 yd south-west"] = "{item:20377} – с NPC {npc:11739}, в 130 м к юго-западу",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302} отправляет вас к персонажу {npc:9298} ({zone:1452}): сохраните задание.",
		["{npc:10302} the goblin sits at {area:543}, just east of the pylon."] = "Гоблин {npc:10302} сидит здесь: {area:543}, чуть к востоку от пилона.",
		["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "Битва за Дарроушир ({npc:10667}) заканчивается боем с элитой. Пропустите.",
		["{npc:15189} and {npc:15190} stand upstairs in their building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} и {npc:15190} стоят наверху в своем здании: поднимитесь внутри, Стрелка не различает этажи.",
		["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} стоит наверху в своем здании: поднимитесь внутри, Стрелка не различает этажи.",
		["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190} стоит наверху в своем здании: поднимитесь внутри, Стрелка не различает этажи.",
		["{npc:15200} holds the camp in the west."] = "{npc:15200} занимает лагерь на западе.",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}, в западной части крепости",
		["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "Теперь {npc:9619} просит шкуру ({npc:9622}) из северо-восточной пещеры: пропустите.",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "Логово ({npc:9684}) – чуть к югу от пилона. Используйте там приманку {npc:9619}; {npc:9684} – 56-го уровня и бьет сильно, начинайте с полным здоровьем.",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999} сидит на хребте, заблудившийся и обессиленный.",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Any Winterfall furbolg can carry the beads; the camps just south of {npc:11556} are the closest."] = "Бусы может нести любой фурболг Зимней Спячки; ближайшие лагеря – чуть к югу от персонажа {npc:11556}.",
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "Обратно в туннель Древобрюхов, выход: {zone:1452}; {npc:9298} стоит лагерем у горячих источников сразу снаружи.",
		["Back south to the Sanctuary, a short ride."] = "Обратно на юг к Святилищу, недалеко.",
		["Below ground"] = "Под землей",
		["Class trainer"] = "Учитель классовых навыков",
		["Corrupted Soul Shards from the cultists, {quest:5887}"] = "Оскверненные осколки души с культистов, «{quest:5887}»",
		["Dungeon instead of grinding"] = "Подземелье вместо гринда",
		["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "Летите в {area:431} и езжайте на северо-запад по дороге из зоны {zone:1440} в {zone:1448}. {area:2479} — лагерь друидов сразу за границей.",
		["From Krakle in Un'Goro"] = "От Кракла из Ун'Горо",
		["Frostfire Winterfall camp"] = "Лагерь Зимней Спячки у источников",
		["Grind to 60"] = "Гринд до 60",
		["In the {object:172961}."] = "Ориентир: {object:172961}.",
		["In {zone:1454}: fly from {area:2255}"] = "В городе {zone:1454}: летите из места {area:2255}",
		["In {zone:1456}: fly from {area:2255}"] = "В городе {zone:1456}: летите из места {area:2255}",
		["On the way back south to {npc:10922}, {npc:9529} takes the shards on the west side of the Sanctuary."] = "По пути обратно на юг к {npc:10922} отдайте осколки: {npc:9529} стоит на западной стороне Святилища.",
		["Optional. Running {area:2279}, {area:2057}, Lower Blackrock Spire or {area:1584} with a group instead of grinding gets you there faster."] = "Необязательно. Прохождение подземелий {area:2279}, {area:2057}, нижняя часть пика Черной горы или {area:1584} в группе вместо гринда быстрее.",
		["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "Необязательно: с группой подземелье 55-60 заменяет гринд ниже.",
		["Ride back west to {area:2246}."] = "Возвращайтесь на запад сюда: {area:2246}.",
		["Ride east along the road to {area:2255}."] = "Езжайте на восток по дороге в {area:2255}.",
		["Ride east, then south down {area:2249}. The Frostmaul giants there are elite level 59: keep to the middle and keep moving. The strange source is at the mouth of {area:2256}, at the south end."] = "Езжайте на восток, затем на юг через место {area:2249}. Великаны ледяного молота там – элита 59-го уровня: держитесь середины и не останавливайтесь. Странный источник – у входа сюда: {area:2256}, в южном конце.",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "Езжайте на север по дороге мимо места {area:1763} в {area:1997}.",
		["South to the Sanctuary once more."] = "Еще раз на юг к Святилищу.",
		["The quests run out here. Rabid Shardtooths prowl {area:2249} in southern {zone:1452}, south of the road from {area:2255}."] = "Задания здесь заканчиваются. Бешеные щербозубы рыщут здесь: {area:2249}, юг зоны {zone:1452}, к югу от дороги из места {area:2255}.",
		["The {area:2479}"] = "Место: {area:2479}",
		["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "Через туннель Древобрюхов в {zone:1450}. {npc:11939} читает в доме здесь: {area:2361}.",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["grind on {npc:7446} at {area:2249}, {zone:1452}"] = "гринд: {npc:7446}, {area:2249}, {zone:1452}",
		["{npc:10306}'s next {quest:4741} would bring you back here from {zone:1452}. Skip it."] = "Следующее задание {npc:10306} «{quest:4741}» вернуло бы вас сюда из зоны {zone:1452}. Пропустите.",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "Заданию {npc:11801} «Осколки сквернита» нужно подземелье {area:2577}. Пропустите.",
		["{npc:9116}'s Silver Heart needs an {item:11173} from northern {zone:1448} and a ride back here. Skip it."] = "Заданию {npc:9116} «Серебряное сердце» нужен {item:11173} с севера зоны {zone:1448} и поездка обратно сюда. Пропустите.",
		["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "Затем {npc:9298} отправляет вас за NPC {npc:10738}, элитой в его пещере. Пропустите.",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/orc/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Бронескорпы ползают по равнинам к западу от места {area:362}. Приручите одного, затем вернитесь к персонажу {npc:3171}.",
		["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "Вернитесь на северо-запад в {area:362}: сначала {npc:3139}, затем {npc:3147} на сторожевой башне, потом {npc:3142} и {npc:266940} по пути на восток к побережью.",
		["Back to the Den"] = "Назад к Логову",
		["Back to {area:362}."] = "Назад сюда: {area:362}.",
		["Below ground"] = "Под землей",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Культисты (Пылающий Клинок) занимают пещеры ({quest:827}); {item:4871} падает с любого. {npc:3204}, чернокнижник 14-го уровня, стоит в глубине, с него падает {item:4903}.",
		["Class trainer"] = "Учитель классовых навыков",
		["Druid trainer"] = "Учитель друидов",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Ловцы Скверны бродят по склону под пещерой, на северной стороне долины.",
		["Free {npc:275811} and see her safely out of the crag"] = "Освободите персонажа {npc:275811} и выведите ее с утеса",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "Двигайтесь на юг через острова. Идолы Лоа лежат по всем южным островам; их охраняют тролли-вудуисты и проклятые тролли, с них падают проклятые подвески. {quest:826} и клетка Миншины – на самом южном острове.",
		["Inside"] = "Внутри",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "В пещере на первой развилке идите прямо, затем направо и вдоль ручья слева до водопада: кирка светится у воды, за каменной колонной.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "В пещере держитесь правой стены по всему кругу, через ручей: {npc:3183} ждет в конце.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "Хижина Майши – к югу от ящеров. {item:4891} – у кроколисков вдоль реки ({area:814}) к западу.",
		["Prickly pears"] = "Колючие груши",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Свинобразы и разведчики занимают хижины к западу от городка; пылебеги и боевые стражи – лагеря дальше к западу.",
		["Spitelash naga"] = "Наги Бича Злобы",
		["Tame it with the {item:15908}"] = "Приручите его предметом {item:15908}",
		["The gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin.\nMakrura and surf crawlers line the beaches north-east of Sen'jin."] = "Гномские ящики с инструментами лежат среди обломков на побережье к востоку и юго-востоку от {area:362}. Идите вдоль берега на юг к Сен'джину.\nМакруры и прибойные ползуны встречаются на пляжах к северо-востоку от Сен'джина.",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "Крепость стоит на побережье к юго-востоку от места {area:362}. Топор, лук и щит налетчиков лежат на ее окраинах. {item:4870} падает с моряков и стражей бухты. {npc:3192} ждет на вершине крепости; его ключ открывает сундук рядом, в нем – {item:4881}.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Колючие груши растут среди хижин свинобразов чуть к западу от городка.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Оружие лежит вокруг Логова и тренировочной площадки; пятнистые вепри бродят по всей долине.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595} стоит здесь: {area:817}, среди культистов, с которыми вы только что бились.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Рокочущие ящерицы и бурешкуры пасутся здесь: {area:369}, у дороги на север к городу {zone:1454}; {item:6486} может упасть с любого. {npc:5810} примет ее, когда следующий гайд будет проходить мимо заставы {area:379}.\nОсторожно: Халикор, элитный противник 12-го уровня, бродит среди ящериц ({area:369}): высматривайте его, прежде чем нападать.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nFizzle holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Рокочущие ящерицы и бурешкуры пасутся здесь: {area:369}, чуть западнее и юго-западнее NPC {npc:3293}.\nПшикс удерживает лагерь клана Пылающего Клинка ({area:369}), к северо-западу от места {area:362}. Охотникам: по пути приручите вепря ({npc:3099}), используя {item:15908}.\nОсторожно: Пшикса окружают сектанты Пылающего Клинка, некоторые связаны и нападают парами, и они быстро возрождаются.\nОсторожно: Халикор, элитный противник 12-го уровня, бродит среди ящериц ({area:369}): высматривайте его, прежде чем нападать.",
		["To {zone:1454}"] = "В {zone:1454}",
		["Training weapons and boars"] = "Учебное оружие и вепри",
		["Upstairs"] = "Наверху",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nDurotar Tigers roam the isle as well as the shore south of Sen'jin, and the Taillasher eggs sit in nests on the isles and along the beach."] = "Переберитесь вброд на северный остров Эха. Там среди ящеров бродит Матриарх.\nТигры Дуротара бродят по острову, а также по берегу к югу от Сен'джина, а яйца хлыстохвостов лежат в гнездах на островах и вдоль пляжа.",
		["Wake {quest:5441} with the {item:16114}"] = "Разбудите батраков ({quest:5441}) предметом {item:16114}",
		["the {object:654925} on the ground beside her"] = "{object:654925} на земле рядом с ней",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} – к западу от Сен'джина. Три плана атаки лежат на земле среди шатров кентавров. {npc:275811} тоже в плену на утесе.",
		["{area:817}'s mouth"] = "Вход: {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, там, где вы начинаете",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809} стоит лагерем чуть к югу от места {area:362}. Сядьте у его костра (/sit) и ждите, пока не появится эффект {spell:1229451}. Если вы освоили профессию, {npc:265809} также предлагает свое задание «Основы походной жизни»: его принимает учитель этой профессии – здесь ({area:362}) или в начале следующего руководства, место: {zone:1454}.",
		["{npc:265809}'s campfire"] = "Костер: {npc:265809}",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809}: для персонажа {npc:11025}",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809}: для персонажа {npc:11046}",
		["{npc:265809}: for {npc:11066}"] = "{npc:265809}: для персонажа {npc:11066}",
		["{npc:265809}: for {npc:2855}"] = "{npc:265809}: для персонажа {npc:2855}",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809}: для персонажа {npc:3175}",
		["{npc:265809}: for {npc:3365}"] = "{npc:265809}: для персонажа {npc:3365}",
		["{npc:265809}: for {npc:3404}"] = "{npc:265809}: для персонажа {npc:3404}",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809}: для персонажа {npc:5943}",
		["{npc:265809}: for {npc:7088}"] = "{npc:265809}: для персонажа {npc:7088}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: только для зачарователей – остаток получают, распыляя проклятые подвески",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} стоит на берегу к востоку от места {area:362}. Трезубец, знамя и кинжал лежат на пляже вокруг него.",
		["{npc:3102} hooves"] = "Копыта: {npc:3102}",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, снова здесь: {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, элитный морской великан",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} стоит сразу у входа в пещеру; {npc:3159} – в глубине пещеры за ним.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} ждет внутри Логова – здания чуть к западу от персонажа {npc:10176}.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, в сторожевой башне",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, учитель воинов, у Логова",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, учитель охотников, у Логова",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, учитель разбойников, в Логове",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, учитель чернокнижников, в глубине пещеры",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, учитель шаманов, у Логова",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} лежит раненый у подножия холмов к северо-западу от Логова.",
		["{npc:3294}, by the inn"] = "{npc:3294}, у таверны",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it."] = "{npc:5875} стоит здесь: {object:172960} – каньон под объектом {object:172982}. Отдайте ему {item:6535}, затем используйте предмет {item:7464} на круге призыва рядом с ним и одолейте демона Бездны, чтобы подчинить его.",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, учитель магов, у входа в Логово",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} стоит у Логова. {area:639} – холм чуть к югу: выпейте там {item:6635}, чтобы увидеть персонажа {npc:5891}, затем отнесите предмет {item:6656} {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} и ваш {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, ориентир: {area:639}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} стоит на дороге у восточного выхода из долины.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, у костра для готовки",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} стоит лагерем на холме к западу от пляжа наг, к югу от места {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "Главные ворота ({zone:1454}) – чуть к западу от места {area:817}. {npc:5875} стоит здесь: {object:172960} – каньон под местом {object:172982}.",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sit у костра {npc:263664}, пока не получите {spell:1229451}",
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Аандерс и павшие стражи – чуть к юго-западу от башни. Заберите с тел перо Раани и фамильный перстень Песни Теней.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "Снова здесь: {quest:92529} – деревня полна призывателей бури и персонажей {npc:251662}, тайники с припасами стоят среди домов, а {npc:251966} ждет в юго-восточной части.",
		["Back to Boro in {area:16635} with the Signet."] = "Возвращайтесь с перстнем к Боро сюда: {area:16635}.",
		["Back to {area:16635}"] = "Назад: {area:16635}",
		["Back to {area:16638}"] = "Назад: {area:16638}",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "Назад к {npc:268592}. Дождитесь, пока он зажжет {npc:268762}, затем сразу несите пламя сюда: {npc:268679} (рядом с {npc:252382}, {area:16638}), пока не истек таймер.",
		["Back up from the den to {npc:257551} and {npc:251366} in the village before heading south-west to {npc:252095}: the road from her camp leads on south to Shen'dar."] = "Поднимитесь из логова назад в деревню к {npc:257551} и {npc:251366}, затем идите на юго-запад к персонажу {npc:252095}: дорога от ее лагеря ведет дальше на юг, в Шен'дар.",
		["Below ground"] = "Под землей",
		["Cast {spell:1259686} near the {object:460001}"] = "Используйте {spell:1259686} рядом: {object:460001}",
		["Class trainer"] = "Учитель классовых навыков",
		["Find {npc:258130}"] = "Найдите персонажа {npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle. {npc:251523} stands on its east side, {npc:251902} in the middle, {npc:254089} just north-west of her, {npc:263664} by the campfire on the west side. With a profession learned, {npc:263664} also offers its Camping 101: its trainer stands in the village."] = "Идите по дороге на юг сюда: {area:16624}, в центр острова. {npc:251523} стоит в восточной части, {npc:251902} – в центре, {npc:254089} – чуть к северо-западу от нее, {npc:263664} – у костра в западной части. Если вы изучили профессию, {npc:263664} также предложит соответствующее задание «Основы походной жизни»: учитель этой профессии находится в деревне.",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "Идите на север сюда: {area:16631}; {npc:257944} стоит лагерем на южной окраине.",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "Идите на юго-запад сюда: {area:17674}. {npc:252155} – на вершине; {item:254871} лежит рядом.",
		["Heal the injured druids in the Nightfang Den"] = "Вылечите раненых друидов в логове",
		["Hungry Bandits"] = "Голодные бандиты",
		["Listen to {npc:252448}'s story"] = "Выслушайте историю: {npc:252448}",
		["Listen to {npc:256083}"] = "Выслушайте персонажа {npc:256083}",
		["Northern {zone:1412}"] = "Север: {zone:1412}",
		["On the road south-east to {area:16638}, {npc:273017} watches the {quest:98512} just north of him."] = "На дороге на юго-восток к месту {area:16638} {npc:273017} следит за целью задания {quest:98512} чуть к северу от себя.",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "Назойливые щетинистые осы и {npc:250873} бродят по роще чуть к юго-востоку от деревни.",
		["Raw Windstones"] = "Ветрокаменное сырье",
		["Ripe Stormapples"] = "Спелые штормояблоки",
		["Skyhoppers"] = "Небопрыги",
		["Skyhoppers hop about the fields just west of Valennia."] = "Небопрыги скачут по полям чуть к западу от Валеннии.",
		["Spread the {item:278078} off {area:1641}"] = "Развейте предмет {item:278078} с обрыва ({area:1641})",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "Буреяблоки и пыльца бабочек-порхательниц лежат по всему саду; на него нападают голодные бандиты. Буреноги пасутся в полях к востоку. Сломанный конструкт парит у северного края сада.",
		["Tell {npc:252800} you're ready"] = "Скажите NPC {npc:252800}, что вы готовы",
		["The Al'Aketh camp"] = "Лагерь Ал'акет",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "Ветрокаменное сырье – синие кристаллы на склонах вокруг деревни.",
		["The hermit lives at {area:16625}'s west shore."] = "Отшельник живет на западном берегу ({area:16625}).",
		["The orchard"] = "Сад",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "Королева парит в юго-восточной части рощи, по пути обратно от монолитов.",
		["The standing stones"] = "Монолиты",
		["The turncoat"] = "Предатель",
		["The turncoat's house is in the {area:16626} north-west of {area:16638}, just north of {npc:273017}."] = "Дом предателя – здесь: {area:16626}, к северо-западу от места {area:16638}, чуть к северу от персонажа {npc:273017}.",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "{area:16629} – к северу от места {area:16638}. Пробейтесь через стражу к персонажу {npc:253576} в восточной части.",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {object:148418}"] = "{object:148418}",
		["To {zone:1454}"] = "В {zone:1454}",
		["Upstairs"] = "Наверху",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Используйте предмет {item:278078} у церемониального коврика и курильницы на южном обрыве ({area:1641}).",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "Вы покидаете остров навсегда. {npc:259119} ждет у места посадки.",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "Вы просыпаетесь здесь: {area:16635}, на севере острова. {npc:251362} стоит у тропы, {npc:251361} – в центре деревни.",
		["search the dead cultist in the house"] = "обыщите мертвого культиста в доме",
		["search the wardrobe"] = "обыщите шкаф",
		["talk to {npc:251684}"] = "поговорите с персонажем {npc:251684}",
		["talk to {npc:251902}"] = "поговорите с персонажем {npc:251902}",
		["talk to {npc:251968}"] = "поговорите с персонажем {npc:251968}",
		["talk to {npc:252155}"] = "поговорите с персонажем {npc:252155}",
		["talk to {npc:252476}"] = "поговорите с персонажем {npc:252476}",
		["talk to {npc:253844}"] = "поговорите с персонажем {npc:253844}",
		["talk to {npc:257554}"] = "поговорите с персонажем {npc:257554}",
		["the bounty board"] = "доска объявлений",
		["{area:16624} turn-ins"] = "Сдача заданий: {area:16624}",
		["{area:16635} turn-ins"] = "Сдача заданий: {area:16635}",
		["{area:16663} is west of {area:16638} along the coast road."] = "{area:16663} – к западу от места {area:16638} по прибрежной дороге.",
		["{item:257128} cones grow south of the hermit; the Wind Hollows drift east of the lake and also drop the Wind Hollow Essences for {npc:254344}'s {quest:93736}. The refugees' belongings lie along the north shore of {area:16625}; {npc:259013} is at its north-west end."] = "Шишки ({item:257128}) растут к югу от отшельника; ветряные мертвени парят к востоку от озера, с них же падают эссенции ветряных мертвеней для задания {quest:93736} ({npc:254344}). Вещи беженцев лежат вдоль северного берега ({area:16625}); {npc:259013} – в его северо-западной части.",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "{item:265105} растет вокруг лагеря {npc:257944}, над ним летают визгуны. {item:265141} – в лагере Ал'акет к востоку от нее.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, у персонажа {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, у персонажа {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, у персонажа {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, у персонажа {npc:3027}",
		["{npc:249363} stands at the {area:17678}, east of the village. {npc:251143} and Al'Aketh Converts gather just north of her. The {object:460001} is just north-east of her: cast your {spell:1259686} racial ability next to it."] = "{npc:249363} стоит здесь: {area:17678}, к востоку от деревни. {npc:251143} и ал'акетские новообращенные собираются чуть к северу от нее. {object:460001} – чуть к северо-востоку: используйте рядом расовую способность {spell:1259686}.",
		["{npc:251361}'s errands"] = "Поручения {npc:251361}",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: записка от вашего учителя",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361}: осмотрите предмет {item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: прочтите предмет {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, учитель друидов, на нижнем ярусе дерева за {npc:251361}",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}: {npc:5873} и ваш {item:5175}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, в сторожевой башне",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, в сторожевой башне",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382}: {npc:2523}, ваш {item:5176} и {item:263412}",
		["{npc:252448} and {npc:256083}"] = "{npc:252448} и {npc:256083}",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}, {npc:258130} и {npc:258134} – в лагере культа к востоку от {npc:257944}. {npc:254151} стоит на окраине. С Хаалиена также падает {quest:94490}: прочтите, чтобы начать следующее задание. Для задания {quest:94489} войдите в логово, вылечите 7 раненых друидов и найдите {npc:258130}.",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} прячется к югу от деревни среди когтей прайда. {npc:254589} – элита: лучше собрать группу.",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083} стоит здесь: {area:16626}, чуть к северо-западу от города.",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247} ждет на дороге к северу от места {area:16638}, в сторону места {area:16629}.",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{item:263993} – у персонажа {npc:257196} в западной части святилища.",
		["{npc:257944} again"] = "Снова {npc:257944}",
		["{npc:257944}, last time"] = "{npc:257944}, в последний раз",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "{npc:259118}, у места посадки: для персонажа {npc:3033} ({zone:1456})",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} просит тауренские благовония: купите четыре части у {npc:3014} (травница), {npc:3012} (товары для зачарования), персонажа {npc:3005} (товары для кожевников) и {npc:3027} (товары для кулинарии), затем соедините их в предмет {item:278078}.",
		["{npc:5543} stands in the {area:2197}, the cave under {area:1640}: go down inside, the arrow cannot tell the floors apart."] = "{npc:5543} стоит здесь: {area:2197} – пещера под местом {area:1640}: спуститесь внутрь, стрелка не различает ярусы.",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529} – к югу от Шен'дара. {npc:257065} встретит вас на окраине; обыщите шкаф в доме за ним.",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["/sit by Kaga's campfire until you get {spell:1229451}"] = "/sit у костра Каги, пока не получите {spell:1229451}",
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "Назад на восток сюда: {area:358}: шаманы из племени Дыбогривов стоят там среди свинобразов.",
		["Back north-west up to {area:221}."] = "Назад на северо-запад, наверх сюда: {area:221}.",
		["Back south-east to the {area:396}."] = "Назад на юго-восток сюда: {area:396}.",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "Назад к персонажу {npc:5888} в лагерь. {npc:5891} ждет на плато к востоку от лагеря: выпейте там {item:6635}, чтобы увидеть его, затем отнесите предмет {item:6656} провидцу.",
		["Back west to the camp."] = "Назад на запад в лагерь.",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "К северу от святилища пасутся боевые вепри; дыбогривые свинобразы занимают ущелье к северо-востоку. {npc:8554} стоит в его восточной части, а {object:3076} лежит на земле в лагере.",
		["Below ground"] = "Под землей",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the north-western woods. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Используйте {spell:18960}. {npc:11802} – здесь: {area:2361}; {quest:5930} – в северо-западных лесах. {npc:11802} стоит наверху в своем здании: поднимитесь внутри, Стрелка не различает этажи.",
		["Class trainer"] = "Учитель классовых навыков",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "Идите на северо-запад мимо города {zone:1456} сюда: {area:398}, на дальнем севере края {zone:1412}.",
		["Cross to {area:1639}."] = "Перейдите сюда: {area:1639}.",
		["Follow the road north out of {area:220}. {npc:265810} waits on the road just south of {area:222}; /sit by her campfire until you get {spell:1229451}. With a profession learned, Kaga also offers its Camping 101, which its trainer takes: in Bloodhoof or on the {zone:1456} stop."] = "Идите по дороге на север от места {area:220}. {npc:265810} ждет на дороге чуть к югу от места {area:222}; /sit у ее костра, пока не получите {spell:1229451}. Если у вас изучена профессия, Кага также предлагает свое задание «Походы для начинающих», которое принимает ваш учитель профессии: в Деревне Кровавого Копыта или во время остановки в городе {zone:1456}.",
		["Galak centaurs"] = "Кентавры из племени Галак",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "Идите на север сюда: {area:225}, к востоку от города {zone:1456}. {npc:3233} стоит у подножия скал; злоумышленники из племени Дыбогривов роются на кладбище, а {npc:2994} ждет наверху.",
		["Inside"] = "Внутри",
		["Plainstriders roam the mesa all around the camp: take their meat and feathers on the way back to {npc:2980}."] = "Равнинные долгоноги бродят по плато вокруг лагеря: соберите их мясо и перья на обратном пути к {npc:2980}.",
		["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "Могучие волки прерий бродят среди волков на равнинах вокруг NPC {npc:275789} и лагеря племени Галак к востоку.",
		["Prairie Wolves and Adult Plainstriders roam the plains around the village."] = "Волки прерий и взрослые равнинные долгоноги бродят по равнинам вокруг деревни.",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Поднимитесь на подъемнике на плато. {npc:2995} присматривает за ветрокрылами на центральном холме; {npc:3057} стоит там в большом шатре.",
		["Spread the {item:278078} off {area:1641}"] = "Развейте предмет {item:278078} с обрыва ({area:1641})",
		["Tame it with the {item:15908}"] = "Приручите его предметом {item:15908}",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "Гноллы из стаи Бледногривов занимают место {area:818} к югу от раскопок и к западу от Деревни Кровавого Копыта. {npc:272203} в плену в их лагере: выведите его.",
		["The Seer's tent stands at the foot of the cougars' hills."] = "Шатер провидца стоит у подножия холмов, где водятся пумы.",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "Гарпии из стаи Ярости Ветра занимают место {area:819} к северу и западу от колодца.",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "Кирки геолога – у дворфов ({area:404}). Разбейте их в кузнице дворфов на раскопках.",
		["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine."] = "Гоблины работают в шахте на холмах к северо-востоку от колодца. {quest:765} стоит в глубине шахты; его {item:281031} начинают задание {quest:98424}, а остальные страницы лежат в шахте.",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "Благовония сгорают за десять минут: бегите прямо на восток вдоль южных холмов сюда: {object:660739}.",
		["The shrine of An'she and Mu'sha"] = "Святилище Ан'ше и Му'ши",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "Камень стоит на перевале из края {zone:1412}, по пути на восток. Используйте там предмет {item:15710} и одолейте Лунокогтя.",
		["The well lies north of the village. Adult Plainstriders graze around it: they drop the {item:287505} for Kyle."] = "Колодец – к северу от деревни. Вокруг него пасутся взрослые равнинные долгоноги: с них падает {item:287505} для Кайла.",
		["The well lies south-east of the village. {npc:2988} camps beside it, and {quest:99079} stands on the {area:821} a little east."] = "Колодец – к юго-востоку от деревни. {npc:2988} стоит лагерем рядом с ним, а {quest:99079} – чуть восточнее ({area:821}).",
		["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "Разбитый караван лежит к северо-западу от кентавров, к востоку от дороги к городу {zone:1456}.",
		["The {object:177525}"] = "{object:177525}",
		["To {zone:1454}"] = "В {zone:1454}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Используйте предмет {item:278078} у церемониального коврика и курильницы на южном обрыве ({area:1641}).",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "Вы начинаете на плато ({area:221}). {npc:2980} и вождь стоят у большого шатра в центре.",
		["{area:221}: kill these as you meet them"] = "{area:221}: убивайте их по пути",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, у персонажа {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, у персонажа {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, у персонажа {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, у персонажа {npc:3027}",
		["{item:4703}, at the digsite forge"] = "{item:4703} – у кузницы на раскопках",
		["{item:5203}: Flatland Prowlers roam the plains around {area:225}"] = "{item:5203}: хищники плоскогорья бродят по равнинам вокруг места {area:225}",
		["{npc:10378}, beside {npc:3418}"] = "{npc:10378} – рядом с NPC {npc:3418}",
		["{npc:265810}: for {npc:10278}"] = "{npc:265810}: для персонажа {npc:10278}",
		["{npc:265810}: for {npc:11047}"] = "{npc:265810}: для персонажа {npc:11047}",
		["{npc:265810}: for {npc:11051}"] = "{npc:265810}: для персонажа {npc:11051}",
		["{npc:265810}: for {npc:11071}"] = "{npc:265810}: для персонажа {npc:11071}",
		["{npc:265810}: for {npc:3001}"] = "{npc:265810}: для персонажа {npc:3001}",
		["{npc:265810}: for {npc:3013}"] = "{npc:265810}: для персонажа {npc:3013}",
		["{npc:265810}: for {npc:3069}"] = "{npc:265810}: для персонажа {npc:3069}",
		["{npc:265810}: for {npc:5938}"] = "{npc:265810}: для персонажа {npc:5938}",
		["{npc:265810}: for {npc:5939}"] = "{npc:265810}: для персонажа {npc:5939}",
		["{npc:265810}: for {npc:6290}"] = "{npc:265810}: для персонажа {npc:6290}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} просит тауренские благовония: купите четыре части у {npc:3014} (травница), {npc:3012} (товары для зачарования), персонажа {npc:3005} (товары для кожевников) и {npc:3027} (товары для кулинарии), затем соедините их в предмет {item:278078}.",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182} стоит на северной окраине деревни. Кайлу нужен предмет {item:287505} с равнинных долгоногов.",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}, на северной окраине деревни",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}, для Хамуула ({zone:1456})",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984} стоит на краю места {area:404}, к югу от колодца.",
		["{npc:2987}, beside {npc:269068}"] = "{npc:2987}, рядом с {npc:269068}",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991} сидит у шатра на восточном краю лагеря; {object:2907} стоит рядом с ней.",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}, для {npc:3057} ({zone:1456})",
		["{npc:3060}, the druid trainer beside him"] = "{npc:3060}, учитель друидов, рядом с ним",
		["{npc:3061}, the hunter trainer"] = "{npc:3061}, учитель охотников",
		["{npc:3062}, the shaman trainer in camp"] = "{npc:3062}, учитель шаманов, в лагере",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "Задание ({npc:3063}): одолейте трех воинов-учеников (или игроков на дуэли) рядом с ним.",
		["{npc:3069}, beside {npc:3067}: {quest:97934}"] = "{npc:3069}, рядом с {npc:3067}: {quest:97934}",
		["{npc:3418} stands at {area:378}, where the road from {zone:1412} meets the {area:458} north to the Crossroads."] = "{npc:3418} стоит здесь: {area:378} – там, где дорога из края {zone:1412} выходит на тракт {area:458}, ведущий на север к Перекрестку.",
		["{npc:3418}: for {npc:3429} at the Crossroads"] = "{npc:3418}: для персонажа {npc:3429} на Перекрестке",
		["{npc:3429}, by the wind rider tower"] = "{npc:3429}, у башни ветрокрылов",
		["{npc:3615}, the wind rider master"] = "{npc:3615}, распорядитель полетов",
		["{npc:5543} stands in the {area:2197}, the cave under {area:1640}: go down inside, the arrow cannot tell the floors apart."] = "{npc:5543} стоит здесь: {area:2197} – пещера под {area:1640}. Спуститесь внутрь: Стрелка не различает этажи.",
		["{npc:5888} stands in {area:221}. {quest:1516} needs level 4, which you reach with the turn-ins here."] = "{npc:5888} стоит здесь: {area:221}. Для задания {quest:1516} нужен 4-й уровень – вы получите его, сдав задания здесь.",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}: {npc:5873} и ваш {item:5175}",
		["{npc:6290}, beside {npc:3067}: {quest:97936}"] = "{npc:6290}, рядом с {npc:3067}: {quest:97936}",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, then hunt the cougars south through the hills towards the Seer's tent at their foot."] = "{npc:6775} стоит в западной части лагеря, у северо-западного угла холмов, где бродят горные пумы: возьмите его задание, затем охотьтесь на пум, двигаясь на юг по холмам к шатру провидца у их подножия.",
		["{object:2910}, 170 yd east"] = "{object:2910}, 170 ярдов к востоку",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "{quest:96130}, волк-одиночка, бродит по равнинам к западу от деревни. Охотники прерий и пумы плоскогорья бродят по равнинам к северу и западу от нее.",
} end)()
t.guides["forever/horde/troll/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Бронескорпы ползают по равнинам к западу от места {area:362}. Приручите одного, затем вернитесь к персонажу {npc:3171}.",
		["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "Вернитесь на северо-запад в {area:362}: сначала {npc:3139}, затем {npc:3147} в сторожевой башне, затем {npc:3142} и {npc:266940} по пути на восток к берегу.",
		["Back to the Den"] = "Назад к Логову",
		["Back to {area:362}."] = "Назад сюда: {area:362}.",
		["Below ground"] = "Под землей",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Культисты (Пылающий Клинок) занимают пещеры ({quest:827}); {item:4871} падает с любого. {npc:3204}, чернокнижник 14-го уровня, стоит в глубине, с него падает {item:4903}.",
		["Class trainer"] = "Учитель классовых навыков",
		["Druid trainer"] = "Учитель друидов",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Ловцы Скверны бродят по склону под пещерой, на северной стороне долины.",
		["Follow the road east out of the valley to {area:367} on the coast."] = "Идите по дороге на восток из долины сюда: {area:367}, на побережье.",
		["Free {npc:275811} and see her safely out of the crag"] = "Освободите персонажа {npc:275811} и выведите ее с утеса",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle.\nWade back west to the shore south of Sen'jin when the isles are done."] = "Идите на юг через острова. Идолы лоа лежат по всем южным островам; их охраняют тролли-вудуисты и проклятые тролли, с которых падают проклятые подвески. {quest:826} и клетка Миншины – на самом южном острове.\nЗакончив с островами, вернитесь вброд на запад к берегу к югу от Сен'джина.",
		["Heal and fortify {npc:12430}"] = "Исцелите персонажа {npc:12430} и наложите на нее стойкость",
		["Inside"] = "Внутри",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "В пещере на первой развилке идите прямо, затем направо и вдоль ручья слева до водопада: кирка светится у воды, за каменной колонной.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "В пещере держитесь правой стены по всему кругу, через ручей: {npc:3183} ждет в конце.",
		["Makrura and surf crawlers line the beaches north-east of Sen'jin; the Taillasher eggs sit in nests along the beach.\nThe gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin."] = "Макруры и прибрежные ползуны усеивают пляжи к северо-востоку от Сен'джина; яйца хлестохвостов лежат в гнездах вдоль пляжа.\nГномские ящики с инструментами лежат среди обломков на берегу к востоку и юго-востоку от {area:362}. Идите вдоль берега на юг к Сен'джину.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "Хижина Майши – к югу от ящеров. {item:4891} – у кроколисков вдоль реки ({area:814}) к западу.",
		["Prickly pears"] = "Колючие груши",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Свинобразы и разведчики занимают хижины к западу от городка; пылебеги и боевые стражи – лагеря дальше к западу.",
		["Spitelash naga"] = "Наги Бича Злобы",
		["Tame it with the {item:15908}"] = "Приручите его предметом {item:15908}",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "Крепость стоит на побережье к юго-востоку от места {area:362}. Топор, лук и щит налетчиков лежат на ее окраинах. {item:4870} падает с моряков и стражей бухты. {npc:3192} ждет на вершине крепости; его ключ открывает сундук рядом, в нем – {item:4881}.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Колючие груши растут среди хижин свинобразов чуть к западу от городка.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Оружие лежит вокруг Логова и тренировочной площадки; пятнистые вепри бродят по всей долине.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595} стоит здесь: {area:817}, среди культистов, с которыми вы только что бились.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Рокочущие ящерицы и бурешкуры пасутся здесь: {area:369}, у дороги на север к городу {zone:1454}; {item:6486} может упасть с любого. {npc:5810} примет ее, когда следующий гайд будет проходить мимо заставы {area:379}.\nОсторожно: Халикор, элитный противник 12-го уровня, бродит среди ящериц ({area:369}): высматривайте его, прежде чем нападать.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nFizzle holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Рокочущие ящерицы и бурешкуры пасутся здесь: {area:369}, чуть западнее и юго-западнее NPC {npc:3293}.\nПшикс удерживает лагерь клана Пылающего Клинка ({area:369}), к северо-западу от места {area:362}. Охотникам: по пути приручите вепря ({npc:3099}), используя {item:15908}.\nОсторожно: Пшикса окружают сектанты Пылающего Клинка, некоторые связаны и нападают парами, и они быстро возрождаются.\nОсторожно: Халикор, элитный противник 12-го уровня, бродит среди ящериц ({area:369}): высматривайте его, прежде чем нападать.",
		["To {zone:1454}"] = "В {zone:1454}",
		["Training weapons and boars"] = "Учебное оружие и вепри",
		["Upstairs"] = "Наверху",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there; Durotar Tigers roam the isle and the shore south of Sen'jin."] = "Перейдите вброд на северный из Островов Эха. Там среди ящеров бродит матриарх; дуротарские тигры бродят по острову и по берегу к югу от Сен'джина.",
		["Wake {quest:5441} with the {item:16114}"] = "Разбудите батраков ({quest:5441}) предметом {item:16114}",
		["the {object:654925} on the ground beside her"] = "{object:654925} на земле рядом с ней",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} – к западу от Сен'джина. Три плана атаки лежат на земле среди шатров кентавров. {npc:275811} тоже в плену на утесе.",
		["{area:817}'s mouth"] = "Вход: {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, там, где вы начинаете",
		["{npc:12430} kneels behind the rocks just off the road south of {area:362}, on your way to the keep. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12430} стоит на коленях за камнями чуть в стороне от дороги к югу от места {area:362}, по пути к крепости. Наложите на нее {spell:613} (ранг 2), затем {spell:1243}: ранг 1 заклинания {spell:613} не засчитывается.",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809} разбил лагерь чуть к югу от места {area:362}. Сядьте у его костра (/sit), пока не появится эффект {spell:1229451}. Если вы изучили профессию, {npc:265809} также предлагает свое задание «Походное дело 101» – сдайте его учителю этой профессии: здесь ({area:362}) или в начале следующего руководства ({zone:1454}).",
		["{npc:265809}'s campfire"] = "Костер: {npc:265809}",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809}: для персонажа {npc:11025}",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809}: для персонажа {npc:11046}",
		["{npc:265809}: for {npc:11066}"] = "{npc:265809}: для персонажа {npc:11066}",
		["{npc:265809}: for {npc:2855}"] = "{npc:265809}: для персонажа {npc:2855}",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809}: для персонажа {npc:3175}",
		["{npc:265809}: for {npc:3365}"] = "{npc:265809}: для персонажа {npc:3365}",
		["{npc:265809}: for {npc:3404}"] = "{npc:265809}: для персонажа {npc:3404}",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809}: для персонажа {npc:5943}",
		["{npc:265809}: for {npc:7088}"] = "{npc:265809}: для персонажа {npc:7088}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: только для зачарователей – остаток получают, распыляя проклятые подвески",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} стоит на берегу к востоку от места {area:362}. Трезубец, знамя и кинжал лежат на пляже вокруг него.",
		["{npc:3102} hooves"] = "Копыта: {npc:3102}",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, снова здесь: {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, элитный морской великан",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} стоит сразу у входа в пещеру; {npc:3159} – в глубине пещеры за ним.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} ждет внутри Логова – здания чуть к западу от персонажа {npc:10176}.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, в сторожевой башне",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} лежит раненый у подножия холмов к северо-западу от Логова.",
		["{npc:3294}, by the inn"] = "{npc:3294}, у таверны",
		["{npc:3706}, beside {npc:266940}: the {item:16606}"] = "{npc:3706}, рядом с персонажем {npc:266940}: {item:16606}",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}, для персонажа {npc:6018} ({zone:1454}): сохраните задание",
		["{npc:3706}, in the barracks beside {npc:266940}"] = "{npc:3706}, в казарме рядом с персонажем {npc:266940}",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}, учитель жрецов, у Логова",
		["{npc:3707}, the priest trainer at the Den: for {npc:3706} in {area:362}"] = "{npc:3707}, учитель жрецов, у Логова: для персонажа {npc:3706} ({area:362})",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it."] = "{npc:5875} стоит здесь: {object:172960} – каньон под объектом {object:172982}. Отдайте ему {item:6535}, затем используйте предмет {item:7464} на круге призыва рядом с ним и одолейте демона Бездны, чтобы подчинить его.",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} стоит у Логова. {area:639} – холм чуть к югу: выпейте там {item:6635}, чтобы увидеть персонажа {npc:5891}, затем отнесите предмет {item:6656} {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} и ваш {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, ориентир: {area:639}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} стоит на дороге у восточного выхода из долины.",
		["{npc:9796} stands just outside the Den's entrance."] = "{npc:9796} стоит сразу у входа в Логово.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, у костра для готовки",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} стоит лагерем на холме к западу от пляжа наг, к югу от места {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "Главные ворота ({zone:1454}) – чуть к западу от места {area:817}. {npc:5875} стоит здесь: {object:172960} – каньон под местом {object:172982}.",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["/sit by her campfire until you get {spell:1229451}"] = "/sit у ее костра, пока не получите {spell:1229451}",
		["Ask {npc:10666} for his report"] = "Спросите отчет у персонажа {npc:10666}",
		["Ask {npc:1496} for his report"] = "Спросите отчет у персонажа {npc:1496}",
		["Ask {npc:251001} for his report"] = "Спросите отчет у персонажа {npc:251001}",
		["Back east along the road to {area:159}. {npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Назад по дороге на восток сюда: {area:159}. {npc:2128} (маги), {npc:2129} (жрецы), {npc:2127} (чернокнижники) и {npc:2130} (разбойники) стоят наверху в таверне: поднимитесь по лестнице внутри, Стрелка не различает этажи.",
		["Back to the church"] = "Назад к церкви",
		["Back to {area:154}"] = "Назад: {area:154}",
		["Back up the road and through {area:159} to its west end."] = "Назад по дороге через место {area:159} к его западной окраине.",
		["Back up the road to {area:159}, on the way north-west to {area:157}."] = "Назад по дороге сюда: {area:159}, по пути на северо-запад к месту {area:157}.",
		["Back up the road to {area:159}. {npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Назад по дороге сюда: {area:159}. {npc:2128} (маги), {npc:2129} (жрецы), {npc:2127} (чернокнижники) и {npc:2130} (разбойники) стоят наверху в таверне: поднимитесь по лестнице внутри, Стрелка не различает этажи.",
		["Beat {npc:6784} in the duel"] = "Победите на дуэли: {npc:6784}",
		["Below ground"] = "Под землей",
		["Crusader's Outpost"] = "Застава Алого Ордена",
		["Dry Branches"] = "Сухие ветки",
		["Eleanor camps just south-west of town. With a profession learned, she also offers its Camping 101, which its trainer takes: in {area:159}, at Linnea's camp, or in the {zone:1458} in the next guide."] = "Элеанор стоит лагерем чуть к юго-западу от городка. Если у вас изучена профессия, она также предлагает соответствующее задание «Основы походной жизни», которое принимает учитель этой профессии: в месте {area:159}, в лагере Линнеи или в городе {zone:1458} в следующем руководстве.",
		["Eleanor: for {npc:2114}"] = "Элеанор: для персонажа {npc:2114}",
		["Eleanor: for {npc:2132}"] = "Элеанор: для персонажа {npc:2132}",
		["Eleanor: for {npc:3523}"] = "Элеанор: для персонажа {npc:3523}",
		["Eleanor: for {npc:3549}"] = "Элеанор: для персонажа {npc:3549}",
		["Eleanor: for {npc:4586}"] = "Элеанор: для персонажа {npc:4586}",
		["Eleanor: for {npc:4598}"] = "Элеанор: для персонажа {npc:4598}",
		["Eleanor: for {npc:4605}"] = "Элеанор: для персонажа {npc:4605}",
		["Eleanor: for {npc:5695}"] = "Элеанор: для персонажа {npc:5695}",
		["Eleanor: for {npc:5759}"] = "Элеанор: для персонажа {npc:5759}",
		["Eleanor: for {npc:6289}"] = "Элеанор: для персонажа {npc:6289}",
		["Escort {npc:275954} out of the outpost"] = "Выведите {npc:275954} с заставы",
		["Everything here is inside the inn, through its door on the south side: {npc:5688} at the bar, {npc:265944} at the north end of the ground floor, the {npc:1931} in the cellar under that end, and {npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) upstairs: take the stairs inside, the arrow cannot tell the floors apart."] = "Все здесь внутри таверны, вход с южной стороны: {npc:5688} у стойки, {npc:265944} в северной части первого этажа, {npc:1931} в подвале под ней, а {npc:2128} (маги), {npc:2129} (жрецы), {npc:2127} (чернокнижники) и {npc:2130} (разбойники) наверху: поднимитесь по лестнице внутри, Стрелка не различает этажи.",
		["Follow the path north into {area:154}; Sarvis stands in front of the church."] = "Идите по тропе на север сюда: {area:154}; Сарвис стоит перед церковью.",
		["Follow the road east. Bleeding Horrors and Wandering Spirits haunt the graves on the east side of the farmstead, where the {quest:99142} grows: Linnea wants eight of each.\nThe Scarlet Friars camp just north-east of the graves; {npc:1664} stands among them.\nThe spiders lurk in the woods at the far east end of the glades."] = "Идите по дороге на восток. Кровоточащие ужасы и странствующие духи бродят у могил в восточной части фермы, где растет {quest:99142}: Линнее нужно по восемь каждых.\nКелейники из Алого ордена стоят лагерем чуть к северо-востоку от могил; {npc:1664} стоит среди них.\nПауки прячутся в лесу на дальнем востоке Тирисфальских лесов.",
		["Follow the road north-west to {area:157}. {npc:1657} walks the graveyard south of the mills; Nissa, Gregor and {npc:1656} haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop {item:2839}.\nCareful: Rotting undead and Darkeye Bonecasters near the Agamands can join a fight as adds."] = "Идите по дороге на северо-запад сюда: {area:157}. {npc:1657} бродит по кладбищу к югу от мельниц; Нисса, Грегор и {npc:1656} обитают на самих мельницах. Ребра падают с костетрясов-солдат и костеголовых солдат, черепа – с мрачнооких скелетов-заклинателей, а {item:2839} может упасть с любого.\nОсторожно: гниющая нежить и мрачноокие скелеты-заклинатели рядом с Агамандами могут вмешаться в бой.",
		["Follow the road south-east from {area:159} past the zeppelin towers."] = "Идите по дороге на юго-восток от места {area:159} мимо башен дирижаблей.",
		["Follow the road south-east from {area:159} past the zeppelin towers. Linnea, Kristof and {npc:3549} camp by the road."] = "Идите по дороге на юго-восток от места {area:159} мимо башен дирижаблей. Линнея, Кристоф и {npc:3549} стоят лагерем у дороги.",
		["Follow the road south-west from {area:159} to the Scarlet Crusade camp. {npc:1662} stands at its south end; every Scarlet there can drop a ring."] = "Идите по дороге на юго-запад от места {area:159} к лагерю Алого ордена. {npc:1662} стоит в его южной части; кольцо может упасть с любого воина Алого ордена.",
		["Greater Duskbats fly over the fields around {area:159} and along the road north: Gretchen wants their pelts, {npc:3549} their wings.\nThe {quest:5482} grows in the graveyard fields just north of {area:159}, where the Rot Hide Graverobbers dig; all the Rot Hides drop the ichor.\nThe Rot Hide Mongrels hold the hills further north. {npc:1753} (level 11) stands in their camp on the hill south of the shore: clear the gnolls around him first.\nCareful: Gnoll guards stand outside the hut and can join the fight. If you slip past them and fight him inside, he fights alone.\nThe Vile Fin murlocs line the north shore: they all drop the scales, and the Minor Oracles and Muckdwellers the skins for {npc:3549}."] = "Большие сумеречницы летают над полями вокруг места {area:159} и вдоль дороги на север: Гретхен нужны их шкурки, {npc:3549} – их крылья.\n{quest:5482} растет на кладбищенских полях чуть к северу от места {area:159}, где роются грабители могил из стаи Гнилошкуров; лимфа падает со всех Гнилошкуров.\nПолукровки из стаи Гнилошкуров занимают холмы дальше к северу. {npc:1753} (11-й уровень) стоит в их лагере на холме к югу от берега: сначала перебейте гноллов вокруг него.\nОсторожно: стражи-гноллы стоят у хижины и могут вмешаться. Если проскользнуть мимо них и сразиться с ним внутри, он будет один.\nМурлоки из племени Злобного Плавника занимают северный берег: чешуя падает со всех, а кожа для {npc:3549} – с младших оракулов и илистых жителей.",
		["Heal and fortify {npc:12428}"] = "Исцелите и укрепите: {npc:12428}",
		["Holland walks around the north side of {area:159}, a few steps from Dillinger."] = "Холланд ходит по северной части места {area:159}, в нескольких шагах от Диллинджера.",
		["Inside"] = "Внутри",
		["Leave {area:154} by the road north-east. {npc:6784} stands by the farmhouse at the {area:156}; {npc:1519} stands by the road just past it."] = "Покиньте место {area:154} по дороге на северо-восток. {npc:6784} стоит у дома фермы ({area:156}); {npc:1519} стоит у дороги чуть дальше.",
		["Listen to Leonid and {npc:246378}, then talk to him again"] = "Выслушайте Леонида и персонажа {npc:246378}, затем снова поговорите с ним",
		["Mindless Zombies"] = "Безмозглые зомби",
		["Offer aid to the {npc:246143}"] = "Предложите помощь: {npc:246143}",
		["Only if the letter dropped"] = "Только если выпало письмо",
		["Rattlecage Skeletons wander the ruined houses in the north half of {area:154}. Young Scavengers and Duskbats roam all around the village; the Ragged Scavengers and Mangy Duskbats are on its east side. {npc:1661} wants their paws and wings: kill them as you meet them while you clear the skeletons."] = "Скелеты-костетрясы бродят по разрушенным домам в северной половине места {area:154}. Молодые падальщики и сумеречницы бродят вокруг деревни; косматые падальщики и облезлые сумеречницы – в ее восточной части. {npc:1661} нужны их лапы и крылья: убивайте их по пути, пока зачищаете скелетов.",
		["Scarlet Warriors guard the outpost north-west of the pumpkin fields. {npc:275954} is held inside: talk to him and stay with him until he is out.\nCareful: Scarlet Warriors are level 6-7 and not elite. Once their health falls to 15% they run off to bring help, so more of them may join the fight."] = "Воины из Алого ордена охраняют заставу к северо-западу от тыквенных полей. {npc:275954} в плену внутри: поговорите с ним и оставайтесь рядом, пока он не выберется.\nОсторожно: воины Алого ордена 6-7-го уровня, не элита. При 15% здоровья они убегают за подмогой, так что к бою могут присоединиться другие.",
		["The Dry Branches lie on the ground around the south-west edge of {area:159}."] = "Сухие ветки лежат на земле у юго-западной окраины места {area:159}.",
		["The Scarlet Converts and Initiates hold the farm east of {area:154}. {npc:1919} wanders between the farmhouses: his remains are for {quest:6395}."] = "Новообращенные и посвященные из Алого ордена занимают ферму к востоку от места {area:154}. {npc:1919} бродит между домами фермы: его останки – для задания {quest:6395}.",
		["The Scarlet camp"] = "Лагерь Алого ордена",
		["The Scarlet farm"] = "Ферма Алого ордена",
		["The Wanted poster by the inn"] = "Плакат «Разыскивается» у таверны",
		["The pumpkins grow in the Scarlet-held fields just north-west of the farmhouse.\nCareful: Farmers stand close to the pumpkins, so you can pull more than one at once. Scarlet mobs are found around the edges of the farm and a bit to the northwest."] = "Тыквы растут на полях Алого ордена чуть к северо-западу от дома фермы.\nОсторожно: фермеры стоят рядом с тыквами, можно привлечь нескольких сразу. Бойцы Алого ордена встречаются по краям фермы и немного к северо-западу.",
		["The zombies shamble around the graveyard and the houses just east of the church."] = "Зомби бродят по кладбищу и у домов чуть к востоку от церкви.",
		["The {area:154} trainers stand around the church"] = "Учителя ({area:154}) стоят вокруг церкви",
		["The {area:159} trainers are in the inn ({npc:2131} downstairs, the rest upstairs); {npc:246152}, the Paladin trainer, by the square"] = "Учителя ({area:159}) – в таверне ({npc:2131} внизу, остальные наверху); {npc:246152}, учитель паладинов, у площади",
		["The {npc:1931}, in the inn's cellar"] = "{npc:1931}, в подвале таверны",
		["The {npc:2211}, in the inn's cellar"] = "{npc:2211}, в подвале таверны",
		["The {npc:246143}"] = "{npc:246143}",
		["The {object:164662} lie beside the ruined houses in the north of {area:154}."] = "{object:164662} лежат у разрушенных домов на севере места {area:154}.",
		["Tirisfal Pumpkins"] = "Тирисфальские тыквы",
		["Use the {item:286176} on five idle Deathguards around town"] = "Используйте предмет {item:286176} на пяти бездельничающих стражах смерти в городке",
		["Vile Fin Attackers"] = "Налетчики из племени Злобного Плавника",
		["Vile Fin Seers"] = "Провидцы из племени Злобного Плавника",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:4568} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "Идите на юг от места {area:159} сюда: {area:153} и спуститесь в город {zone:1458}. {npc:4568} стоит здесь: {object:36082}. Лагерь Алого ордена – чуть к западу от руин.",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:5675} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "Идите на юг от места {area:159} сюда: {area:153} и спуститесь в город {zone:1458}. {npc:5675} стоит здесь: {object:36082}. Лагерь Алого ордена – чуть к западу от руин.",
		["You rise in the crypt at the south end of {area:154}. {npc:1568} waits just outside."] = "Вы восстаете в склепе в южной части места {area:154}. {npc:1568} ждет сразу снаружи.",
		["{item:16333}, from {npc:1919}"] = "{item:16333}, с персонажа {npc:1919}",
		["{item:2320} from {npc:2118}, for Gretchen"] = "{item:2320} у персонажа {npc:2118}, для Гретхен",
		["{item:2839}, a rare drop"] = "{item:2839}, редкая добыча",
		["{item:7227}, in the farmstead's garden"] = "{item:7227}, в саду фермы",
		["{npc:12428} kneels by the north gate of {area:159}'s graveyard, on your way north. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Fortitude first does not count."] = "{npc:12428} стоит на коленях у северных ворот кладбища ({area:159}), по пути на север. Примените к нему {spell:613} (ранг 2), затем {spell:1243}: если сначала наложить «Стойкость», это не засчитывается.",
		["{npc:1495}'s camp"] = "Лагерь: {npc:1495}",
		["{npc:1496} and {npc:1742} stand at the west end of {area:159}, where the road from Solliden comes in."] = "{npc:1496} и {npc:1742} стоят на западной окраине места {area:159}, где входит дорога от фермы Соллиден.",
		["{npc:1499}, in the town hall"] = "{npc:1499}, в ратуше",
		["{npc:1500}, in the inn"] = "{npc:1500}, в таверне",
		["{npc:1515}, in front of the inn"] = "{npc:1515}, перед таверной",
		["{npc:1518} is in the apothecary's house on the west side of the square, {npc:1515} in front of the inn with the Wanted poster beside him, {npc:1499} in the town hall on the square's north side. The inn comes last, in one go."] = "{npc:1518} – в доме аптекаря на западной стороне площади, {npc:1515} – перед таверной, рядом с ним плакат «Разыскивается», {npc:1499} – в ратуше на северной стороне площади. Таверна – в конце, за один заход.",
		["{npc:1525} and Ravaged Corpses shamble through the fields just west of {area:159}; Decrepit Darkhounds roam there and on west along the road toward {npc:10666}. Johaan wants their blood, {npc:3549} their hides."] = "{npc:1525} и изуродованные трупы бродят по полям чуть к западу от места {area:159}; дряхлые псы тьмы бродят там и дальше на запад вдоль дороги к персонажу {npc:10666}. Йохану нужна их кровь, {npc:3549} – их шкуры.",
		["{npc:1560}, in the inn"] = "{npc:1560}, в таверне",
		["{npc:1569}: the scroll for {npc:244808}"] = "{npc:1569}: свиток для {npc:244808}",
		["{npc:1570}, in the church"] = "{npc:1570}, в церкви",
		["{npc:2114}, beside Johaan: {quest:97957}"] = "{npc:2114}, рядом с Йоханом: {quest:97957}",
		["{npc:2122}, the rogue trainer"] = "{npc:2122}, учитель разбойников",
		["{npc:2123}, the priest trainer in the church"] = "{npc:2123}, учитель жрецов, в церкви",
		["{npc:2123}, the priest trainer in the church, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him now: the wounded guard Beryl sends you to needs it."] = "{npc:2123}, учитель жрецов, в церкви, отправляет вас к персонажу {npc:2129} ({area:159}). Изучите у него {spell:613} (ранг 2) сейчас: это понадобится для раненого стражника, к которому вас отправит Берил.",
		["{npc:2123}: for {npc:2129} in {area:159}"] = "{npc:2123}: для персонажа {npc:2129} ({area:159})",
		["{npc:2124}, the mage trainer, in the church"] = "{npc:2124}, учитель магов, в церкви",
		["{npc:2126}, the warlock trainer"] = "{npc:2126}, учитель чернокнижников",
		["{npc:2128} (mages), {npc:2129} (priests), {npc:2127} (warlocks) and {npc:2130} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:2128} (маги), {npc:2129} (жрецы), {npc:2127} (чернокнижники) и {npc:2130} (разбойники) стоят наверху в таверне: поднимитесь по лестнице внутри, Стрелка не различает этажи.",
		["{npc:2128}: {npc:4568} in the {zone:1458} takes it"] = "{npc:2128}: задание принимает {npc:4568} ({zone:1458})",
		["{npc:2129}, upstairs"] = "{npc:2129}, наверху",
		["{npc:2129}, upstairs: the {item:16607}"] = "{npc:2129}, наверху: {item:16607}",
		["{npc:2132}, beside Johaan: {quest:97951}"] = "{npc:2132}, рядом с Йоханом: {quest:97951}",
		["{npc:246152}, the Paladin trainer"] = "{npc:246152}, учитель паладинов",
		["{npc:265944}, at the inn's north end: Camping 101 asks you to learn it"] = "{npc:265944}, в северной части таверны: задание «Основы походной жизни» требует его изучить",
		["{npc:3523}, by the road west of {area:159}: {quest:97961}"] = "{npc:3523}, у дороги к западу от места {area:159}: {quest:97961}",
		["{npc:5759}, by the bar: {quest:97955}"] = "{npc:5759}, у стойки: {quest:97955}",
		["{npc:6289}, beside {npc:3549}: {quest:97960}"] = "{npc:6289}, рядом с персонажем {npc:3549}: {quest:97960}",
		["{npc:6390} waits in the mausoleum on the hill just north of town: open the gate and fight him."] = "{npc:6390} ждет в склепе на холме чуть к северу от городка: откройте ворота и сразитесь с ним.",
		["{npc:6784} stands by the farmhouse at the {area:156}, on the way to the Crusader's Outpost."] = "{npc:6784} стоит у дома фермы ({area:156}), по пути к заставе Алого ордена.",
		["{object:1661} is under the {area:153}, beside the zeppelin towers. {npc:5675} is in the {object:36082}: use the {item:6284} on the summoning circle beside him and defeat the voidwalker. {npc:4606} is in the {object:36070}. {npc:4568} is in the {object:36082} too."] = "{object:1661} – под местом {area:153}, рядом с башнями дирижаблей. {npc:5675} – здесь: {object:36082}: используйте предмет {item:6284} на круге призыва рядом с ним и одолейте демона Бездны. {npc:4606} – здесь: {object:36070}. {npc:4568} – тоже здесь: {object:36082}.",
		["{object:178090} is in the {area:154} graveyard, beside the church."] = "{object:178090} – на кладбище ({area:154}), у церкви.",
		["{object:37098} stands beside {npc:1662} at the camp's south end."] = "{object:37098} стоит рядом с персонажем {npc:1662} в южной части лагеря.",
} end)()
t.guides["forever/legacy/legacy-challenges"] = (function() return {
		["Adventure: explore the world map"] = "Приключения: исследуйте карту мира",
		["Adventure: {npc:16042}"] = "Приключения: {npc:16042}",
		["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "Классы дают 27 очков: каждый класс на уровнях 25, 45 и 60. Каждый класс засчитывается один раз на учетную запись, так что второй персонаж уже прокачанного класса ничего не добавит, а новый класс – добавит. Первый персонаж, достигший 25-го уровня, обычно и открывает Систему наследия.",
		["Classes: level 25"] = "Классы: уровень 25",
		["Classes: level 45"] = "Классы: уровень 45",
		["Classes: level 60"] = "Классы: уровень 60",
		["Dire Maul East"] = "Забытый Город: восток",
		["Dire Maul North"] = "Забытый Город: север",
		["Dire Maul West"] = "Забытый Город: запад",
		["Dungeons: level 15-25"] = "Подземелья: уровни 15-25",
		["Dungeons: level 26-45"] = "Подземелья: уровни 26-45",
		["Dungeons: level 46-60"] = "Подземелья: уровни 46-60",
		["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "Каждая профессия производства дает 3 очка: на 150, 225 и 300. Ранги засчитываются один раз на профессию для всей учетной записи. Следуйте гайду Polestar «{skill:171} 1-300» (Профессии). Профессия производства на 150 также открывает Систему наследия.",
		["Follow the Polestar guide \"{skill:164} 1-300\" (Professions)."] = "Следуйте гайду Polestar «{skill:164} 1-300» (Профессии).",
		["Follow the Polestar guide \"{skill:165} 1-300\" (Professions)."] = "Следуйте гайду Polestar «{skill:165} 1-300» (Профессии).",
		["Follow the Polestar guide \"{skill:197} 1-300\" (Professions)."] = "Следуйте гайду Polestar «{skill:197} 1-300» (Профессии).",
		["Follow the Polestar guide \"{skill:202} 1-300\" (Professions)."] = "Следуйте гайду Polestar «{skill:202} 1-300» (Профессии).",
		["Follow the Polestar guide \"{skill:333} 1-300\" (Professions)."] = "Следуйте гайду Polestar «{skill:333} 1-300» (Профессии).",
		["Legacy Challenges"] = "Испытания наследия",
		["Level 45 with this character's class."] = "45-й уровень этим классом персонажа.",
		["Level 60 with this character's class."] = "60-й уровень этим классом персонажа.",
		["Lower {area:1583}"] = "{area:1583}: нижняя часть",
		["PvP: Field of Honor"] = "PvP: Field of Honor",
		["PvP: battleground reputations (Alliance)"] = "PvP: репутация полей боя (Альянс)",
		["PvP: battleground reputations (Horde)"] = "PvP: репутация полей боя (Орда)",
		["PvP: honor ranks"] = "PvP: звания чести",
		["Raids: Barrow Deeps"] = "Рейды: Barrow Deeps",
		["Raids: Hyjal Summit"] = "Рейды: Вершина Хиджала",
		["Raids: {npc:10184}"] = "Рейды: {npc:10184}",
		["Ranks 3, 7, 10, 13 and 14 are a point each. Polestar cannot read your highest rank yet, so tick each one off yourself. Forever's honor rules for reaching a rank have not been published in detail; in Classic, ranks come from your weekly honor standing, and 13-14 take many weeks of top standing."] = "Звания 3, 7, 10, 13 и 14 дают по очку. Polestar пока не видит ваше высшее звание, так что отмечайте их сами. Правила чести Forever для получения званий подробно не опубликованы; в Classic звание зависит от еженедельного места по чести, а для 13-14 нужно много недель на вершине.",
		["The Field of Honor PvP season has weekly journey quests; finishing the ones for weeks 4, 7 and 10 is a point each. These quests are new in Forever and not in our data, so tick each one off yourself."] = "В PvP-сезоне Field of Honor есть еженедельные задания; выполнение заданий 4-й, 7-й и 10-й недель дает по очку. Эти задания – новые в Forever, их нет в наших данных, так что отмечайте их сами.",
		["This step cannot check the whole map by itself yet; it becomes a tracked goal once the Legacy achievement ids are recorded."] = "Этот шаг пока не может сам проверить всю карту; он станет отслеживаемой целью, когда будут записаны ID достижений наследия.",
		["Tradeskills: {skill:164}"] = "Профессии: {skill:164}",
		["Tradeskills: {skill:165}"] = "Профессии: {skill:165}",
		["Tradeskills: {skill:171}"] = "Профессии: {skill:171}",
