t.guides["forever/professions/enchanting"] = (function() return {
		["Apprentice {skill:333} lets you craft up to 75 for 10c, at any character level. Not every {skill:333} trainer teaches it: Alliance {npc:3606} ({zone:1438}), {npc:11068} ({zone:1453}), {npc:257004} (Zephras Isle), {npc:11070} ({zone:1457}), {npc:257020} (Zephras Isle) and {npc:11065} ({zone:1455}); Horde {npc:257004} (Zephras Isle), {npc:11066} ({zone:1454}), {npc:11067} ({zone:1458}), {npc:11071} ({zone:1456}), {npc:257020} (Zephras Isle), {npc:266881} ({zone:1411}) and {npc:5695} ({zone:1420}). The arrow picks the nearest of your faction. Buy a {item:6217} and {item:247786} from an enchanting supplies vendor (in the capitals and on Zephras Isle; the starting-area trainers have none beside them, and the next step's arrow picks the nearest). From now on, disenchant every green you do not wear: that is where the dust and essences come from. Two starter quests teach Disenchant on a quest item: An Enchanting Lesson from {npc:11072} ({area:91}, {zone:1429}) and A Pain in the Neck from {npc:266881} ({area:367}, {zone:1411}). 1-75 takes about 50c of recipes and 4s 44c of vendor goods, plus 51 {item:10940} to gather or buy."] = "Ранг «Ученик» ({skill:333}) позволяет создавать предметы до 75 за 10м, на любом уровне персонажа. Учат ему не все учителя ({skill:333}): Альянс – {npc:3606} ({zone:1438}), {npc:11068} ({zone:1453}), {npc:257004} (Остров Зефрис), {npc:11070} ({zone:1457}), {npc:257020} (Остров Зефрис) и {npc:11065} ({zone:1455}); Орда – {npc:257004} (Остров Зефрис), {npc:11066} ({zone:1454}), {npc:11067} ({zone:1458}), {npc:11071} ({zone:1456}), {npc:257020} (Остров Зефрис), {npc:266881} ({zone:1411}) и {npc:5695} ({zone:1420}). Стрелка выбирает ближайшего для вашей фракции. Купите {item:6217} и {item:247786} у торговца товарами для зачаровывания (в столицах и на Острове Зефрис; рядом с учителями в стартовых зонах таких нет, и стрелка следующего шага выбирает ближайшего). С этого момента разрушайте чары на каждом зеленом предмете, который не носите: оттуда берутся пыль и эссенции. Два стартовых задания обучают «Разрушению чар» на предмете задания: «Очаровательный урок» от NPC {npc:11072} ({area:91}, {zone:1429}) и «Подчиняющие подвески» от NPC {npc:266881} ({area:367}, {zone:1411}). На 1-75 уйдет около 50м на рецепты и 4с 44м на товары торговцев, плюс 51 {item:10940} – добудьте или купите.",
		["Artisan {skill:333}"] = "{skill:333}: Искусник",
		["Expert {skill:333}"] = "{skill:333}: Умелец",
		["Journeyman raises the cap from 75 to 150 for 5s (Classic's price; Forever's is not in the data); it needs {skill:333} 50 and character level 10, so you can take it on any visit from 50. Not every {skill:333} trainer teaches it: Alliance {npc:5157} ({zone:1455}), {npc:1317} ({zone:1453}), {npc:4213} ({zone:1457}) and {npc:7949} ({zone:1444}); Horde {npc:3345} ({zone:1454}), {npc:4616} ({zone:1458}) and {npc:3011} ({zone:1456}). The arrow picks the nearest of your faction. Learn now: {spell:7771} (from 70, 2s). 75-150 takes about 2s of recipes, plus 1 {item:1210}, 1 {item:6338}, 4 {item:10938}, 121 {item:10940} and 20 {item:11083} to gather or buy."] = "Ранг «Подмастерье» поднимает предел с 75 до 150 за 5с (цена Classic; цены Forever нет в данных); нужен навык {skill:333} 50 и уровень персонажа 10, так что его можно взять при любом визите начиная с 50. Учат ему не все учителя ({skill:333}): Альянс – {npc:5157} ({zone:1455}), {npc:1317} ({zone:1453}), {npc:4213} ({zone:1457}) и {npc:7949} ({zone:1444}); Орда – {npc:3345} ({zone:1454}), {npc:4616} ({zone:1458}) и {npc:3011} ({zone:1456}). Стрелка выбирает ближайшего для вашей фракции. Изучите сейчас: {spell:7771} (с 70, 2с). На 75-150 уйдет около 2с на рецепты, плюс 1 {item:1210}, 1 {item:6338}, 4 {item:10938}, 121 {item:10940} и 20 {item:11083} – добудьте или купите.",
		["Journeyman {skill:333}"] = "{skill:333}: Подмастерье",
		["a tool: keep it in your bags"] = "инструмент: держите его в сумке",
		["from the recipe in your bags"] = "по рецепту из сумки",
		["{item:5500} (Alliance)"] = "{item:5500} (Альянс)",
		["{item:5500} (Horde)"] = "{item:5500} (Орда)",
		["{item:8831} (Alliance)"] = "{item:8831} (Альянс)",
		["{item:8831} (Horde)"] = "{item:8831} (Орда)",
		["{skill:333} recipes at 130"] = "{skill:333}: рецепты на 130",
		["{spell:7418} to 25"] = "{spell:7418} до 25",
} end)()
t.guides["forever/professions/engineering"] = (function() return {
		["19 {item:2592} for {spell:3953}: humanoids of level 15-30 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House."] = "19 {item:2592} для {spell:3953}: падает с гуманоидов 15-30 уровня. Сохраняйте то, что добываете при прокачке, берите из банка или покупайте на аукционе.",
		["24 {item:14047} for {item:15994}: humanoids of level 45-60 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House."] = "24 {item:14047} для {item:15994}: падает с гуманоидов 45-60 уровня. Сохраняйте то, что добываете при прокачке, берите из банка или покупайте на аукционе.",
		["Artisan {skill:202}"] = "{skill:202}: Искусник",
		["Expert raises the cap from 150 to 225 for 50s (Classic's price; Forever's is not in the data); it needs {skill:202} 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance {npc:5174} ({zone:1455}); Horde {npc:11017} ({zone:1454}). The arrow picks the nearest of your faction. Learn now: {spell:9271} (from 150) and {spell:3953} (from 145). 150-225 takes about 31s of vendor goods, plus 19 {item:2319}, 19 {item:2592}, 31 {item:2836}, 74 {item:2838}, 100 {item:2841}, 6 {item:2842}, 81 {item:3575}, 19 {item:3860} and 62 {item:7912} to gather or buy."] = "Ранг «Умелец» поднимает предел со 150 до 225 за 50с (цена Classic; цены Forever нет в данных); нужен навык {skill:202} 125 и уровень персонажа 20, так что его можно взять при любом визите начиная со 125. Учат ему лишь немногие: Альянс – {npc:5174} ({zone:1455}); Орда – {npc:11017} ({zone:1454}). Стрелка выбирает ближайшего для вашей фракции. Изучите сейчас: {spell:9271} (со 150) и {spell:3953} (со 145). На 150-225 уйдет около 31с на товары торговцев, плюс 19 {item:2319}, 19 {item:2592}, 31 {item:2836}, 74 {item:2838}, 100 {item:2841}, 6 {item:2842}, 81 {item:3575}, 19 {item:3860} и 62 {item:7912} – добудьте или купите.",
		["Expert {skill:202}"] = "{skill:202}: Умелец",
		["Journeyman raises the cap from 75 to 150 for 5s (Classic's price; Forever's is not in the data); it needs {skill:202} 50 and character level 10, so you can take it on any visit from 50. Not every {skill:202} trainer teaches it: Alliance {npc:1676} ({zone:1431}), {npc:5518} ({zone:1453}) and {npc:11029} ({zone:1455}); Horde {npc:11031} ({zone:1458}) and {npc:3412} ({zone:1454}). The arrow picks the nearest of your faction. Learn now: {spell:3929} (from 75, 2s 50c) and {spell:3930} (from 75, 2s 50c). 75-150 takes about 5s of recipes and 45s of vendor goods, plus 15 {item:2836}, 27 {item:2838}, 72 {item:2840}, 61 {item:2841} and 2 {item:2842} to gather or buy."] = "Ранг «Подмастерье» поднимает предел с 75 до 150 за 5с (цена Classic; цены Forever нет в данных); нужен навык {skill:202} 50 и уровень персонажа 10, так что его можно взять при любом визите начиная с 50. Учат ему не все учителя ({skill:202}): Альянс – {npc:1676} ({zone:1431}), {npc:5518} ({zone:1453}) и {npc:11029} ({zone:1455}); Орда – {npc:11031} ({zone:1458}) и {npc:3412} ({zone:1454}). Стрелка выбирает ближайшего для вашей фракции. Изучите сейчас: {spell:3929} (с 75, 2с 50м) и {spell:3930} (с 75, 2с 50м). На 75-150 уйдет около 5с на рецепты и 45с на товары торговцев, плюс 15 {item:2836}, 27 {item:2838}, 72 {item:2840}, 61 {item:2841} и 2 {item:2842} – добудьте или купите.",
		["Journeyman {skill:202}"] = "{skill:202}: Подмастерье",
		["a tool: keep it in your bags"] = "инструмент: держите его в сумке",
		["from the recipe in your bags"] = "по рецепту из сумки",
		["{item:10512} to 225"] = "{item:10512} до 225",
		["{item:10512} to 245"] = "{item:10512} до 245",
		["{item:16000} to 300"] = "{item:16000} до 300",
		["{item:16047} teaches {item:16000} ({skill:202} 275) for 1g 60s. Sold by {npc:260565} ({zone:2548}) and {npc:11185} ({zone:1452}), limited stock."] = "{item:16047} обучает: {item:16000} ({skill:202} 275), стоит 1з 60с. Продают {npc:260565} ({zone:2548}) и {npc:11185} ({zone:1452}), запас ограничен.",
		["{item:2319} (Alliance)"] = "{item:2319} (Альянс)",
		["{item:2319} (Horde)"] = "{item:2319} (Орда)",
		["{item:2836} (Alliance)"] = "{item:2836} (Альянс)",
		["{item:2836} (Horde)"] = "{item:2836} (Орда)",
		["{item:2838} (Alliance)"] = "{item:2838} (Альянс)",
		["{item:2838} (Horde)"] = "{item:2838} (Орда)",
		["{item:7912} (Alliance)"] = "{item:7912} (Альянс)",
		["{item:7912} (Horde)"] = "{item:7912} (Орда)",
		["{skill:202} recipes at 125"] = "{skill:202}: рецепты на 125",
		["{skill:202} recipes at 175"] = "{skill:202}: рецепты на 175",
		["{skill:202} recipes at 210"] = "{skill:202}: рецепты на 210",
		["{skill:202} recipes at 245"] = "{skill:202}: рецепты на 245",
		["{spell:3953} to 175"] = "{spell:3953} до 175",
		["{spell:3967} is yellow at 191 (yellow 190, green 210, grey 230): about 27 crafts to 210. Each takes 3 {item:3575}, 3 {spell:3945} and 1 {spell:3973} and makes 2. Make the 74 {spell:3945} and 30 {spell:3973} (6 crafts) first. Use the 7 {spell:3945} you made earlier; the counts above leave them out. A {item:2842} makes five Silver Contacts (grey by now: no points, but no trip to a vendor either); the {spell:3945} comes from {item:2838}. Each craft makes two bombs. Specialisation (optional): at 200 and character level 30, {npc:5174} ({zone:1455}), {npc:5518} ({zone:1453}), {npc:4586} ({zone:1458}) or Tinkerwiz ({area:392}) sends you to {spell:20220} ({npc:7944}, {zone:1455}, or {npc:7406}, {area:35}: 6 Mithril Tubes, an {item:4407} and 2 Advanced Target Dummies) or Goblin Engineering ({npc:8126}, {area:976}: 20 Big Iron Bombs, 20 {item:10507} and 5 {npc:2675}). The {item:4407} schematic now binds when picked up, but the quest takes a scope someone else made. The membership card lasts 14 days of play; renewing it costs 2g. You can take only one; neither is needed for 300, and the beta never tested them (it stopped at level 30). Needs an anvil nearby. {item:2842} (6 for 150-225): {skill:186}: smelt {item:2775}; or the Auction House. {item:3575} (81 for 150-225): {skill:186}: smelt {item:2772}; or the Auction House."] = "{spell:3967}: желтый на 191 (желтый 190, зеленый 210, серый 230): около 27 изготовлений до 210. Каждое требует 3 {item:3575}, 3 {spell:3945} и 1 {spell:3973} и дает 2 шт. Сначала сделайте 74 {spell:3945} и 30 {spell:3973} (6 изготовлений). Используйте 7 {spell:3945}, сделанных ранее; в подсчете выше они не учтены. Из {item:2842} выходит пять серебряных контактов (уже серые: очков нет, зато не нужно идти к торговцу); {spell:3945} делается из {item:2838}. Каждое изготовление дает две бомбы. Специализация (необязательно): на 200 и уровне персонажа 30 {npc:5174} ({zone:1455}), {npc:5518} ({zone:1453}), {npc:4586} ({zone:1458}) или Оловень ({area:392}) направит вас к {spell:20220} ({npc:7944}, {zone:1455}, или {npc:7406}, {area:35}: 6 мифриловых трубок, {item:4407} и 2 улучшенных тренировочных манекена) или к гоблинской инженерии ({npc:8126}, {area:976}: 20 больших железных бомб, 20 {item:10507} и 5 {npc:2675}). Схема {item:4407} теперь становится персональной при получении, но для задания годится прицел, сделанный другим игроком. Членская карта действует 14 дней игрового времени; продление стоит 2з. Можно выбрать только одну; ни одна не нужна для 300, и на бете их не проверяли (она заканчивалась на уровне 30). Нужна наковальня рядом. {item:2842} (6 на 150-225): {skill:186}: выплавьте из {item:2775}; или аукцион. {item:3575} (81 на 150-225): {skill:186}: выплавьте из {item:2772}; или аукцион.",
} end)()
t.guides["forever/professions/first-aid"] = (function() return {
		["Any {skill:129} trainer of your faction teaches Apprentice {skill:129} (any character level, 1s); the arrow picks the nearest. Forever teaches {item:118} with it: {item:2447}, {item:2678} and an {item:3371}, orange to 55. With {skill:182} it can replace the Linen Bandages below."] = "Любой учитель навыка {skill:129} вашей фракции обучает уровню «Ученик» ({skill:129}) (любой уровень персонажа, 1с); стрелка указывает на ближайшего. На Forever вместе с ним изучается {item:118}: {item:2447}, {item:2678} и {item:3371}, оранжевый до 55. С навыком {skill:182} это может заменить льняные бинты ниже.",
		["Artisan {skill:129}"] = "{skill:129}: искусник",
		["Artisan {skill:129} comes from the {quest:6622} quest. It needs skill 225 and level 35; the {skill:129} trainer in {zone:1454} sends you to the doctor in {area:321}. Bring the Mageweave (about 74) and {item:14047} (about 65) for 225-300 now: bandages need no fire, so you craft 225-300 beside the doctor, who teaches the Artisan bandages."] = "Уровень «Искусник» ({skill:129}) дает задание {quest:6622}. Нужен навык 225 и уровень 35; учитель навыка {skill:129} — {zone:1454} — отправит вас к доктору ({area:321}). Возьмите сразу магическую ткань (около 74) и {item:14047} (около 65) для 225-300: бинтам не нужен огонь, так что 225-300 вы прокачаете рядом с доктором, который обучает бинтам искусника.",
		["Artisan {skill:129} comes from the {quest:6624} quest. It needs skill 225 and level 35; the {skill:129} trainer in {zone:1455} sends you to the doctor in Theramore. Bring the Mageweave (about 74) and {item:14047} (about 65) for 225-300 now: bandages need no fire, so you craft 225-300 beside the doctor, who teaches the Artisan bandages."] = "Уровень «Искусник» ({skill:129}) дает задание {quest:6624}. Нужен навык 225 и уровень 35; учитель навыка {skill:129} — {zone:1455} — отправит вас к доктору в Терамор. Возьмите сразу магическую ткань (около 74) и {item:14047} (около 65) для 225-300: бинтам не нужен огонь, так что 225-300 вы прокачаете рядом с доктором, который обучает бинтам искусника.",
		["Buy and read {item:16084} (Expert {skill:129})"] = "Купите и прочтите {item:16084} (уровень «Умелец», {skill:129})",
		["Expert {skill:129}"] = "{skill:129}: умелец",
		["Expert {skill:129} raises the cap to 225; it needs skill 125 and character level 20: it is a book, {item:16084} (1g); the arrow picks its nearest seller for your faction. Buy it and read it. The same vendor sells the Heavy Silk and {item:8544} manuals (22s and 50s): buy both now, you read them at 180 and 210."] = "Уровень «Умелец» ({skill:129}) повышает предел до 225; нужен навык 125 и уровень персонажа 20: это книга {item:16084} (1з); стрелка указывает на ближайшего продавца вашей фракции. Купите и прочтите ее. Тот же торговец продает руководства по плотным шелковым бинтам и {item:8544} (22с и 50с): купите оба сейчас, прочтете их на 180 и 210.",
		["Journeyman {skill:129}"] = "{skill:129}: подмастерье",
		["Journeyman {skill:129} raises the cap to 150; it needs skill 50 and no character level: the arrow picks the nearest {skill:129} trainer of your faction; training costs 5s."] = "Уровень «Подмастерье» ({skill:129}) повышает предел до 150; нужен навык 50, уровень персонажа не требуется: стрелка указывает на ближайшего учителя навыка {skill:129} вашей фракции; обучение стоит 5с.",
		["Learn {skill:129}"] = "Изучите: {skill:129}",
		["Trauma"] = "Травма",
		["{item:1251} is orange from 1 (yellow at 30, green at 45, grey at 60): about 41 crafts to 40. Bandages need no fire: craft them anywhere. At 20 the trainer also teaches {item:279968} (1s; the Camping 101: {skill:129} quest at your starting area's camp teaches it free), Forever's camping item for {skill:129}: three Linen Bandages and a {item:159}; it gives a few points until 25."] = "{item:1251} — оранжевый с 1 (желтый с 30, зеленый с 45, серый с 60): около 41 изготовления до 40. Бинтам не нужен огонь: делайте их где угодно. На 20 учитель также обучает рецепту {item:279968} (1с; задание «Camping 101: {skill:129}» в лагере стартовой зоны обучает бесплатно) — походный предмет Forever для навыка {skill:129}: три льняных бинта и {item:159}; дает немного очков до 25.",
		["{item:1251}: cloth"] = "{item:1251}: ткань",
		["{item:14047} drops from humanoids of level 45-60: keep what you loot as you level, take it from your bank, or buy it at the Auction House."] = "{item:14047} падает с гуманоидов 45-60 уровня: сохраняйте то, что добываете при прокачке, берите из банка или покупайте на аукционе.",
		["{item:14529} is yellow from 260 (yellow at 260, green at 290, grey at 320): about 65 crafts to 300. Bandages need no fire: craft them anywhere. {item:14529} turns green at 290, yet to 300 it takes about the same {item:14047} as switching to {item:14530} (the doctor teaches it at 290): one recipe is enough."] = "{item:14529} — желтый с 260 (желтый с 260, зеленый с 290, серый с 320): около 65 изготовлений до 300. Бинтам не нужен огонь: делайте их где угодно. {item:14529} зеленеет на 290, но до 300 уходит примерно столько же ткани ({item:14047}), сколько при переходе на {item:14530} (доктор обучает на 290): хватит одного рецепта.",
		["{item:14529}: cloth"] = "{item:14529}: ткань",
		["{item:2581} is orange from 40 (yellow at 50, green at 75, grey at 100): about 10 crafts to 50. Bandages need no fire: craft them anywhere. Any {skill:129} trainer of your faction teaches it from skill 40 for 1s; the arrow picks the nearest."] = "{item:2581} — оранжевый с 40 (желтый с 50, зеленый с 75, серый с 100): около 10 изготовлений до 50. Бинтам не нужен огонь: делайте их где угодно. Любой учитель навыка {skill:129} вашей фракции обучает этому с навыка 40 за 1с; стрелка указывает на ближайшего.",
		["{item:2581} is yellow from 50 (yellow at 50, green at 75, grey at 100): about 46 crafts to 80. Bandages need no fire: craft them anywhere. Herbalists: {item:858} (from 55, 1s 50c; {item:2450}, two {item:2678} and an {item:3371}) is orange to 85."] = "{item:2581} — желтый с 50 (желтый с 50, зеленый с 75, серый с 100): около 46 изготовлений до 80. Бинтам не нужен огонь: делайте их где угодно. Травникам: {item:858} (с 55, 1с 50м; {item:2450}, два {item:2678} и {item:3371}) — оранжевый до 85.",
		["{item:2581}: cloth"] = "{item:2581}: ткань",
